// ── INJECT GLOBAL MOBILE STYLES ───────────────────────────────────────────
(function injectMobileStyles() {
  if (typeof document === "undefined") return;
  const id = "nfl-mobile-styles";
  if (document.getElementById(id)) return;
  const style = document.createElement("style");
  style.id = id;
  style.textContent = `
    html, body { background: #000000 !important; margin: 0; padding: 0; }
    button:active, a:active { transform: scale(0.97); transition: transform 0.08s ease; }
    .nfl-hscroll::-webkit-scrollbar { display: none; }
    .nfl-hscroll { -ms-overflow-style: none; scrollbar-width: none; }
    .nfl-bottom-nav { padding-bottom: env(safe-area-inset-bottom, 0px); }
  `;
  document.head.appendChild(style);
})();
  // ── INJECT GOOGLE FONTS ───────────────────────────────────────────────────
  (function injectFonts() {
    if (typeof document === "undefined") return;
    if (document.getElementById("nfl-google-fonts")) return;
    const link = document.createElement("link");
    link.id   = "nfl-google-fonts";
    link.rel  = "stylesheet";
    link.href = "https://fonts.googleapis.com/css2?family=Cooper+Black&family=Inter:wght@400;500;600&display=swap";
    document.head.appendChild(link);
  })();

