function ManagerLogo({ name, size = 24 }) {
  const team = MANAGER_NFL_TEAM[name];
  if (!team) return null;
  const teamData = DATA.nflTeams[team];
  if (!teamData) return null;
  const svgStr = NFL_LOGOS[team];
  if (svgStr) {
    if (svgStr.startsWith('<svg')) {
      const dataUrl = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svgStr)}`;
      return (
        <img src={dataUrl} width={size} height={size} alt={team}
          style={{ display:"inline-block", verticalAlign:"middle", flexShrink:0 }} />
      );
    }
    if (svgStr.startsWith('<img')) {
      const srcMatch = svgStr.match(/src="([^"]+)"/);
      if (srcMatch) {
        return (
          <img src={srcMatch[1]} width={size} height={size} alt={team}
            style={{ display:"inline-block", verticalAlign:"middle", flexShrink:0, objectFit:"contain" }} />
        );
      }
    }
  }
  // Fallback: colored abbr badge
  return (
    <span style={{ display:"inline-flex", alignItems:"center", justifyContent:"center", flexShrink:0,
      width:size, height:size, borderRadius:3, background:teamData.color||"#1a1a1a",
      fontSize:size*0.38, fontWeight:700, color:teamData.secondary||"#fff", verticalAlign:"middle" }}>
      {teamData.abbr||"NFL"}
    </span>
  );
}
