const ALUMNI = new Set(["Spencer Hower","Casey Rhoda","Tim Hoekstra","Jonathon Israel","Jon Vander Molen","Ben de Ruiter","Zac Dewey","Tommy Van Groningen"]);
const mgr = (name) => ALUMNI.has(name) ? `${name} 💀🪦⚰️` : name;
const firstName = (name) => {
  const parts = name.split(" ");
  const first = parts[0];
  const SHARED_FIRST = ["Greg"];
  if (SHARED_FIRST.includes(first) && parts.length > 1) return `${first} ${parts[parts.length - 1][0]}.`;
  return first;
}
;
const shortMgr = (name, mobile) => {
  if (!mobile) return mgr(name);
  const short = firstName(name);
  return ALUMNI.has(name) ? `${short} 💀` : short;
};

// ── HELPERS ──────────────────────────────────────────────────────────────────
const pct = (v) => `${(v * 100).toFixed(1)}%`;
const rank = (i) => {
  const s = ["🥇", "🥈", "🥉"];
  return s[i] || `#${i + 1}`;
};
const playoffBadge = (val) => {
  if (val === "Playoffs") return <span style={{ background: "#2a9d8f", color: "#fff", borderRadius: 4, padding: "1px 6px", fontSize: 11 }}>Playoffs</span>;
  if (val === "No Playoffs") return <span style={{ background: "#444", color: "#aaa", borderRadius: 4, padding: "1px 6px", fontSize: 11 }}>Missed</span>;
  return <span style={{ background: "#333", color: "#777", borderRadius: 4, padding: "1px 6px", fontSize: 11 }}>In Progress</span>;
};

// ── SHARED COMPONENTS ────────────────────────────────────────────────────────
const Card = ({ children, style }) => {
  const mobile = useMobile();
  return <div style={{ background: "#1a1a1a", border: "1px solid #222222", borderRadius: 12, padding: mobile ? "12px 12px" : "20px 24px", ...style }}>{children}</div>;
};

const SectionTitle = ({ children }) => {
  const mobile = useMobile();
  return <h2 style={{ fontFamily: "'Cooper Black', Georgia, serif", fontSize: mobile ? 20 : 28, color: "#2176d2", letterSpacing: 2, margin: mobile ? "0 0 12px 0" : "0 0 18px 0", textTransform: "uppercase" }}>{children}</h2>;
};

const Table = ({ headers, rows, rowStyle }) => {
  const mobile = useMobile();
  return (
  <div style={{ overflowX: "auto" }}>
    <table style={{ width: "100%", borderCollapse: "collapse", fontSize: mobile ? 13 : 13 }}>
      <thead>
        <tr>
          {headers.map((h, i) => (
            <th key={i} style={{ textAlign: "left", padding: mobile ? "6px 8px" : "8px 12px", borderBottom: "1px solid #222222", color: "#2176d2", fontFamily: "'Cooper Black', Georgia, serif", letterSpacing: 1, fontSize: 14, whiteSpace: "nowrap" }}>
              {h}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row, i) => (
          <tr key={i} style={{ background: i % 2 === 0 ? "#0d0d0d" : "#1a1a1a", ...(rowStyle ? rowStyle(row, i) : {}) }}>
            {row.map((cell, j) => (
              <td key={j} style={{ padding: mobile ? "6px 8px" : mobile ? "6px 8px" : "9px 12px", borderBottom: "1px solid #1a1a1a", color: "#ccc", whiteSpace: "nowrap" }}>
                {cell}
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  </div>
  );
};

const StatCard = ({ label, value, sub, color }) => {
  const mobile = useMobile();
  return (
    <div style={{ background: "#0d0d0d", border: `1px solid ${color || "#222222"}`, borderRadius: 10, padding: mobile ? "10px 12px" : "16px 20px", flex: 1, minWidth: mobile ? 80 : 140 }}>
      <div style={{ fontSize: mobile ? 11 : 11, color: "#888", textTransform: "uppercase", letterSpacing: 1, marginBottom: 4 }}>{label}</div>
      <div style={{ fontSize: mobile ? 20 : 26, fontFamily: "'Cooper Black', Georgia, serif", color: color || "#fff", letterSpacing: 1 }}>{value}</div>
      {sub && <div style={{ fontSize: 11, color: "#666", marginTop: 2 }}>{sub}</div>}
    </div>
  );
};

const FilterBar = ({ children }) => (
  <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center", marginBottom: 4 }}>
    {children}
  </div>
);
const ToggleBtn = ({ active, onToggle, label }) => {
  const mobile = useMobile();
  return (
    <button onClick={onToggle} style={{
      background: active ? "#2176d2" : "#1a1a1a",
      color: active ? "#fff" : "#555",
      border: `1px solid ${active ? "#2176d2" : "#333"}`,
      borderRadius: 6, padding: mobile ? "5px 8px" : "6px 14px", cursor: "pointer", fontSize: mobile ? 11 : 12,
    }}>{label}</button>
  );
};
// ── MGR NAME w/ LOGO (logo + firstName on mobile, full name on desktop) ──────
const MgrName = ({ name, size, ddLogos }) => {
  const mobile = useMobile();
  const { open } = usePopover();
  const s = size || (mobile ? 30 : 30);
  return (
    <span
      onClick={e => { e.stopPropagation(); open(name, { x: e.clientX, y: e.clientY }); }}
      style={{ display:"inline-flex", alignItems:"center", gap: mobile ? 4 : 5, minWidth:0, overflow:"hidden", cursor:"pointer" }}
    >
      {ddLogos ? <DDManagerLogo name={name} size={s} /> : <ManagerLogo name={name} size={s} />}
      <span style={{ color:getColor(name), fontWeight:600, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap", textDecoration:"underline", textDecorationStyle:"dotted", textDecorationColor: getColor(name) + "66", textUnderlineOffset: 3 }}>
        {shortMgr(name, mobile)}
      </span>
    </span>
  );
};



// ── MGRSPAN — lightweight inline manager name (no logo) with popover ─────────
const MgrSpan = ({ name, children, style = {} }) => {
  const { open } = usePopover();
  if (!name) return <span style={style}>{children || name}</span>;
  const color = getColor(name);
  return (
    <span
      onClick={e => { e.stopPropagation(); open(name, { x: e.clientX, y: e.clientY }); }}
      style={{ color, fontWeight: 600, cursor: "pointer", textDecoration: "underline",
        textDecorationStyle: "dotted", textDecorationColor: color + "66",
        textUnderlineOffset: 3, ...style }}
    >{children || name}</span>
  );
};

// ── YEARSPAN — tappable year (2015–2025 only) that opens Season Card ─────────
const LEAGUE_YEARS = new Set([2015,2016,2017,2018,2019,2020,2021,2022,2023,2024,2025]);
const YearSpan = ({ year, style = {} }) => {
  const { open } = useSeason();
  const y = Number(year);
  if (!LEAGUE_YEARS.has(y)) return <span style={style}>{year}</span>;
  return (
    <span
      onClick={e => { e.stopPropagation(); open(y, { x: e.clientX, y: e.clientY }); }}
      style={{ cursor: "pointer", textDecoration: "underline", textDecorationStyle: "dotted",
        textDecorationColor: "#aaa6", textUnderlineOffset: 3, ...style }}
    >{year}</span>
  );
};
const ManagerPopoverCard = ({ manager, anchorPos, onClose }) => {
  const mobile = useMobile();
  const { goToManager } = useNavigate();

  if (!manager) return null;

  // ── Compute career stats ──
  const seasons   = DATA.seasonHistories[manager] || [];
  const wins      = seasons.reduce((s, y) => s + y.W, 0);
  const losses    = seasons.reduce((s, y) => s + y.L, 0);
  const totalGames = wins + losses;
  const playoffSeasons = seasons.filter(y => y.playoffs).length;
  const titles    = DATA.leagueWinners.filter(w => w.Manager === manager).length;
  const titleYears = DATA.leagueWinners.filter(w => w.Manager === manager).map(w => w.Year);
  const twin      = DATA.mgrNFLTwin[manager] || null;
  const twinData  = twin ? DATA.nflTeams[twin] : null;
  const color     = getColor(manager);

  // Career PPG (PF per week)
  const totalPF   = seasons.reduce((s, y) => s + y.PF, 0);
  const ppg       = totalGames > 0 ? (totalPF / totalGames).toFixed(1) : "—";

  // Best season by W%
  const bestSeason = seasons.length > 0
    ? seasons.reduce((best, y) => {
        const pct = (y.W + y.L) > 0 ? y.W / (y.W + y.L) : 0;
        const bpct = (best.W + best.L) > 0 ? best.W / (best.W + best.L) : 0;
        return pct > bpct ? y : best;
      })
    : null;

  // Latest season team name
  const latestSeason = seasons.length > 0 ? seasons[seasons.length - 1] : null;

  // ── Position logic ──
  const cardStyle = mobile
    ? {
        position: "fixed", bottom: 0, left: 0, right: 0,
        background: "#0d0d0d", borderTop: `3px solid ${color}`,
        borderRadius: "20px 20px 0 0", padding: "20px 20px 32px",
        zIndex: 1000, boxShadow: "0 -8px 40px rgba(0,0,0,0.7)",
        maxHeight: "75vh", overflowY: "auto",
      }
    : (() => {
        const x = anchorPos?.x || window.innerWidth / 2;
        const y = anchorPos?.y || window.innerHeight / 2;
        const flipX = x > window.innerWidth * 0.65;
        const flipY = y > window.innerHeight * 0.55;
        return {
          position: "fixed",
          left:  flipX ? undefined : Math.min(x + 12, window.innerWidth - 340),
          right: flipX ? window.innerWidth - x + 12 : undefined,
          top:   flipY ? undefined : Math.min(y - 20, window.innerHeight - 380),
          bottom: flipY ? window.innerHeight - y + 12 : undefined,
          width: 320,
          background: "#0d0d0d",
          border: `1px solid ${color}55`,
          borderTop: `3px solid ${color}`,
          borderRadius: 14,
          padding: "18px 18px 16px",
          zIndex: 1000,
          boxShadow: "0 8px 40px rgba(0,0,0,0.7)",
        };
      })();

  return (
    <>
      {/* Backdrop */}
      <div
        onClick={onClose}
        style={{
          position: "fixed", inset: 0, zIndex: 999,
          background: mobile ? "rgba(0,0,0,0.5)" : "transparent",
        }}
      />
      {/* Card */}
      <div style={cardStyle}>
        {/* Header row */}
        <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between", marginBottom: 14, gap: 10 }}>
          <div style={{ minWidth: 0 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
              <ManagerLogo name={manager} size={36} />
              <div>
                <div style={{ color, fontWeight: 700, fontSize: 15, lineHeight: 1.2 }}>{manager}</div>
                {twinData && (
                  <div style={{ fontSize: 11, color: "#666", marginTop: 1 }}>
                    <span style={{ color: twinData.color, fontWeight: 600 }}>{twinData.abbr}</span>
                    {" "}· {twin}
                  </div>
                )}
              </div>
            </div>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: 8, flexShrink: 0 }}>
            {/* Close button */}
            <button onClick={onClose} style={{
              background: "none", border: "1px solid #333", borderRadius: "50%",
              color: "#666", cursor: "pointer", width: 26, height: 26,
              fontSize: 14, display: "flex", alignItems: "center", justifyContent: "center",
              flexShrink: 0,
            }}>✕</button>
          </div>
        </div>

        {/* Divider */}
        <div style={{ borderTop: `1px solid ${color}33`, marginBottom: 12 }} />

        {/* Stats grid */}
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: "10px 6px", marginBottom: 14 }}>
          {[
            { label: "Record", value: `${wins}–${losses}` },
            { label: "Playoffs", value: `${playoffSeasons}/${seasons.length}` },
            { label: "Titles", value: titles > 0 ? `${"🏆".repeat(Math.min(titles, 3))} ${titles}` : "0" },
            { label: "Seasons", value: seasons.length },
            { label: "PPG Avg", value: ppg },
            { label: "Win %", value: totalGames > 0 ? `${(wins / totalGames * 100).toFixed(0)}%` : "—" },
          ].map(({ label, value }) => (
            <div key={label} style={{ background: "#000000", borderRadius: 8, padding: "8px 6px", textAlign: "center" }}>
              <div style={{ fontSize: 11, color: "#555", letterSpacing: 0.5, textTransform: "uppercase", marginBottom: 3 }}>{label}</div>
              <div style={{ fontSize: 14, fontWeight: 700, color: "#ddd" }}>{value}</div>
            </div>
          ))}
        </div>

        {/* Best season */}
        {bestSeason && (
          <div style={{ background: `${color}11`, border: `1px solid ${color}33`, borderRadius: 8, padding: "8px 12px", marginBottom: 10 }}>
            <div style={{ fontSize: 11, color: "#555", textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 3 }}>Best Season</div>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <span style={{ color, fontWeight: 600, fontSize: 13 }}>{bestSeason.year} · {bestSeason.team}</span>
              <span style={{ color: "#aaa", fontSize: 13 }}>{bestSeason.W}–{bestSeason.L}</span>
            </div>
            {bestSeason.PlayoffFinish === 1 && (
              <div style={{ fontSize: 11, color: "#e9c46a", marginTop: 2 }}>🏆 League Champion</div>
            )}
          </div>
        )}

        {/* Title years */}
        {titleYears.length > 0 && (
          <div style={{ fontSize: 11, color: "#e9c46a", textAlign: "center" }}>
            🏆 Champion: {titleYears.join(", ")}
          </div>
        )}

        {/* Latest team */}
        {latestSeason && (
          <div style={{ fontSize: 11, color: "#444", textAlign: "center", marginTop: 6 }}>
            {latestSeason.year} team: <span style={{ color: "#666" }}>{latestSeason.team}</span>
          </div>
        )}
        {/* Manager Spotlight link */}
        <button
          onClick={() => { onClose(); goToManager(manager); }}
          style={{
            marginTop: 14, width: "100%",
            background: "#1a1a1a", border: `1px solid ${color}`,
            borderRadius: 8, padding: "9px 14px",
            color, cursor: "pointer", fontSize: 13, fontWeight: 600,
            display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
            WebkitTapHighlightColor: "transparent", transition: "background 0.15s",
          }}
          onMouseEnter={e => e.currentTarget.style.background = "#2a1a3e"}
          onMouseLeave={e => e.currentTarget.style.background = "#1a1a1a"}
        >
          🔍 View Full Profile →
        </button>
      </div>
    </>
  );
};
// ── RIVALRY POPOVER CARD ──────────────────────────────────────────────────────
const RivalryPopoverCard = ({ managerA, managerB, anchorPos, onClose }) => {
  const mobile = useMobile();

  if (!managerA || !managerB) return null;

  const colorA = getColor(managerA);
  const colorB = getColor(managerB);

  // ── H2H aggregate record ──
  const recAB = DATA.h2h[managerA]?.[managerB] || { W: 0, L: 0, PF: 0, PA: 0 };
  const winsA = recAB.W;
  const winsB = recAB.L;
  const total = winsA + winsB;
  const pfA   = recAB.PF;
  const pfB   = recAB.PA;
  const ppgA  = total > 0 ? (pfA / total).toFixed(1) : "—";
  const ppgB  = total > 0 ? (pfB / total).toFixed(1) : "—";
  const leaderA = winsA > winsB;
  const tied    = winsA === winsB;
  const pctA    = total > 0 ? winsA / total : 0.5;

  // ── Rivalry ranking & heat ──
  const rivalry = DATA.rivalries.find(r =>
    (r.a === managerA && r.b === managerB) ||
    (r.a === managerB && r.b === managerA)
  );
  const maxScore = Math.max(...DATA.rivalries.map(r => r.score));
  const heatColor = (score) => {
    const t = score / maxScore;
    if (t > 0.85) return "#2176d2";
    if (t > 0.65) return "#f4a261";
    if (t > 0.45) return "#e9c46a";
    return "#2a9d8f";
  };
  const rivalryRank = rivalry ? DATA.rivalries.indexOf(rivalry) + 1 : null;
  const heat = rivalry ? heatColor(rivalry.score) : "#555";

  // ── Biggest win between these two ──
  const allMatchups = [...DATA.biggestBlowouts, ...DATA.closestMatchups];
  const pairMatchups = allMatchups.filter(g =>
    (g.Winner === managerA && g.Loser === managerB) ||
    (g.Winner === managerB && g.Loser === managerA)
  );
  const biggestWin = pairMatchups.length > 0
    ? pairMatchups.reduce((best, g) => g.Margin > best.Margin ? g : best)
    : null;
  const closestGame = pairMatchups.length > 0
    ? pairMatchups.reduce((best, g) => g.Margin < best.Margin ? g : best)
    : null;

  // ── Ownage check ──
  const ownageEntry = DATA.ownage.find(o =>
    (o.Winner === managerA && o.Loser === managerB) ||
    (o.Winner === managerB && o.Loser === managerA)
  );
  const isDomination = ownageEntry && ownageEntry.WPct >= 0.8 && ownageEntry.Total >= 5;

  // ── Position logic (same pattern as manager card) ──
  const cardStyle = mobile
    ? {
        position: "fixed", bottom: 0, left: 0, right: 0,
        background: "#0d0d0d", borderTop: `3px solid ${leaderA || tied ? colorA : colorB}`,
        borderRadius: "20px 20px 0 0", padding: "20px 20px 32px",
        zIndex: 1000, boxShadow: "0 -8px 40px rgba(0,0,0,0.7)",
        maxHeight: "75vh", overflowY: "auto",
      }
    : (() => {
        const x = anchorPos?.x || window.innerWidth / 2;
        const y = anchorPos?.y || window.innerHeight / 2;
        const flipX = x > window.innerWidth * 0.6;
        const flipY = y > window.innerHeight * 0.55;
        return {
          position: "fixed",
          left:  flipX ? undefined : Math.min(x + 14, window.innerWidth - 360),
          right: flipX ? window.innerWidth - x + 14 : undefined,
          top:   flipY ? undefined : Math.min(y - 20, window.innerHeight - 440),
          bottom: flipY ? window.innerHeight - y + 14 : undefined,
          width: 340,
          background: "#0d0d0d",
          border: "1px solid #222222",
          borderTop: `3px solid ${heat}`,
          borderRadius: 14,
          padding: "18px 18px 16px",
          zIndex: 1000,
          boxShadow: "0 8px 40px rgba(0,0,0,0.7)",
        };
      })();

  return (
    <>
      {/* Backdrop */}
      <div onClick={onClose} style={{
        position: "fixed", inset: 0, zIndex: 999,
        background: mobile ? "rgba(0,0,0,0.5)" : "transparent",
      }} />
      {/* Card */}
      <div style={cardStyle}>

        {/* ── Title row ── */}
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
          <div style={{
            fontFamily: "'Cooper Black', Georgia, serif",
            fontSize: 13, letterSpacing: 2, color: heat,
            textTransform: "uppercase",
          }}>
            {rivalryRank ? `⚔️ Rivalry #${rivalryRank}` : "⚔️ Head-to-Head"}
          </div>
          <button onClick={onClose} style={{
            background: "none", border: "1px solid #333", borderRadius: "50%",
            color: "#666", cursor: "pointer", width: 26, height: 26,
            fontSize: 14, display: "flex", alignItems: "center", justifyContent: "center",
          }}>✕</button>
        </div>

        {/* ── Manager matchup header ── */}
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 14 }}>
          {/* Manager A */}
          <div style={{ flex: 1, textAlign: "center" }}>
            <ManagerLogo name={managerA} size={38} />
            <div style={{ color: colorA, fontWeight: 700, fontSize: 13, marginTop: 4, lineHeight: 1.2 }}>
              {managerA.split(" ")[0]}
            </div>
          </div>

          {/* Record display */}
          <div style={{ textAlign: "center", flexShrink: 0 }}>
            <div style={{ fontFamily: "'Cooper Black', Georgia, serif", fontSize: 28, lineHeight: 1, letterSpacing: 2 }}>
              <span style={{ color: winsA >= winsB ? colorA : "#555" }}>{winsA}</span>
              <span style={{ color: "#333", margin: "0 4px" }}>–</span>
              <span style={{ color: winsB >= winsA ? colorB : "#555" }}>{winsB}</span>
            </div>
            <div style={{ fontSize: 11, color: "#444", marginTop: 2 }}>{total} games</div>
          </div>

          {/* Manager B */}
          <div style={{ flex: 1, textAlign: "center" }}>
            <ManagerLogo name={managerB} size={38} />
            <div style={{ color: colorB, fontWeight: 700, fontSize: 13, marginTop: 4, lineHeight: 1.2 }}>
              {managerB.split(" ")[0]}
            </div>
          </div>
        </div>

        {/* ── Win % bar ── */}
        <div style={{ marginBottom: 14 }}>
          <div style={{ display: "flex", height: 8, borderRadius: 4, overflow: "hidden", background: colorB }}>
            <div style={{ width: `${pctA * 100}%`, background: colorA, transition: "width 0.4s" }} />
          </div>
          <div style={{ display: "flex", justifyContent: "space-between", marginTop: 4, fontSize: 11 }}>
            <span style={{ color: colorA }}>{(pctA * 100).toFixed(0)}%</span>
            <span style={{ color: tied ? "#aaa" : (leaderA ? colorA : colorB), fontWeight: 700, fontSize: 12 }}>
              {tied ? "DEADLOCKED" : `${leaderA ? managerA.split(" ")[0] : managerB.split(" ")[0]} leads`}
            </span>
            <span style={{ color: colorB }}>{((1 - pctA) * 100).toFixed(0)}%</span>
          </div>
        </div>

        {/* ── PPG comparison ── */}
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 8, marginBottom: 14 }}>
          {[
            { label: "Avg Score", valA: ppgA, valB: ppgB },
            { label: "Total PF",  valA: pfA.toFixed(1), valB: pfB.toFixed(1) },
          ].map(({ label, valA, valB }) => (
            <div key={label} style={{ background: "#000000", borderRadius: 8, padding: "8px 10px" }}>
              <div style={{ fontSize: 11, color: "#444", textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 5, textAlign: "center" }}>{label}</div>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <span style={{ color: colorA, fontWeight: 700, fontSize: 13 }}>{valA}</span>
                <span style={{ color: "#333", fontSize: 11 }}>vs</span>
                <span style={{ color: colorB, fontWeight: 700, fontSize: 13 }}>{valB}</span>
              </div>
            </div>
          ))}
        </div>

        {/* ── Divider ── */}
        <div style={{ borderTop: "1px solid #141414", marginBottom: 12 }} />

        {/* ── Notable games ── */}
        {biggestWin && (
          <div style={{ background: "#000000", borderRadius: 8, padding: "8px 12px", marginBottom: 8 }}>
            <div style={{ fontSize: 11, color: "#555", textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 4 }}>💥 Biggest Blowout</div>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <span style={{ color: getColor(biggestWin.Winner), fontWeight: 700, fontSize: 13 }}>
                {biggestWin.Winner.split(" ")[0]}
              </span>
              <span style={{ color: "#aaa", fontSize: 12 }}>
                {biggestWin.WinnerPts.toFixed(1)} – {biggestWin.LoserPts.toFixed(1)}
              </span>
              <span style={{ color: "#444", fontSize: 11 }}>+{biggestWin.Margin.toFixed(1)}</span>
            </div>
            <div style={{ fontSize: 11, color: "#444", marginTop: 2 }}><YearSpan year={biggestWin.Year} /> · Week {biggestWin.Week}</div>
          </div>
        )}

        {closestGame && closestGame !== biggestWin && (
          <div style={{ background: "#000000", borderRadius: 8, padding: "8px 12px", marginBottom: 8 }}>
            <div style={{ fontSize: 11, color: "#555", textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 4 }}>🔥 Closest Game</div>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <span style={{ color: getColor(closestGame.Winner), fontWeight: 700, fontSize: 13 }}>
                {closestGame.Winner.split(" ")[0]}
              </span>
              <span style={{ color: "#aaa", fontSize: 12 }}>
                {closestGame.WinnerPts.toFixed(1)} – {closestGame.LoserPts.toFixed(1)}
              </span>
              <span style={{ color: "#444", fontSize: 11 }}>+{closestGame.Margin.toFixed(1)}</span>
            </div>
            <div style={{ fontSize: 11, color: "#444", marginTop: 2 }}><YearSpan year={closestGame.Year} /> · Week {closestGame.Week}</div>
          </div>
        )}

        {/* ── Domination badge ── */}
        {isDomination && (
          <div style={{
            background: "#200d0d", border: "1px solid #2176d233",
            borderRadius: 8, padding: "7px 12px", textAlign: "center",
          }}>
            <span style={{ color: "#2176d2", fontSize: 12, fontWeight: 700 }}>
              👑 {ownageEntry.Winner.split(" ")[0]} OWNS THIS MATCHUP
            </span>
            <span style={{ color: "#555", fontSize: 11, marginLeft: 6 }}>
              ({ownageEntry.W}–{ownageEntry.L})
            </span>
          </div>
        )}

      </div>
    </>
  );
};


// ── SHARED POPOVER POSITION HELPER ───────────────────────────────────────────
const popoverCardStyle = (mobile, anchorPos, w = 320, h = 420, accentColor = "#2176d2") => {
  if (mobile) return {
    position: "fixed", bottom: 0, left: 0, right: 0,
    background: "#0d0d0d", borderTop: `3px solid ${accentColor}`,
    borderRadius: "20px 20px 0 0", padding: "20px 20px 32px",
    zIndex: 1000, boxShadow: "0 -8px 40px rgba(0,0,0,0.7)",
    maxHeight: "78vh", overflowY: "auto",
  };
  const x = anchorPos?.x || window.innerWidth / 2;
  const y = anchorPos?.y || window.innerHeight / 2;
  const flipX = x > window.innerWidth * 0.62;
  const flipY = y > window.innerHeight * 0.55;
  return {
    position: "fixed",
    left:   flipX ? undefined : Math.min(x + 14, window.innerWidth - w - 16),
    right:  flipX ? window.innerWidth - x + 14 : undefined,
    top:    flipY ? undefined : Math.min(y - 20, window.innerHeight - h - 16),
    bottom: flipY ? window.innerHeight - y + 14 : undefined,
    width: w, background: "#0d0d0d",
    border: "1px solid #222222", borderTop: `3px solid ${accentColor}`,
    borderRadius: 14, padding: "18px 18px 16px",
    zIndex: 1000, boxShadow: "0 8px 40px rgba(0,0,0,0.7)",
  };
};
const PopoverBackdrop = ({ onClose, mobile }) => (
  <div onClick={onClose} style={{
    position: "fixed", inset: 0, zIndex: 999,
    background: mobile ? "rgba(0,0,0,0.5)" : "transparent",
  }} />
);
const PopoverCloseBtn = ({ onClose }) => (
  <button onClick={onClose} style={{
    background: "none", border: "1px solid #333", borderRadius: "50%",
    color: "#666", cursor: "pointer", width: 26, height: 26, fontSize: 14,
    display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
  }}>✕</button>
);
const PopoverStatGrid = ({ stats, cols = 3 }) => (
  <div style={{ display: "grid", gridTemplateColumns: `repeat(${cols}, 1fr)`, gap: "10px 6px", marginBottom: 14 }}>
    {stats.map(({ label, value, color }) => (
      <div key={label} style={{ background: "#000000", borderRadius: 8, padding: "8px 6px", textAlign: "center" }}>
        <div style={{ fontSize: 11, color: "#555", letterSpacing: 0.5, textTransform: "uppercase", marginBottom: 3 }}>{label}</div>
        <div style={{ fontSize: 14, fontWeight: 700, color: color || "#ddd" }}>{value}</div>
      </div>
    ))}
  </div>
);

// ── SEASON CARD ───────────────────────────────────────────────────────────────
const SeasonCard = ({ year, anchorPos, onClose }) => {
  const mobile = useMobile();
  const { goToSeason } = useNavigate();
  if (!year) return null;

  const champion   = DATA.leagueWinners.find(w => w.Year === year);
  const yearStats  = DATA.yoyScoring.find(y => y.year === year);
  const allSeasons = ALL_SEASONS[year] || [];
  const highScore  = allSeasons.reduce((b, s) => s.PF > b.PF ? s : b, allSeasons[0] || {});
  const blowout    = DATA.biggestBlowouts.find(g => g.Year === year);
  const closest    = DATA.closestMatchups.find(g => g.Year === year);
  const playoffTeams = allSeasons.filter(s => s.ReachedPlayoffs === "Playoffs").length;

  const accent = "#2176d2";
  return (
    <>
      <PopoverBackdrop onClose={onClose} mobile={mobile} />
      <div style={popoverCardStyle(mobile, anchorPos, 320, 440, accent)}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
          <div style={{ fontFamily: "'Cooper Black', Georgia, serif", fontSize: 32, color: accent, letterSpacing: 3, lineHeight: 1 }}>{year}</div>
          <PopoverCloseBtn onClose={onClose} />
        </div>
        <div style={{ borderTop: "1px solid #222222", marginBottom: 12 }} />
        {/* Champion */}
        {champion && (
          <div style={{ background: "#1a1400", border: "1px solid #e9c46a33", borderRadius: 8, padding: "10px 14px", marginBottom: 14, display: "flex", alignItems: "center", gap: 10 }}>
            <span style={{ fontSize: 24 }}>🏆</span>
            <div>
              <div style={{ fontSize: 11, color: "#666", textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 2 }}>Champion</div>
              <div style={{ color: getColor(champion.Manager), fontWeight: 700, fontSize: 15 }}>{champion.Manager}</div>
              <div style={{ color: "#666", fontSize: 12, fontStyle: "italic" }}>{champion["Team Name"]} · {champion.Record}</div>
            </div>
          </div>
        )}
        <PopoverStatGrid cols={3} stats={[
          { label: "Teams",    value: allSeasons.length },
          { label: "Playoffs", value: `${playoffTeams} teams` },
          { label: "Avg Score", value: yearStats ? yearStats.avg.toFixed(1) : "—", color: "#2a9d8f" },
          { label: "High Week", value: yearStats ? yearStats.high.toFixed(1) : "—", color: "#e9c46a" },
          { label: "Low Week",  value: yearStats ? yearStats.low.toFixed(1)  : "—", color: "#2176d2" },
          { label: "Std Dev",   value: yearStats ? yearStats.stdev.toFixed(1) : "—" },
        ]} />
        {highScore.Manager && (
          <div style={{ background: "#000000", borderRadius: 8, padding: "8px 12px", marginBottom: 8 }}>
            <div style={{ fontSize: 11, color: "#555", textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 3 }}>📈 Top Scorer (Season PF)</div>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <span style={{ color: getColor(highScore.Manager), fontWeight: 700, fontSize: 13 }}>{highScore.Manager}</span>
              <span style={{ color: "#e9c46a", fontWeight: 700, fontSize: 13 }}>{highScore.PF?.toFixed(1)}</span>
            </div>
          </div>
        )}
        {blowout && (
          <div style={{ background: "#000000", borderRadius: 8, padding: "8px 12px", marginBottom: 8 }}>
            <div style={{ fontSize: 11, color: "#555", textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 3 }}>💥 Biggest Blowout (Wk {blowout.Week})</div>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <span style={{ color: getColor(blowout.Winner), fontWeight: 700, fontSize: 13 }}>{blowout.Winner.split(" ")[0]}</span>
              <span style={{ color: "#aaa", fontSize: 12 }}>{blowout.WinnerPts.toFixed(1)} – {blowout.LoserPts.toFixed(1)}</span>
              <span style={{ color: "#444", fontSize: 11 }}>+{blowout.Margin.toFixed(1)}</span>
            </div>
          </div>
        )}
        {closest && (
          <div style={{ background: "#000000", borderRadius: 8, padding: "8px 12px" }}>
            <div style={{ fontSize: 11, color: "#555", textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 3 }}>🔥 Closest Game (Wk {closest.Week})</div>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <span style={{ color: getColor(closest.Winner), fontWeight: 700, fontSize: 13 }}>{closest.Winner.split(" ")[0]}</span>
              <span style={{ color: "#aaa", fontSize: 12 }}>{closest.WinnerPts.toFixed(1)} – {closest.LoserPts.toFixed(1)}</span>
              <span style={{ color: "#2a9d8f", fontSize: 11 }}>+{closest.Margin.toFixed(2)}</span>
            </div>
          </div>
        )}
        {/* Season Explorer link */}
        <button
          onClick={() => { onClose(); goToSeason(year); }}
          style={{
            marginTop: 14, width: "100%",
            background: "#1a1a1a", border: "1px solid #2176d2",
            borderRadius: 8, padding: "9px 14px",
            color: "#2176d2", cursor: "pointer", fontSize: 13, fontWeight: 600,
            display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
            WebkitTapHighlightColor: "transparent",
            transition: "background 0.15s",
          }}
          onMouseEnter={e => e.currentTarget.style.background = "#2a1a2e"}
          onMouseLeave={e => e.currentTarget.style.background = "#1a1a1a"}
        >
          🗓️ View {year} in Season Explorer →
        </button>
      </div>
    </>
  );
};

// ── TEAM NAME CARD ────────────────────────────────────────────────────────────
const TeamNameCard = ({ teamName, manager, year, anchorPos, onClose }) => {
  const mobile = useMobile();
  if (!teamName || !manager) return null;

  const seasons = DATA.seasonHistories[manager] || [];
  const thisSeason = seasons.find(s => s.year === year);
  const color = getColor(manager);
  const isChamp = DATA.leagueWinners.some(w => w.Manager === manager && w.Year === year);
  const allTeamNames = seasons.map(s => s.team);
  const timesUsed = allTeamNames.filter(t => t === teamName).length;

  const finishLabel = (finish) => {
    if (!finish) return "—";
    if (finish === 1) return "🏆 Champion";
    if (finish === 2) return "🥈 Runner-up";
    if (finish === 3) return "🥉 3rd Place";
    return `#${finish} Finish`;
  };

  return (
    <>
      <PopoverBackdrop onClose={onClose} mobile={mobile} />
      <div style={popoverCardStyle(mobile, anchorPos, 300, 340, color)}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 12 }}>
          <div style={{ minWidth: 0, flex: 1 }}>
            <div style={{ fontSize: 11, color: "#555", textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 4 }}>Team Name</div>
            <div style={{ color, fontWeight: 700, fontSize: 16, lineHeight: 1.2, fontStyle: "italic" }}>"{teamName}"</div>
          </div>
          <PopoverCloseBtn onClose={onClose} />
        </div>
        <div style={{ borderTop: "1px solid #222222", marginBottom: 12 }} />
        {/* Manager + year */}
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 14 }}>
          <ManagerLogo name={manager} size={32} />
          <div>
            <div style={{ color, fontWeight: 700, fontSize: 14 }}>{manager}</div>
            <div style={{ color: "#555", fontSize: 12 }}>{year} Season</div>
          </div>
          {isChamp && <span style={{ marginLeft: "auto", fontSize: 22 }}>🏆</span>}
        </div>
        {thisSeason && (
          <PopoverStatGrid cols={2} stats={[
            { label: "Record",  value: `${thisSeason.W}–${thisSeason.L}`, color },
            { label: "PF",      value: thisSeason.PF?.toFixed(1), color: "#2a9d8f" },
            { label: "RS Rank", value: `#${thisSeason.RSRank}` },
            { label: "Finish",  value: finishLabel(thisSeason.PlayoffFinish), color: thisSeason.PlayoffFinish <= 3 ? "#e9c46a" : "#aaa" },
          ]} />
        )}
        {thisSeason?.playoffs && (
          <div style={{ background: "#0d200d", border: "1px solid #2ecc7133", borderRadius: 8, padding: "7px 12px", textAlign: "center", fontSize: 12, color: "#2ecc71" }}>
            ✅ Made the playoffs
          </div>
        )}
        {!thisSeason?.playoffs && thisSeason && (
          <div style={{ background: "#1a0d0d", border: "1px solid #2176d233", borderRadius: 8, padding: "7px 12px", textAlign: "center", fontSize: 12, color: "#2176d2" }}>
            ❌ Missed the playoffs
          </div>
        )}
      </div>
    </>
  );
};

// ── SCORE CARD ────────────────────────────────────────────────────────────────
const ScoreCard = ({ score, anchorPos, onClose }) => {
  const mobile = useMobile();
  if (!score) return null;

  const { Points, Manager, Year, Week, "Team Name": teamName, "Reached Playoffs": reachedPlayoffs } = score;
  const color = getColor(Manager);

  // All-time rank across all segments
  const allScores = Object.values(DATA.topScoresBySegment)
    .flat()
    .sort((a, b) => b.Points - a.Points);
  const rank = allScores.findIndex(s =>
    s.Manager === Manager && s.Year === Year && s.Week === Week
  );
  const allTimeRank = rank >= 0 ? rank + 1 : null;

  // Find matchup opponent from closestMatchups / biggestBlowouts
  const matchup = [...DATA.closestMatchups, ...DATA.biggestBlowouts].find(g =>
    g.Year === Year && g.Week === Week &&
    (g.Winner === Manager || g.Loser === Manager)
  );
  const isWinner = matchup?.Winner === Manager;
  const opponent = matchup ? (isWinner ? matchup.Loser : matchup.Winner) : null;
  const oppScore = matchup ? (isWinner ? matchup.LoserPts : matchup.WinnerPts) : null;

  const accent = color;
  return (
    <>
      <PopoverBackdrop onClose={onClose} mobile={mobile} />
      <div style={popoverCardStyle(mobile, anchorPos, 300, 360, accent)}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 12 }}>
          <div>
            <div style={{ fontSize: 11, color: "#555", textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 2 }}>{Year} · Week {Week}</div>
            <div style={{ fontFamily: "'Cooper Black', Georgia, serif", fontSize: 36, color, letterSpacing: 2, lineHeight: 1 }}>{Points}</div>
            <div style={{ fontSize: 12, color: "#555", fontStyle: "italic", marginTop: 2 }}>pts</div>
          </div>
          <PopoverCloseBtn onClose={onClose} />
        </div>
        <div style={{ borderTop: "1px solid #222222", marginBottom: 12 }} />
        {/* Manager */}
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 14 }}>
          <ManagerLogo name={Manager} size={32} />
          <div>
            <div style={{ color, fontWeight: 700, fontSize: 14 }}>{Manager}</div>
            {teamName && <div style={{ color: "#555", fontSize: 12, fontStyle: "italic" }}>"{teamName}"</div>}
          </div>
        </div>
        {allTimeRank && (
          <div style={{ background: "#000000", borderRadius: 8, padding: "8px 12px", marginBottom: 8, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span style={{ fontSize: 11, color: "#555", textTransform: "uppercase", letterSpacing: 0.5 }}>All-Time Rank</span>
            <span style={{ fontFamily: "'Cooper Black', Georgia, serif", fontSize: 18, color: allTimeRank <= 5 ? "#e9c46a" : allTimeRank <= 20 ? "#f4a261" : "#aaa" }}>#{allTimeRank}</span>
          </div>
        )}
        {opponent && (
          <div style={{ background: isWinner ? "#0d200d" : "#200d0d", border: `1px solid ${isWinner ? "#2ecc71" : "#2176d2"}33`, borderRadius: 8, padding: "8px 12px", marginBottom: 8 }}>
            <div style={{ fontSize: 11, color: "#555", textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 4 }}>
              {isWinner ? "✅ Won vs" : "❌ Lost to"} {opponent.split(" ")[0]}
            </div>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <span style={{ color, fontWeight: 700, fontSize: 14 }}>{Points}</span>
              <span style={{ color: "#444", fontSize: 12 }}>vs</span>
              <span style={{ color: getColor(opponent), fontWeight: 700, fontSize: 14 }}>{oppScore?.toFixed(1)}</span>
            </div>
            {matchup && <div style={{ fontSize: 11, color: "#444", marginTop: 2 }}>Margin: {matchup.Margin.toFixed(1)} pts</div>}
          </div>
        )}
        <div style={{ background: "#000000", borderRadius: 8, padding: "7px 12px", textAlign: "center", fontSize: 12, color: reachedPlayoffs === "Playoffs" ? "#2ecc71" : "#2176d2" }}>
          {reachedPlayoffs === "Playoffs" ? "✅ Made playoffs that season" : "❌ Missed playoffs that season"}
        </div>
      </div>
    </>
  );
};

// ── PLAYOFF YEAR CARD ─────────────────────────────────────────────────────────
const PlayoffYearCard = ({ year, anchorPos, onClose }) => {
  const mobile = useMobile();
  const { goToPlayoffHistory } = useNavigate();
  if (!year) return null;

  const ELIM = new Set(["Quarterfinal", "Semifinal", "Championship"]);
  const games = DATA.playoffData.gameLog.filter(g =>
    g.year === year && g.bracket === "winners" && ELIM.has(g.roundName)
  );
  // Dedupe into matchups (one entry per pair per round)
  const seen = new Set();
  const matchups = [];
  games.forEach(g => {
    const key = [g.roundName, [g.manager, g.opponent].sort().join("|")].join("-");
    if (!seen.has(key)) {
      seen.add(key);
      const winnerGame = games.find(x => x.manager === g.manager && x.opponent === g.opponent && x.win) ||
                         games.find(x => x.manager === g.opponent && x.opponent === g.manager && x.win);
      matchups.push({
        round: g.roundName,
        winner: winnerGame?.manager,
        loser:  winnerGame ? (winnerGame.manager === g.manager ? g.opponent : g.manager) : null,
        winnerPts: winnerGame?.pf,
        loserPts:  winnerGame?.pa,
        isChamp: winnerGame?.champion,
      });
    }
  });

  const roundOrder = ["Quarterfinal", "Semifinal", "Championship"];
  const byRound = roundOrder.map(r => matchups.filter(m => m.round === r)).filter(g => g.length > 0);
  const champion = DATA.leagueWinners.find(w => w.Year === year);
  const accent = "#e9c46a";

  return (
    <>
      <PopoverBackdrop onClose={onClose} mobile={mobile} />
      <div style={popoverCardStyle(mobile, anchorPos, 330, 480, accent)}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 14 }}>
          <div>
            <div style={{ fontFamily: "'Cooper Black', Georgia, serif", fontSize: 28, color: accent, letterSpacing: 3, lineHeight: 1 }}>{year} Playoffs</div>
            {champion && <div style={{ fontSize: 12, color: "#555", marginTop: 2 }}>🏆 {champion.Manager} · {champion["Team Name"]}</div>}
          </div>
          <PopoverCloseBtn onClose={onClose} />
        </div>
        <div style={{ borderTop: "1px solid #222222", marginBottom: 14 }} />
        {byRound.map((roundGames, ri) => (
          <div key={ri} style={{ marginBottom: 12 }}>
            <div style={{ fontSize: 11, color: "#555", textTransform: "uppercase", letterSpacing: 1, marginBottom: 6, fontFamily: "'Cooper Black', Georgia, serif" }}>
              {roundGames[0]?.round}
            </div>
            <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
              {roundGames.map((m, i) => (
                <div key={i} style={{ background: "#000000", borderRadius: 8, padding: "7px 12px", border: m.isChamp ? "1px solid #e9c46a44" : "none" }}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                    <span style={{ color: getColor(m.winner), fontWeight: 700, fontSize: 13 }}>
                      {m.isChamp ? "👑 " : "✅ "}{m.winner?.split(" ")[0]}
                    </span>
                    <span style={{ color: "#e9c46a", fontFamily: "'Cooper Black', Georgia, serif", fontSize: 15 }}>
                      {m.winnerPts?.toFixed(1)}
                    </span>
                  </div>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 2, opacity: 0.5 }}>
                    <span style={{ color: getColor(m.loser), fontSize: 12 }}>
                      ❌ {m.loser?.split(" ")[0]}
                    </span>
                    <span style={{ color: "#aaa", fontSize: 12 }}>{m.loserPts?.toFixed(1)}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}
        {/* Playoff History link */}
        <button
          onClick={() => { onClose(); goToPlayoffHistory("record"); }}
          style={{
            marginTop: 14, width: "100%",
            background: "#1a1a1a", border: "1px solid #e9c46a",
            borderRadius: 8, padding: "9px 14px",
            color: "#e9c46a", cursor: "pointer", fontSize: 13, fontWeight: 600,
            display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
            WebkitTapHighlightColor: "transparent", transition: "background 0.15s",
          }}
          onMouseEnter={e => e.currentTarget.style.background = "#2a2a0e"}
          onMouseLeave={e => e.currentTarget.style.background = "#1a1a1a"}
        >
          📋 View All-Time Playoff Records →
        </button>
      </div>
    </>
  );
};


// ── TROPHY CARD ───────────────────────────────────────────────────────────────
const TrophyCard = ({ manager, year, anchorPos, onClose }) => {
  const mobile = useMobile();
  const { goToPlayoffHistory } = useNavigate();
  if (!manager || !year) return null;

  const color = getColor(manager);
  const winnerEntry = DATA.leagueWinners.find(w => w.Manager === manager && w.Year === year);

  // Championship game details from playoffData
  const champGame = DATA.playoffData.gameLog.find(g =>
    g.year === year && g.championship && g.bracket === "winners" && g.champion
  );
  const loserGame = DATA.playoffData.gameLog.find(g =>
    g.year === year && g.championship && g.bracket === "winners" && !g.champion
  );
  const opponent = champGame?.opponent;
  const winnerPts = champGame?.pf;
  const loserPts  = champGame?.pa;
  const margin    = winnerPts && loserPts ? (winnerPts - loserPts).toFixed(1) : null;

  // Manager's season that year
  const seasons = DATA.seasonHistories[manager] || [];
  const thisSeason = seasons.find(s => s.year === year);

  // How many titles total at that point
  const titlesThrough = DATA.leagueWinners.filter(w => w.Manager === manager && w.Year <= year).length;

  const accent = "#e9c46a";
  return (
    <>
      <PopoverBackdrop onClose={onClose} mobile={mobile} />
      <div style={popoverCardStyle(mobile, anchorPos, 320, 400, accent)}>
        {/* Header */}
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:14 }}>
          <div>
            <div style={{ fontFamily:"'Cooper Black',Georgia,serif", fontSize:13, color:"#555", letterSpacing:2, textTransform:"uppercase", marginBottom:2 }}>
              🏆 Championship {year}
            </div>
            <div style={{ display:"flex", alignItems:"center", gap:8 }}>
              <ManagerLogo name={manager} size={32} />
              <div style={{ color, fontWeight:700, fontSize:16 }}>{manager}</div>
            </div>
            {titlesThrough > 1 && (
              <div style={{ fontSize:11, color:"#e9c46a", marginTop:3 }}>
                {"👑".repeat(titlesThrough)} · Title #{titlesThrough}
              </div>
            )}
          </div>
          <PopoverCloseBtn onClose={onClose} />
        </div>

        <div style={{ borderTop:`1px solid ${color}33`, marginBottom:14 }} />

        {/* Championship game result */}
        {champGame && opponent ? (
          <div style={{ background:"#0d1a0d", border:"1px solid #2ecc7133", borderRadius:10, padding:"12px 14px", marginBottom:14 }}>
            <div style={{ fontSize:11, color:"#555", textTransform:"uppercase", letterSpacing:0.5, marginBottom:8 }}>Championship Game</div>
            <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between" }}>
              {/* Winner side */}
              <div style={{ textAlign:"center", flex:1 }}>
                <ManagerLogo name={manager} size={28} />
                <div style={{ color, fontWeight:700, fontSize:13, marginTop:3 }}>{manager.split(" ")[0]}</div>
                <div style={{ fontFamily:"'Cooper Black',Georgia,serif", fontSize:26, color:"#e9c46a", lineHeight:1 }}>
                  {winnerPts?.toFixed(1)}
                </div>
              </div>
              {/* vs */}
              <div style={{ textAlign:"center", padding:"0 8px" }}>
                <div style={{ color:"#333", fontSize:11, marginBottom:4 }}>vs</div>
                {margin && <div style={{ color:"#2ecc71", fontSize:11, fontWeight:700 }}>+{margin}</div>}
              </div>
              {/* Loser side */}
              <div style={{ textAlign:"center", flex:1, opacity:0.6 }}>
                <ManagerLogo name={opponent} size={28} />
                <div style={{ color:getColor(opponent), fontWeight:700, fontSize:13, marginTop:3 }}>{opponent.split(" ")[0]}</div>
                <div style={{ fontFamily:"'Cooper Black',Georgia,serif", fontSize:26, color:"#aaa", lineHeight:1 }}>
                  {loserPts?.toFixed(1)}
                </div>
              </div>
            </div>
          </div>
        ) : null}

        {/* Season stats */}
        {thisSeason && (
          <PopoverStatGrid cols={3} stats={[
            { label:"RS Record", value:`${thisSeason.W}–${thisSeason.L}`, color },
            { label:"RS Rank",   value:`#${thisSeason.RSRank}` },
            { label:"PF",        value:thisSeason.PF?.toFixed(1), color:"#2a9d8f" },
          ]} />
        )}

        {/* Team name */}
        {winnerEntry && (
          <div style={{ textAlign:"center", fontSize:12, color:"#555", fontStyle:"italic", marginBottom:14 }}>
            "{winnerEntry["Team Name"]}" · {winnerEntry.Record}
          </div>
        )}

        {/* Link to Playoff History */}
        <button
          onClick={() => { onClose(); goToPlayoffHistory("record"); }}
          style={{
            width:"100%", background:"#1a1a1a", border:`1px solid ${accent}`,
            borderRadius:8, padding:"9px 14px", color:accent, cursor:"pointer",
            fontSize:13, fontWeight:600, display:"flex", alignItems:"center",
            justifyContent:"center", gap:6, WebkitTapHighlightColor:"transparent",
            transition:"background 0.15s",
          }}
          onMouseEnter={e => e.currentTarget.style.background="#2a2a0e"}
          onMouseLeave={e => e.currentTarget.style.background="#1a1a1a"}
        >
          📋 View All-Time Playoff Records →
        </button>
      </div>
    </>
  );
};

// ── MATCHUP CARD ──────────────────────────────────────────────────────────────
const MatchupCard = ({ manager, year, anchorPos, onClose }) => {
  const mobile = useMobile();
  if (!manager || !year) return null;

  const color  = getColor(manager);
  const seasons = DATA.seasonHistories[manager] || [];
  const thisSeason = seasons.find(s => s.year === year);

  // All matchups involving this manager this season from our game pools
  const allGames = [...DATA.closestMatchups, ...DATA.biggestBlowouts];
  const seasonGames = allGames.filter(g =>
    g.Year === year && (g.Winner === manager || g.Loser === manager)
  );
  // Deduplicate by Week
  const seen = new Set();
  const uniqueGames = seasonGames.filter(g => {
    const k = `${g.Year}-${g.Week}`;
    if (seen.has(k)) return false;
    seen.add(k); return true;
  }).sort((a, b) => a.Week - b.Week);

  // Best and worst scoring weeks from topScores/worstScores
  const allTopScores = Object.values(DATA.topScoresBySegment).flat();
  const notableScores = allTopScores
    .filter(s => s.Manager === manager && s.Year === year)
    .sort((a, b) => b.Points - a.Points);
  const bestWeek  = notableScores[0] || null;

  const allWorstScores = Object.values(DATA.worstScoresBySegment).flat();
  const worstScores = allWorstScores
    .filter(s => s.Manager === manager && s.Year === year)
    .sort((a, b) => a.Points - b.Points);
  const worstWeek = worstScores[0] || null;

  // Playoff games that year
  const playoffGames = DATA.playoffData.gameLog.filter(g =>
    g.year === year && g.manager === manager && g.bracket === "winners"
  );
  const isChamp = playoffGames.some(g => g.champion);

  const accent = color;
  return (
    <>
      <PopoverBackdrop onClose={onClose} mobile={mobile} />
      <div style={popoverCardStyle(mobile, anchorPos, 320, 460, accent)}>
        {/* Header */}
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:12 }}>
          <div>
            <div style={{ fontSize:11, color:"#555", textTransform:"uppercase", letterSpacing:0.5, marginBottom:3 }}>
              <YearSpan year={year} /> Season
            </div>
            <div style={{ display:"flex", alignItems:"center", gap:8 }}>
              <ManagerLogo name={manager} size={30} />
              <div style={{ color, fontWeight:700, fontSize:15 }}>{manager}</div>
              {isChamp && <span style={{ fontSize:18 }}>👑</span>}
            </div>
            {thisSeason && (
              <div style={{ color:"#555", fontSize:12, fontStyle:"italic", marginTop:2 }}>"{thisSeason.team}"</div>
            )}
          </div>
          <PopoverCloseBtn onClose={onClose} />
        </div>

        <div style={{ borderTop:`1px solid ${color}33`, marginBottom:12 }} />

        {/* Season summary stats */}
        {thisSeason && (
          <PopoverStatGrid cols={3} stats={[
            { label:"Record",   value:`${thisSeason.W}–${thisSeason.L}`, color },
            { label:"PF",       value:thisSeason.PF?.toFixed(1), color:"#2a9d8f" },
            { label:"PA",       value:thisSeason.PA?.toFixed(1), color:"#2176d2" },
            { label:"RS Rank",  value:`#${thisSeason.RSRank}` },
            { label:"PPG",      value:((thisSeason.W + thisSeason.L) > 0 ? (thisSeason.PF / (thisSeason.W + thisSeason.L)).toFixed(1) : "—") },
            { label:"Playoffs", value:thisSeason.playoffs ? "✅ Yes" : "❌ No", color: thisSeason.playoffs ? "#2ecc71" : "#2176d2" },
          ]} />
        )}

        {/* Notable games that season */}
        {bestWeek && (
          <div style={{ background:"#0d1a0d", border:"1px solid #2ecc7133", borderRadius:8, padding:"8px 12px", marginBottom:8 }}>
            <div style={{ fontSize:11, color:"#555", textTransform:"uppercase", letterSpacing:0.5, marginBottom:3 }}>🔥 Best Week (Wk {bestWeek.Week})</div>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
              <span style={{ color, fontWeight:700, fontSize:13 }}>{bestWeek.Points} pts</span>
              <span style={{ color:"#444", fontSize:11 }}>{bestWeek["Team Name"]}</span>
            </div>
          </div>
        )}
        {worstWeek && (
          <div style={{ background:"#1a0d0d", border:"1px solid #2176d233", borderRadius:8, padding:"8px 12px", marginBottom:8 }}>
            <div style={{ fontSize:11, color:"#555", textTransform:"uppercase", letterSpacing:0.5, marginBottom:3 }}>💀 Worst Week (Wk {worstWeek.Week})</div>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
              <span style={{ color:"#2176d2", fontWeight:700, fontSize:13 }}>{worstWeek.Points} pts</span>
              <span style={{ color:"#444", fontSize:11 }}>{worstWeek["Team Name"]}</span>
            </div>
          </div>
        )}

        {/* Notable matchups */}
        {uniqueGames.length > 0 && (
          <div style={{ background:"#000000", borderRadius:8, padding:"8px 12px" }}>
            <div style={{ fontSize:11, color:"#555", textTransform:"uppercase", letterSpacing:0.5, marginBottom:6 }}>Notable Matchups</div>
            <div style={{ display:"flex", flexDirection:"column", gap:4 }}>
              {uniqueGames.slice(0,3).map((g,i) => {
                const won = g.Winner === manager;
                const opp = won ? g.Loser : g.Winner;
                const myPts = won ? g.WinnerPts : g.LoserPts;
                const oppPts = won ? g.LoserPts : g.WinnerPts;
                return (
                  <div key={i} style={{ display:"flex", justifyContent:"space-between", alignItems:"center", fontSize:12 }}>
                    <span style={{ color: won ? "#2ecc71" : "#2176d2", fontWeight:700, minWidth:20 }}>{won ? "W" : "L"}</span>
                    <span style={{ color:"#555", minWidth:24 }}>Wk{g.Week}</span>
                    <MgrSpan name={opp} style={{ flex:1, fontSize:12, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap", marginLeft:4 }}>{opp.split(" ")[0]}</MgrSpan>
                    <span style={{ color:"#aaa", flexShrink:0, marginLeft:8 }}>{myPts?.toFixed(1)}–{oppPts?.toFixed(1)}</span>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </>
  );
};


const MiniBar = ({ value, max, color }) => (
  <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
    <div style={{ flex: 1, background: "#000000", borderRadius: 4, height: 8, overflow: "hidden" }}>
      <div style={{ width: `${(value / max) * 100}%`, height: "100%", background: color, borderRadius: 4, transition: "width 0.4s" }} />
    </div>
    <span style={{ fontSize: 12, color: "#aaa", minWidth: 30, textAlign: "right" }}>{value}</span>
  </div>
);

