function useSleeperLive(leagueId = SLEEPER_2026_LEAGUE_ID, nameMap = SLEEPER_NAME_MAP) {
  const [state, setState] = React.useState({
    loading:           false,
    error:             null,
    leagueStatus:      null,   // "pre_draft" | "drafting" | "in_season" | "complete" | null
    currentWeek:       null,
    managers:          [],     // [{ rosterId, name, wins, losses, pf, pa, streak }]
    matchups:          [],     // [{ matchupId, teamA, teamB }]
    transactions:      [],     // [{ type, adds, drops, ts, rosterIdToName }]
    // ── Project Banana: current season player data ──────────────────────────
    currentPlayerData: null,   // { draftPicks: [], weeklyScores: [] } | null when complete
    seasonComplete:    false,  // true when status === "complete" → show commissioner banner
    lastFetched:       null,
  });

  const fetch$ = React.useCallback(async () => {
    setState(s => ({ ...s, loading: true, error: null }));

    // ════════════════════════════════════════════════════════════

    try {
      const LID = leagueId;

      const [leagueRes, rostersRes, usersRes] = await Promise.all([
        fetch(`${SLEEPER_BASE}/league/${LID}`),
        fetch(`${SLEEPER_BASE}/league/${LID}/rosters`),
        fetch(`${SLEEPER_BASE}/league/${LID}/users`),
      ]);
      const league  = await leagueRes.json();
      const rosters = await rostersRes.json();
      const users   = await usersRes.json();

      // ── Sleeper API schema validator ─────────────────────────────────────
      // If Sleeper renames fields, these checks catch it early with a visible
      // error rather than silently producing wrong data. Verify once per season.
      const schemaWarnings = [];
      if (!("status" in league))                          schemaWarnings.push("league.status missing");
      if (!league.settings || !("leg" in league.settings)) schemaWarnings.push("league.settings.leg missing (current week)");
      if (!Array.isArray(rosters) || rosters.length === 0) schemaWarnings.push("rosters array empty or missing");
      if (rosters.length > 0) {
        const r0 = rosters[0];
        if (!r0.settings || !("wins" in r0.settings))    schemaWarnings.push("rosters[].settings.wins missing");
        if (!r0.settings || !("fpts" in r0.settings))    schemaWarnings.push("rosters[].settings.fpts missing");
        if (!("roster_id" in r0))                         schemaWarnings.push("rosters[].roster_id missing");
        if (!("owner_id"  in r0))                         schemaWarnings.push("rosters[].owner_id missing");
      }
      if (!Array.isArray(users) || users.length === 0)   schemaWarnings.push("users array empty or missing");
      if (users.length > 0) {
        if (!("user_id"      in users[0]))                schemaWarnings.push("users[].user_id missing");
        if (!("display_name" in users[0]))                schemaWarnings.push("users[].display_name missing");
      }
      if (schemaWarnings.length > 0) {
        setState(s => ({ ...s, loading: false,
          error: "⚠️ Sleeper API schema changed — dashboard data may be wrong.\n" + schemaWarnings.join("\n") }));
        return;
      }
      // ─────────────────────────────────────────────────────────────────────

      const status = league.status;
      const week   = league.settings?.leg || 1;

      // Build rosterId → canonical name map
      const uidToDisplay = {};
      users.forEach(u => { uidToDisplay[u.user_id] = u.display_name; });
      const rosterIdToName = {};
      rosters.forEach(r => {
        const display = uidToDisplay[r.owner_id] || "";
        rosterIdToName[r.roster_id] = nameMap[display] || display || `Team ${r.roster_id}`;
      });

      // Build standings from roster metadata
      const managers = rosters.map(r => {
        const wins   = r.settings?.wins   || 0;
        const losses = r.settings?.losses || 0;
        const ties   = r.settings?.ties   || 0;
        const pf     = parseFloat(((r.settings?.fpts || 0) + (r.settings?.fpts_decimal || 0) * 0.01).toFixed(2));
        const pa     = parseFloat(((r.settings?.fpts_against || 0) + (r.settings?.fpts_against_decimal || 0) * 0.01).toFixed(2));
        const streakType = r.metadata?.streak_type;
        const streakLen  = parseInt(r.metadata?.streak || "0", 10);
        const streak = streakType === "W" ? streakLen : streakType === "L" ? -streakLen : 0;
        return { rosterId: r.roster_id, name: rosterIdToName[r.roster_id], wins, losses, ties, pf, pa, streak };
      }).sort((a, b) => b.wins - a.wins || b.pf - a.pf);

      let matchups     = [];
      let transactions = [];

      // ── Season is complete → stop live-fetching, show commissioner banner ──
      if (status === "complete") {
        setState({
          loading: false, error: null,
          leagueStatus: status, currentWeek: week,
          managers, matchups: [], transactions: [],
          currentPlayerData: null, seasonComplete: true,
          lastFetched: new Date(),
        });
        return;
      }

      // ── Active season: fetch matchups, transactions, and player data ─────────
      if (status === "in_season" || status === "drafting") {

        // Current week matchups (standings display)
        const mRes  = await fetch(`${SLEEPER_BASE}/league/${LID}/matchups/${week}`);
        const mData = await mRes.json();
        const byId  = {};
        mData.forEach(entry => {
          if (!byId[entry.matchup_id]) byId[entry.matchup_id] = [];
          byId[entry.matchup_id].push(entry);
        });
        matchups = Object.values(byId).filter(p => p.length === 2).map(([a, b]) => ({
          matchupId: a.matchup_id,
          teamA: { name: rosterIdToName[a.roster_id], points: a.points || 0 },
          teamB: { name: rosterIdToName[b.roster_id], points: b.points || 0 },
        }));

        // Recent transactions (last 3 weeks)
        const txWeeks  = [week, week - 1, week - 2].filter(w => w >= 1);
        const txResults = await Promise.all(
          txWeeks.map(w => fetch(`${SLEEPER_BASE}/league/${LID}/transactions/${w}`).then(r => r.json()))
        );
        const allTx = txResults.flat().filter(t => t.status === "complete");
        allTx.sort((a, b) => b.created - a.created);
        transactions = allTx.slice(0, 20).map(t => ({
          type:           t.type,
          adds:           Object.keys(t.adds  || {}),
          drops:          Object.keys(t.drops || {}),
          rosterId:       Object.keys(t.adds  || {})[0] ? t.adds[Object.keys(t.adds)[0]] : null,
          rosterIdToName,
          ts:             t.created,
        }));

        // ── Project Banana: draft picks for current season ───────────────────
        let currentDraftPicks = [];
        try {
          const draftsRes = await fetch(`${SLEEPER_BASE}/league/${LID}/drafts`);
          const drafts    = await draftsRes.json();
          if (drafts.length > 0) {
            const draftId   = drafts[0].draft_id;
            const picksRes  = await fetch(`${SLEEPER_BASE}/draft/${draftId}/picks`);
            const picks     = await picksRes.json();
            currentDraftPicks = picks.map(p => {
              const meta = p.metadata || {};
              return {
                year:       2026,
                manager:    rosterIdToName[p.roster_id] || `Team ${p.roster_id}`,
                playerId:   p.player_id,
                playerName: `${meta.first_name || ""} ${meta.last_name || ""}`.trim(),
                position:   meta.position || "",
                price:      parseInt(meta.amount || 0, 10),
                pickNo:     p.pick_no,
                isKeeper:   !!p.is_keeper,
              };
            });
          }
        } catch (e) {
          console.warn("Banana: draft picks fetch failed", e);
        }

        // ── Project Banana: weekly player scores for all completed weeks ─────
        // Fetch all weeks 1..week in parallel — each matchup entry has players_points
        let currentWeeklyScores = [];
        try {
          const weeksToFetch = Array.from({ length: week }, (_, i) => i + 1);
          const allMatchupWeeks = await Promise.all(
            weeksToFetch.map(w =>
              fetch(`${SLEEPER_BASE}/league/${LID}/matchups/${w}`)
                .then(r => r.json())
                .then(data => ({ week: w, data }))
                .catch(() => ({ week: w, data: [] }))
            )
          );
          allMatchupWeeks.forEach(({ week: w, data }) => {
            data.forEach(entry => {
              const pp       = entry.players_points || {};
              const starters = new Set(entry.starters || []);
              const manager  = rosterIdToName[entry.roster_id] || `Team ${entry.roster_id}`;
              Object.entries(pp).forEach(([pid, pts]) => {
                currentWeeklyScores.push({
                  year:     2026,
                  week:     w,
                  manager,
                  playerId: pid,
                  points:   pts,
                  starter:  starters.has(pid),
                });
              });
            });
          });
        } catch (e) {
          console.warn("Banana: weekly scores fetch failed", e);
        }

        setState({
          loading: false, error: null,
          leagueStatus: status, currentWeek: week,
          managers, matchups, transactions,
          currentPlayerData: {
            draftPicks:   currentDraftPicks,
            weeklyScores: currentWeeklyScores,
          },
          seasonComplete: false,
          lastFetched: new Date(),
        });
        return;
      }

      // ── Pre-draft / offseason state ──────────────────────────────────────────
      setState({
        loading: false, error: null,
        leagueStatus: status, currentWeek: week,
        managers, matchups: [], transactions: [],
        currentPlayerData: null, seasonComplete: false,
        lastFetched: new Date(),
      });

    } catch (err) {
      setState(s => ({ ...s, loading: false, error: err.message || "Failed to load data." }));
    }
  }, []);

  return { ...state, refresh: fetch$ };
}

// ── Commissioner banner: shown when season is complete and not yet archived ───
function CommissionerBanner({ onDismiss }) {
  const [dismissed, setDismissed] = React.useState(false);
  if (dismissed) return null;
  return (
    <div style={{
      background: "rgba(233,196,106,0.12)", border: "1px solid rgba(233,196,106,0.35)",
      borderRadius: 8, padding: "12px 16px", marginBottom: 16,
      display: "flex", alignItems: "flex-start", gap: 12,
    }}>
      <span style={{ fontSize: 20, lineHeight: 1 }}>📦</span>
      <div style={{ flex: 1 }}>
        <div style={{ fontWeight: 700, color: "#e9c46a", fontSize: 13, marginBottom: 4 }}>
          Season Complete — Archive Needed
        </div>
        <div style={{ fontSize: 12, color: "#aaa", lineHeight: 1.5 }}>
          The 2026 season has ended. Run <code style={{ background: "#333", padding: "1px 5px", borderRadius: 3, fontSize: 11 }}>sleeper_full_extraction.py</code> to
          archive this season's player data, then update the dashboard.
        </div>
      </div>
      <button
        onClick={() => setDismissed(true)}
        style={{ background: "none", border: "none", color: "#666", cursor: "pointer", fontSize: 16, padding: "0 4px", lineHeight: 1 }}
      >✕</button>
    </div>
  );
}

// ── Sub-components ────────────────────────────────────────────────────────────

function CSStandings({ managers, ddLogos }) {
  const mobile = useMobile();
  const PLAYOFF_SPOTS = 6;
  const headers = mobile
    ? ["#", "Manager", "W", "L", "PF", "Streak", ""]
    : ["#", "Manager", "W", "L", "PF", "PA", "Streak", ""];
  return (
    <div>
      <div style={{ fontSize: 11, fontWeight: 700, color: "#888", textTransform: "uppercase", letterSpacing: 0.8, marginBottom: 8 }}>
        Standings
      </div>
      <div style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: mobile ? 13 : 14 }}>
          <thead>
            <tr style={{ borderBottom: "2px solid #333" }}>
              {headers.map(h => (
                <th key={h} style={{ padding: "6px 8px", textAlign: h === "Manager" ? "left" : "center", color: "#888", fontWeight: 600, fontSize: 11, whiteSpace: "nowrap" }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {managers.map((m, i) => {
              const streakLabel = m.streak === 0 ? "—" : m.streak > 0 ? `W${m.streak}` : `L${Math.abs(m.streak)}`;
              const streakColor = m.streak > 0 ? "#2ecc71" : m.streak < 0 ? "#2176d2" : "#888";
              const inPlayoffs  = i < PLAYOFF_SPOTS;
              const onBubble    = i === PLAYOFF_SPOTS - 1;
              const justOut     = i === PLAYOFF_SPOTS;
              const rowBg = inPlayoffs
                ? (onBubble ? "rgba(233,196,106,0.05)" : "rgba(46,204,113,0.04)")
                : i % 2 === 0 ? "transparent" : "rgba(255,255,255,0.02)";
              const leftBorder = inPlayoffs
                ? (onBubble ? "3px solid #e9c46a" : "3px solid #2ecc71")
                : "3px solid transparent";
              return (
                <tr key={m.rosterId} style={{ borderBottom: "1px solid #222", background: rowBg, borderLeft: leftBorder }}>
                  <td style={{ padding: "8px", textAlign: "center", color: "#666", fontWeight: 600 }}>{i + 1}</td>
                  <td style={{ padding: "8px" }}><MgrName name={m.name} size={24} ddLogos={ddLogos} /></td>
                  <td style={{ padding: "8px", textAlign: "center", color: "#2ecc71", fontWeight: 700 }}>{m.wins}</td>
                  <td style={{ padding: "8px", textAlign: "center", color: "#2176d2", fontWeight: 700 }}>{m.losses}</td>
                  <td style={{ padding: "8px", textAlign: "center" }}>{m.pf.toFixed(2)}</td>
                  {!mobile && <td style={{ padding: "8px", textAlign: "center", color: "#888" }}>{m.pa.toFixed(2)}</td>}
                  <td style={{ padding: "8px", textAlign: "center", color: streakColor, fontWeight: 700 }}>{streakLabel}</td>
                  <td style={{ padding: "6px 8px", textAlign: "center", whiteSpace: "nowrap" }}>
                    {inPlayoffs && !onBubble && <span style={{ fontSize: 9, fontWeight: 800, color: "#2ecc71", background: "rgba(46,204,113,0.15)", border: "1px solid rgba(46,204,113,0.3)", borderRadius: 4, padding: "2px 5px", letterSpacing: 0.4 }}>IN</span>}
                    {onBubble  && <span style={{ fontSize: 9, fontWeight: 800, color: "#e9c46a", background: "rgba(233,196,106,0.15)", border: "1px solid rgba(233,196,106,0.3)", borderRadius: 4, padding: "2px 5px", letterSpacing: 0.4 }}>BUBBLE</span>}
                    {justOut   && <span style={{ fontSize: 9, fontWeight: 800, color: "#2176d2", background: "rgba(33,118,210,0.15)",   border: "1px solid rgba(33,118,210,0.3)",   borderRadius: 4, padding: "2px 5px", letterSpacing: 0.4 }}>OUT</span>}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      <div style={{ marginTop: 8, fontSize: 11, color: "#444" }}>
        Top {PLAYOFF_SPOTS} teams advance · Tiebreaker: PF
      </div>
    </div>
  );
}

// ── Pre-computed historical lookup tables (built once at module load) ─────────

// Flat sorted arrays built from DATA at startup — used for score ranking
const _allScoresSorted = (() => {
  const arr = [...(DATA.allScores.scores || [])];
  arr.sort((a, b) => b - a);
  return arr;
})();

// Top-80 attributed scores (with Year/Week/Manager), merged from both era segments
const _topAttributed = (() => {
  const seg = DATA.topScoresBySegment || {};
  const all = Object.values(seg).flat();
  all.sort((a, b) => b.Points - a.Points);
  return all; // [{ Points, Year, Week, Manager, ... }]
})();

// Bottom-80 attributed scores
const _worstAttributed = (() => {
  const seg = DATA.worstScoresBySegment || {};
  const all = Object.values(seg).flat();
  all.sort((a, b) => a.Points - b.Points);
  return all;
})();

// Per-manager scores sorted descending (for personal rank lookups)
const _mgrScoresSorted = (() => {
  const out = {};
  const dist = DATA.scoreDistByManager || {};
  Object.keys(dist).forEach(mgr => {
    out[mgr] = [...(dist[mgr].scores || [])].sort((a, b) => b - a);
  });
  return out;
})();

// Ordinal helper
function _ord(n) {
  const s = ['th','st','nd','rd'];
  const v = n % 100;
  return n + (s[(v-20)%10] || s[v] || s[0]);
}

// Thresholds — still used for alert gating
const HIST = {
  HIGH_SCORE:   164.02,
  LOW_SCORE:     55.20,
  BLOWOUT:       54.70,
  CLOSE_GAME:     4.70,
};

// Build rich context for a single score: all-time rank, personal rank, "highest since" context
function buildScoreContext(score, managerName) {
  const ctx = {};

  // ── 1. All-time rank ──────────────────────────────────────────────────────
  const allRank = _allScoresSorted.findIndex(s => s <= score) + 1;
  ctx.allTimeRank  = allRank;
  ctx.allTimeTotal = _allScoresSorted.length;

  // ── 2. Personal rank + previous personal high ─────────────────────────────
  const mgrScores = _mgrScoresSorted[managerName] || [];
  const persRank  = mgrScores.findIndex(s => s <= score) + 1;
  ctx.personalRank  = persRank;
  ctx.personalTotal = mgrScores.length;

  // Find the next score above this one in their personal history
  const prevPersonalValue = mgrScores.find(s => s > score) || null;
  if (prevPersonalValue) {
    // Look up week/year in the attributed list
    const attr = _topAttributed.find(e => e.Manager === managerName && Math.abs(e.Points - prevPersonalValue) < 0.01);
    ctx.prevPersonal = attr
      ? { pts: prevPersonalValue, year: attr.Year, week: attr.Week }
      : { pts: prevPersonalValue, year: null, week: null };
  } else {
    ctx.prevPersonal = null; // this IS their personal best
  }

  // ── 3. League-wide "highest since" ───────────────────────────────────────
  // Find the most recent attributed score >= score that belongs to someone else
  // "Most recent" = sort by year desc, week desc among those with Points >= score
  const higher = _topAttributed.filter(e => e.Points >= score - 0.01);
  higher.sort((a, b) => b.Year - a.Year || b.Week - a.Week);
  // The first entry that isn't this exact score
  const prevLeague = higher.find(e => !(e.Manager === managerName && Math.abs(e.Points - score) < 0.01));
  ctx.prevLeague = prevLeague
    ? { pts: prevLeague.Points, year: prevLeague.Year, week: prevLeague.Week, mgr: prevLeague.Manager }
    : null;

  return ctx;
}

// Build rich context for a LOW score
function buildLowScoreContext(score, managerName) {
  const ctx = {};
  const allRank = _allScoresSorted.slice().reverse().findIndex(s => s >= score) + 1;
  ctx.allTimeRank  = allRank;
  ctx.allTimeTotal = _allScoresSorted.length;

  const mgrScores = [...(_mgrScoresSorted[managerName] || [])].reverse();
  const persRank  = mgrScores.findIndex(s => s >= score) + 1;
  ctx.personalRank  = persRank;
  ctx.personalTotal = mgrScores.length;

  // Previous personal low (next score below this one)
  const prevLowValue = mgrScores.find(s => s < score) || null;
  if (prevLowValue) {
    const attr = _worstAttributed.find(e => e.Manager === managerName && Math.abs(e.Points - prevLowValue) < 0.01);
    ctx.prevPersonal = attr
      ? { pts: prevLowValue, year: attr.Year, week: attr.Week }
      : { pts: prevLowValue, year: null, week: null };
  } else {
    ctx.prevPersonal = null;
  }

  // League-wide "lowest since"
  const lower = _worstAttributed.filter(e => e.Points <= score + 0.01);
  lower.sort((a, b) => b.Year - a.Year || b.Week - a.Week);
  const prevLeague = lower.find(e => !(e.Manager === managerName && Math.abs(e.Points - score) < 0.01));
  ctx.prevLeague = prevLeague
    ? { pts: prevLeague.Points, year: prevLeague.Year, week: prevLeague.Week, mgr: prevLeague.Manager }
    : null;

  return ctx;
}

// Returns an array of alert objects for a matchup
function getMatchupAlerts(teamA, teamB) {
  const apts = teamA.points;
  const bpts = teamB.points;
  const bothScored = apts > 0 && bpts > 0;
  const margin     = Math.abs(apts - bpts);
  const alerts     = [];

  if (!bothScored) return alerts;

  // High score alerts
  [teamA, teamB].forEach(t => {
    if (t.points < HIST.HIGH_SCORE) return;
    const ctx = buildScoreContext(t.points, t.name);
    const firstName = t.name.split(' ')[0];

    // Line 1: all-time rank
    let detail = `${_ord(ctx.allTimeRank)} highest score in league history (${ctx.allTimeTotal} total games).`;

    // Line 2: personal rank + previous personal high context
    if (ctx.personalRank === 1) {
      detail += ` New career high for ${firstName}!`;
    } else {
      detail += ` ${firstName}'s ${_ord(ctx.personalRank)} best ever`;
      if (ctx.prevPersonal) {
        if (ctx.prevPersonal.year) {
          detail += ` — last scored higher in Wk ${ctx.prevPersonal.week} ${ctx.prevPersonal.year} (${ctx.prevPersonal.pts.toFixed(2)} pts)`;
        } else {
          detail += ` — previous best was ${ctx.prevPersonal.pts.toFixed(2)} pts`;
        }
      }
      detail += '.';
    }

    // Line 3: league-wide "highest since"
    if (ctx.prevLeague) {
      const lg = ctx.prevLeague;
      detail += ` Last time anyone in the league scored this high: ${lg.mgr.split(' ')[0]} scored ${lg.pts.toFixed(2)} in Wk ${lg.week} ${lg.year}.`;
    } else {
      detail += ` No one in league history has scored this high.`;
    }

    alerts.push({ icon: '🔥', label: 'Historic score', color: '#e9c46a', detail });
  });

  // Low score alert
  [teamA, teamB].forEach(t => {
    if (t.points <= 0 || t.points > HIST.LOW_SCORE) return;
    const ctx = buildLowScoreContext(t.points, t.name);
    const firstName = t.name.split(' ')[0];

    let detail = `${_ord(ctx.allTimeRank)} lowest score in league history.`;

    if (ctx.personalRank === 1) {
      detail += ` Career low for ${firstName}.`;
    } else {
      detail += ` ${firstName}'s ${_ord(ctx.personalRank)} worst ever`;
      if (ctx.prevPersonal) {
        if (ctx.prevPersonal.year) {
          detail += ` — last scored lower in Wk ${ctx.prevPersonal.week} ${ctx.prevPersonal.year} (${ctx.prevPersonal.pts.toFixed(2)} pts)`;
        } else {
          detail += ` — previous worst was ${ctx.prevPersonal.pts.toFixed(2)} pts`;
        }
      }
      detail += '.';
    }

    if (ctx.prevLeague) {
      const lg = ctx.prevLeague;
      detail += ` Last time anyone scored this low: ${lg.mgr.split(' ')[0]} scored ${lg.pts.toFixed(2)} in Wk ${lg.week} ${lg.year}.`;
    }

    alerts.push({ icon: '💀', label: 'All-time low', color: '#2176d2', detail });
  });

  // Blowout alert
  if (margin >= HIST.BLOWOUT) {
    const winner = apts > bpts ? teamA : teamB;
    const loser  = apts > bpts ? teamB : teamA;
    const blowouts = DATA.biggestBlowouts || [];
    const blowoutRank = blowouts.filter(b => b.Margin > margin).length + 1;
    let detail = `${margin.toFixed(2)}-pt margin — ${_ord(blowoutRank)} largest blowout in league history.`;
    if (blowoutRank > 1) {
      const prevBlowout = blowouts[blowoutRank - 2]; // next bigger one
      if (prevBlowout) detail += ` Last bigger blowout: ${prevBlowout.Winner.split(' ')[0]} over ${prevBlowout.Loser.split(' ')[0]} by ${prevBlowout.Margin.toFixed(2)} pts in Wk ${prevBlowout.Week} ${prevBlowout.Year}.`;
    }
    alerts.push({ icon: '💥', label: 'Historic blowout', color: '#f4a261', detail });
  }

  // Close game alert
  if (margin <= HIST.CLOSE_GAME && margin > 0) {
    const close = DATA.closestMatchups || [];
    const closeRank = close.filter(c => c.Margin < margin).length + 1;
    let detail = `${margin.toFixed(2)}-pt margin — ${_ord(closeRank)} closest game in league history.`;
    if (closeRank > 1) {
      const prevClose = close[closeRank - 2];
      if (prevClose) detail += ` Last closer: ${prevClose.Winner.split(' ')[0]} over ${prevClose.Loser.split(' ')[0]} by ${prevClose.Margin.toFixed(2)} pts in Wk ${prevClose.Week} ${prevClose.Year}.`;
    }
    alerts.push({ icon: '⚡', label: 'Photo finish', color: '#64b5f6', detail });
  }

  // Shootout alert (both over 140)
  if (apts >= 140 && bpts >= 140) {
    alerts.push({ icon: '🏆', label: 'Shootout', color: '#2ecc71',
      detail: `Both managers over 140 pts — one of the highest-scoring matchups in league history.` });
  }

  return alerts;
}

function CSMatchupCards({ matchups, week }) {
  const mobile = useMobile();
  return (
    <div>
      <div style={{ fontSize: 11, fontWeight: 700, color: "#888", textTransform: "uppercase", letterSpacing: 0.8, marginBottom: 8 }}>
        Week {week} Matchups
      </div>
      <div style={{ display: "grid", gridTemplateColumns: mobile ? "1fr" : "1fr 1fr", gap: 12 }}>
        {matchups.map(m => {
          const aWinning = m.teamA.points > m.teamB.points;
          const bWinning = m.teamB.points > m.teamA.points;
          const alerts   = getMatchupAlerts(m.teamA, m.teamB);
          const bothScored = m.teamA.points > 0 && m.teamB.points > 0;
          const margin     = bothScored ? Math.abs(m.teamA.points - m.teamB.points) : null;
          return (
            <div key={m.matchupId} style={{
              background: "#1a1a1a", borderRadius: 10, padding: "14px 16px",
              border: alerts.length > 0 ? `1px solid ${alerts[0].color}55` : "1px solid #333",
              display: "flex", flexDirection: "column", gap: 0,
            }}>
              {[{ team: m.teamA, winning: aWinning }, { team: m.teamB, winning: bWinning }].map(({ team, winning }, idx) => (
                <div key={idx} style={{ display: "flex", justifyContent: "space-between", alignItems: "center",
                  padding: "7px 0", borderBottom: idx === 0 ? "1px solid #2a2a3e" : "none" }}>
                  <MgrName name={team.name} size={24} />
                  <span style={{ fontWeight: 700, fontSize: 16,
                    color: team.points >= HIST.HIGH_SCORE ? "#e9c46a"
                         : team.points > 0 && team.points <= HIST.LOW_SCORE ? "#2176d2"
                         : winning ? "#fff" : "#555",
                    minWidth: 60, textAlign: "right" }}>
                    {team.points > 0 ? team.points.toFixed(2) : "—"}
                  </span>
                </div>
              ))}
              {bothScored && (
                <div style={{ display: "flex", justifyContent: "flex-end", paddingTop: 5 }}>
                  <span style={{ fontSize: 11,
                    color: margin <= HIST.CLOSE_GAME ? "#64b5f6" : margin >= HIST.BLOWOUT ? "#f4a261" : "#555",
                    fontWeight: (margin <= HIST.CLOSE_GAME || margin >= HIST.BLOWOUT) ? 700 : 400 }}>
                    margin: {margin.toFixed(2)}
                  </span>
                </div>
              )}
              {alerts.length > 0 && (
                <div style={{ display: "flex", flexDirection: "column", gap: 6, marginTop: 10,
                  paddingTop: 10, borderTop: "1px solid #2a2a3e" }}>
                  {alerts.map((a, i) => (
                    <div key={i} style={{ display: "flex", alignItems: "flex-start", gap: 8 }}>
                      <span style={{ fontSize: 14, flexShrink: 0 }}>{a.icon}</span>
                      <div style={{ flex: 1 }}>
                        <span style={{ fontSize: 10, fontWeight: 800, color: a.color,
                          textTransform: "uppercase", letterSpacing: 0.6 }}>{a.label} — </span>
                        <span style={{ fontSize: 11, color: "#888", lineHeight: 1.5 }}>{a.detail}</span>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// Position badge colours — each position gets its own accent
const POS_COLORS = {
  QB: "#2176d2", RB: "#2a9d8f", WR: "#e9c46a",
  TE: "#9b5de5", K:  "#64b5f6", DEF: "#f4a261", DST: "#f4a261",
};

// Normalise a player entry — preview sends { name, pos, rank, team }, live API sends a plain string (player ID for now)
function resolvePlayer(p) {
  if (typeof p === "object" && p !== null) return p;
  return { name: String(p), pos: null, rank: null, team: null };
}

// TeamLogoSmall — mirrors ManagerLogo pattern: container sets size, SVG fills via preserveAspectRatio + overflow hidden
function TeamLogoSmall({ teamName, size = 24 }) {
  if (!teamName) return null;
  const svgStr   = NFL_LOGOS[teamName];
  const teamData = DATA.nflTeams[teamName];
  if (svgStr) {
    return (
      <span style={{ display: "inline-flex", alignItems: "center", flexShrink: 0,
        width: size, height: size, overflow: "hidden", verticalAlign: "middle" }}
        dangerouslySetInnerHTML={{ __html: svgStr }} />
    );
  }
  if (!teamData) return null;
  return (
    <span style={{ display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0,
      width: size, height: size, borderRadius: 3, background: teamData.color || "#1a1a1a",
      fontSize: size * 0.38, fontWeight: 700, color: teamData.secondary || "#fff", verticalAlign: "middle" }}>
      {teamData.abbr || "NFL"}
    </span>
  );
}

function PlayerPill({ player, accentColor }) {
  const { name, pos, rank, team } = resolvePlayer(player);
  const posColor  = pos ? (POS_COLORS[pos] || "#888") : null;
  const rankLabel = pos && rank ? `${pos}${rank}` : pos || null;

  return (
    <span style={{
      display: "inline-flex", alignItems: "center", gap: 0,
      background: `${accentColor}12`, border: `1px solid ${accentColor}30`,
      borderRadius: 6, overflow: "hidden", fontSize: 12,
    }}>
      {/* Position + rank badge */}
      {rankLabel && (
        <span style={{
          background: `${posColor}22`, borderRight: `1px solid ${accentColor}25`,
          color: posColor, fontWeight: 800, fontSize: 10,
          padding: "3px 6px", letterSpacing: 0.3, whiteSpace: "nowrap",
        }}>
          {rankLabel}
        </span>
      )}
      {/* Team logo — uses TeamLogoSmall for correct scaling via overflow hidden */}
      {team && (
        <span style={{ borderRight: `1px solid ${accentColor}25`, background: "rgba(255,255,255,0.04)",
          display: "inline-flex", alignItems: "center", flexShrink: 0 }}>
          <TeamLogoSmall teamName={team} size={24} />
        </span>
      )}
      {/* Player name */}
      <span style={{ color: accentColor, fontWeight: 600, padding: "3px 8px", whiteSpace: "nowrap" }}>
        {name}
      </span>
    </span>
  );
}

function CSTransactions({ transactions }) {
  const typeLabel = { free_agent: "Free Agent", waiver: "Waiver", trade: "Trade" };
  const typeColor = { free_agent: "#2a9d8f", waiver: "#e9c46a", trade: "#9b5de5" };

  if (!transactions.length) return (
    <div>
      <div style={{ fontSize: 11, fontWeight: 700, color: "#888", textTransform: "uppercase", letterSpacing: 0.8, marginBottom: 8 }}>Recent Transactions</div>
      <div style={{ color: "#666", fontSize: 13, padding: "12px 0" }}>No recent transactions found.</div>
    </div>
  );

  return (
    <div>
      <div style={{ fontSize: 11, fontWeight: 700, color: "#888", textTransform: "uppercase", letterSpacing: 0.8, marginBottom: 8 }}>
        Recent Transactions
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
        {transactions.map((tx, i) => {
          const managerName = tx.managerName
            || (tx.rosterId ? (tx.rosterIdToName?.[tx.rosterId] || `Roster ${tx.rosterId}`) : "Unknown");
          const added   = tx.addedPlayers   || Object.keys(tx.adds   || {});
          const dropped = tx.droppedPlayers || Object.keys(tx.drops  || {});
          const date    = tx.ts ? new Date(tx.ts).toLocaleDateString("en-US", { month: "short", day: "numeric" }) : "";
          const color   = typeColor[tx.type] || "#888";
          const label   = typeLabel[tx.type] || tx.type;
          const isTrade = tx.type === "trade";

          return (
            <div key={i} style={{ background: "#1a1a1a", border: "1px solid #2a2a3e", borderLeft: `3px solid ${color}`, borderRadius: 10, padding: "12px 16px", display: "flex", flexDirection: "column", gap: 8 }}>
              {/* Header: type badge + date */}
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <span style={{ fontSize: 10, fontWeight: 700, color, textTransform: "uppercase", letterSpacing: 0.8,
                  background: `${color}18`, border: `1px solid ${color}44`, borderRadius: 4, padding: "2px 7px" }}>
                  {label}
                </span>
                <span style={{ fontSize: 11, color: "#555" }}>{date}</span>
              </div>
              {/* Manager — with trade partner arrow, both tappable */}
              <div style={{ fontSize: 13, display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
                <MgrName name={managerName} size={22} />
                {isTrade && tx.tradePartner && (
                  <>
                    <span style={{ color: "#555" }}>⇄</span>
                    <MgrName name={tx.tradePartner} size={22} />
                  </>
                )}
              </div>
              {/* Added players */}
              {added.length > 0 && (
                <div style={{ display: "flex", flexWrap: "wrap", gap: 6, alignItems: "center" }}>
                  <span style={{ fontSize: 12, color: "#2ecc71", fontWeight: 800, minWidth: 16 }}>+</span>
                  {added.map((p, j) => <PlayerPill key={j} player={p} accentColor="#2ecc71" />)}
                </div>
              )}
              {/* Dropped players */}
              {dropped.length > 0 && (
                <div style={{ display: "flex", flexWrap: "wrap", gap: 6, alignItems: "center" }}>
                  <span style={{ fontSize: 12, color: "#2176d2", fontWeight: 800, minWidth: 16 }}>−</span>
                  {dropped.map((p, j) => <PlayerPill key={j} player={p} accentColor="#2176d2" />)}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}


