// ── Main component ────────────────────────────────────────────────────────────

function CSPowerRankings({ managers, currentWeek }) {
  const mobile = useMobile();

  const ranked = React.useMemo(() => {
    if (!managers || managers.length === 0) return [];
    const n = managers.length;

    // W%
    const wPcts = managers.map(m => m.wins / Math.max(1, m.wins + m.losses));
    const maxWPct = Math.max(...wPcts, 0.001);

    // PF rank (0 = best)
    const sortedByPF = [...managers].sort((a, b) => b.pf - a.pf);
    const pfRankMap = {};
    sortedByPF.forEach((m, i) => { pfRankMap[m.name] = i; });

    // Streak range
    const streaks = managers.map(m => m.streak);
    const maxAbsStreak = Math.max(...streaks.map(Math.abs), 1);

    // Raw scores
    const withScores = managers.map(m => {
      const wPct    = m.wins / Math.max(1, m.wins + m.losses);
      const wScore  = (wPct / maxWPct) * 50;
      const pfRank  = pfRankMap[m.name];
      const pfScore = ((n - 1 - pfRank) / Math.max(n - 1, 1)) * 30;
      const strNorm = (m.streak / maxAbsStreak) * 0.5 + 0.5;
      const stScore = strNorm * 20;
      return { ...m, rawScore: wScore + pfScore + stScore };
    });

    // Normalize to 0-100
    const scores = withScores.map(m => m.rawScore);
    const minS = Math.min(...scores);
    const maxS = Math.max(...scores);
    const range = maxS - minS || 1;

    const normalized = withScores
      .map(m => ({ ...m, score: Math.round(((m.rawScore - minS) / range) * 100) }))
      .sort((a, b) => b.score - a.score);

    // ± movement vs stored rankings
    const storageKey = `nfl_pr_prev_${currentWeek}`;
    let prevRanks = {};
    try {
      const stored = localStorage.getItem(storageKey);
      if (stored) prevRanks = JSON.parse(stored);
    } catch(e) {}

    const result = normalized.map((m, i) => {
      const rank = i + 1;
      const prev = prevRanks[m.name];
      const delta = prev != null ? prev - rank : null;
      return { ...m, rank, delta };
    });

    // Store current rankings for next week comparison
    try {
      const toStore = {};
      result.forEach(m => { toStore[m.name] = m.rank; });
      localStorage.setItem(storageKey, JSON.stringify(toStore));
    } catch(e) {}

    return result;
  }, [managers, currentWeek]);

  if (ranked.length === 0) return (
    <div style={{ color:"#555", fontSize:14, padding:"32px 0", textAlign:"center" }}>
      No data available yet.
    </div>
  );

  const tiers = [
    { label:"Top tier",    color:"#2176d2", indices:[0,3] },
    { label:"Mid pack",    color:"#e9c46a", indices:[4,7] },
    { label:"Bottom tier", color:"#d42b2b", indices:[8,11] },
  ];

  const streakLabel = s => s > 0 ? `W${s}` : s < 0 ? `L${Math.abs(s)}` : "—";

  const colStyle = {
    rank:   { width:22, flexShrink:0, textAlign:"center" },
    name:   { flex:1, minWidth:0, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" },
    record: { width: mobile ? 36 : 42, flexShrink:0, textAlign:"center" },
    bar:    { flex: mobile ? 1 : 2, minWidth:0, display: mobile && "flex", alignItems: mobile && "center" },
    score:  { width:34, flexShrink:0, textAlign:"right" },
    delta:  { width:30, flexShrink:0, textAlign:"center" },
    streak: { width:28, flexShrink:0, textAlign:"center", display: mobile ? "none" : "block" },
  };

  return (
    <div style={{ display:"flex", flexDirection:"column", gap:0 }}>

      {/* Formula pill */}
      <div style={{ fontSize:11, color:"#555", background:"#111", borderRadius:6, padding:"6px 12px", marginBottom:12, lineHeight:1.5 }}>
        Score = W% (50%) + PF rank (30%) + streak (20%), normalized 0–100
      </div>

      {/* Column headers */}
      <div style={{ display:"flex", alignItems:"center", gap:8, padding:"0 12px 6px", fontSize:11, color:"#555", borderBottom:"1px solid #222" }}>
        <div style={colStyle.rank}>#</div>
        <div style={colStyle.name}>Manager</div>
        <div style={colStyle.record}>W–L</div>
        <div style={colStyle.bar}>Score</div>
        <div style={colStyle.score}>Pts</div>
        <div style={colStyle.delta}>±</div>
        <div style={colStyle.streak}>Streak</div>
      </div>

      {tiers.map(tier => {
        const tierManagers = ranked.slice(tier.indices[0], tier.indices[1] + 1);
        if (tierManagers.length === 0) return null;
        return (
          <div key={tier.label}>
            <div style={{ fontSize:10, color:tier.color, letterSpacing:1.5, textTransform:"uppercase",
              padding:"8px 12px 4px", fontFamily:"'Cooper Black',Georgia,serif" }}>
              {tier.label}
            </div>
            {tierManagers.map(m => (
              <div key={m.name} style={{
                display:"flex", alignItems:"center", gap:8,
                padding: mobile ? "9px 12px" : "10px 14px",
                background:"#0a0a0a",
                border:"1px solid #1a1a1a",
                borderRadius:8,
                marginBottom:6,
              }}>
                <div style={{ ...colStyle.rank, fontSize:13, fontWeight:500,
                  color: m.rank <= 4 ? "#2176d2" : m.rank >= 9 ? "#d42b2b" : "#555" }}>
                  {m.rank}
                </div>
                <div style={{ ...colStyle.name, fontSize: mobile ? 13 : 14, fontWeight:500, color:"#fff" }}>
                  {m.name.split(" ")[0]}
                </div>
                <div style={{ ...colStyle.record, fontSize:12, color:"#555" }}>
                  {m.wins}–{m.losses}
                </div>
                <div style={colStyle.bar}>
                  <div style={{ background:"#1a1a1a", borderRadius:3, height:6, width:"100%" }}>
                    <div style={{ height:6, borderRadius:3, width:`${m.score}%`,
                      background: m.rank <= 4 ? "#2176d2" : m.rank >= 9 ? "#d42b2b" : "#e9c46a",
                      transition:"width 0.4s ease" }} />
                  </div>
                </div>
                <div style={{ ...colStyle.score, fontSize:13, fontWeight:500, color:"#fff" }}>
                  {m.score}
                </div>
                <div style={{ ...colStyle.delta, fontSize:11 }}>
                  {m.delta === null ? (
                    <span style={{ color:"#333" }}>—</span>
                  ) : m.delta > 0 ? (
                    <span style={{ background:"#0a2a1a", color:"#2ecc71", borderRadius:4, padding:"2px 4px" }}>+{m.delta}</span>
                  ) : m.delta < 0 ? (
                    <span style={{ background:"#2a0a0a", color:"#d42b2b", borderRadius:4, padding:"2px 4px" }}>{m.delta}</span>
                  ) : (
                    <span style={{ color:"#333" }}>—</span>
                  )}
                </div>
                <div style={{ ...colStyle.streak, fontSize:11, color:"#555" }}>
                  {streakLabel(m.streak)}
                </div>
              </div>
            ))}
          </div>
        );
      })}

      <div style={{ fontSize:11, color:"#333", paddingTop:8, textAlign:"center" }}>
        ± shows movement from prior load · refreshes each page visit
      </div>
    </div>
  );
}

// ── SCORING SNAPSHOT ──────────────────────────────────────────────────────────
function CSScoringSnapshot({ managers, currentWeek }) {
  const mobile = useMobile();

  const MANAGER_AVG = {
    "Aaron Fay": 104.24, "Ben de Ruiter": 96.0, "Casey Rhoda": 93.9,
    "Eric Graef": 108.18, "Greg Cady": 105.37, "Greg Mulder": 109.11,
    "James Lazette": 109.81, "Jon Vander Molen": 103.01, "Jonathon Israel": 85.7,
    "Joshua Van Groningen": 108.94, "Christian Manes": 101.85,
    "Ross Van Groningen": 105.63, "Spencer Hower": 104.23, "Steve Vander Molen": 107.44,
    "Tim Hoekstra": 78.31, "Tommy Van Groningen": 67.72, "Trey Hugen": 110.28,
    "Tyler Goslinga": 109.43, "Vance Sipma": 102.75, "Zac Dewey": 101.49,
  };

  if (!managers || managers.length === 0) return (
    <div style={{ color:"#555", fontSize:14, padding:"32px 0", textAlign:"center" }}>No data available yet.</div>
  );

  // Get current week scores from matchups via managers (pf is season total — use it for sorting)
  // We rank by pf this week — managers sorted by pf descending
  const sorted = [...managers].sort((a, b) => b.pf - a.pf);
  const maxScore = sorted[0]?.pf || 1;

  return (
    <div style={{ display:"flex", flexDirection:"column", gap:0 }}>
      <div style={{ fontSize:11, color:"#555", background:"#111", borderRadius:6, padding:"6px 12px", marginBottom:12, lineHeight:1.5 }}>
        Season PF vs all-time scoring average · bar = season PF · line = career avg
      </div>
      <div style={{ display:"flex", alignItems:"center", gap:8, padding:"0 4px 6px", fontSize:11, color:"#555", borderBottom:"1px solid #222", marginBottom:6 }}>
        <span style={{ width:mobile?70:90, flexShrink:0 }}>Manager</span>
        <span style={{ flex:1 }}>Score vs avg</span>
        <span style={{ width:44, textAlign:"right", flexShrink:0 }}>PF</span>
        <span style={{ width:40, textAlign:"right", flexShrink:0 }}>Avg</span>
        <span style={{ width:44, textAlign:"center", flexShrink:0 }}>Delta</span>
      </div>
      {sorted.map((m, i) => {
        const avg = MANAGER_AVG[m.name] || 100;
        const score = m.pf;
        const delta = score - avg;
        const barPct = Math.min(100, (score / maxScore) * 100);
        const avgPct = Math.min(100, (avg / maxScore) * 100);
        const isAbove = delta >= 0;
        const barColor = i < 4 ? "#2176d2" : i >= sorted.length - 4 ? "#d42b2b" : "#e9c46a";
        return (
          <div key={m.name} style={{ display:"flex", alignItems:"center", gap:8, padding: mobile?"8px 4px":"9px 4px", borderBottom:"1px solid #111" }}>
            <span style={{ width:mobile?70:90, flexShrink:0, fontSize:mobile?12:13, fontWeight:500, color:"#fff", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
              {m.name.split(" ")[0]}
            </span>
            <div style={{ flex:1, minWidth:0, position:"relative" }}>
              <div style={{ background:"#1a1a1a", borderRadius:3, height:6, position:"relative" }}>
                <div style={{ height:6, borderRadius:3, width:`${barPct}%`, background:barColor, transition:"width 0.4s ease" }} />
                <div style={{ position:"absolute", top:-3, bottom:-3, left:`${avgPct}%`, width:2, background:"#555", borderRadius:1 }} />
              </div>
            </div>
            <span style={{ width:44, textAlign:"right", fontSize:13, fontWeight:500, color:"#fff", flexShrink:0 }}>{score.toFixed(1)}</span>
            <span style={{ width:40, textAlign:"right", fontSize:11, color:"#555", flexShrink:0 }}>{avg.toFixed(1)}</span>
            <span style={{ width:44, textAlign:"center", fontSize:11, flexShrink:0, padding:"2px 4px", borderRadius:4,
              background: isAbove ? "#0a2a1a" : "#2a0a0a",
              color: isAbove ? "#2ecc71" : "#d42b2b" }}>
              {isAbove ? "+" : ""}{delta.toFixed(1)}
            </span>
          </div>
        );
      })}
      <div style={{ fontSize:11, color:"#333", paddingTop:8, textAlign:"center" }}>
        Grey line = career avg · refreshes each page load
      </div>
    </div>
  );
}

// ── SCORING TRENDS ─────────────────────────────────────────────────────────────
function CSScoringTrends({ managers, currentWeek }) {
  const mobile = useMobile();

  if (!managers || managers.length === 0) return (
    <div style={{ color:"#555", fontSize:14, padding:"32px 0", textAlign:"center" }}>No data available yet.</div>
  );

  // Store weekly scores in localStorage keyed by week
  React.useEffect(() => {
    if (!currentWeek || managers.length === 0) return;
    try {
      const key = `nfl_weekly_scores_${currentWeek}`;
      const existing = localStorage.getItem(key);
      if (!existing) {
        const snap = {};
        managers.forEach(m => { snap[m.name] = m.pf; });
        localStorage.setItem(key, JSON.stringify(snap));
      }
    } catch(e) {}
  }, [managers, currentWeek]);

  // Build weekly history from localStorage
  const history = React.useMemo(() => {
    const result = {};
    managers.forEach(m => { result[m.name] = []; });
    if (!currentWeek) return result;
    try {
      for (let w = 1; w <= currentWeek; w++) {
        const stored = localStorage.getItem(`nfl_weekly_scores_${w}`);
        if (!stored) continue;
        const snap = JSON.parse(stored);
        managers.forEach(m => {
          if (snap[m.name] != null) result[m.name].push({ week: w, score: snap[m.name] });
        });
      }
    } catch(e) {}
    return result;
  }, [managers, currentWeek]);

  const sorted = [...managers].sort((a, b) => b.pf - a.pf);
  const allScores = Object.values(history).flat().map(x => x.score);
  const minS = allScores.length ? Math.min(...allScores) * 0.9 : 60;
  const maxS = allScores.length ? Math.max(...allScores) * 1.05 : 200;

  const sparkPoints = (pts) => {
    if (!pts || pts.length === 0) return "";
    const W = 160; const H = 28;
    return pts.map((p, i) => {
      const x = pts.length === 1 ? W/2 : (i / (pts.length - 1)) * W;
      const y = H - ((p.score - minS) / (maxS - minS)) * H;
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    }).join(" ");
  };

  const trendLabel = (pts) => {
    if (!pts || pts.length < 2) return { label:"—", color:"#555" };
    const last = pts[pts.length - 1].score;
    const prev = pts[pts.length - 2].score;
    const diff = last - prev;
    if (diff > 10) return { label:"↑ hot", color:"#2ecc71" };
    if (diff < -10) return { label:"↓ cold", color:"#d42b2b" };
    return { label:"steady", color:"#555" };
  };

  return (
    <div style={{ display:"flex", flexDirection:"column", gap:0 }}>
      <div style={{ fontSize:11, color:"#555", background:"#111", borderRadius:6, padding:"6px 12px", marginBottom:12, lineHeight:1.5 }}>
        Week-by-week scoring sparklines · builds automatically each week
      </div>
      {currentWeek && (
        <div style={{ fontSize:11, color:"#555", marginBottom:8, paddingLeft:4 }}>
          Week 1 → Week {currentWeek}
        </div>
      )}
      {sorted.map(m => {
        const pts = history[m.name] || [];
        const trend = trendLabel(pts);
        const points = sparkPoints(pts);
        return (
          <div key={m.name} style={{ display:"flex", alignItems:"center", gap:8, padding: mobile?"7px 4px":"8px 4px", borderBottom:"1px solid #111" }}>
            <span style={{ width:mobile?70:90, flexShrink:0, fontSize:mobile?12:13, fontWeight:500, color:"#fff", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
              {m.name.split(" ")[0]}
            </span>
            <div style={{ flex:1, minWidth:0 }}>
              <svg viewBox="0 0 160 28" style={{ width:"100%", height:28, display:"block" }}>
                {points && <polyline points={points} fill="none" stroke="#2176d2" strokeWidth="1.5" />}
                {pts.map((p, i) => {
                  const W = 160; const H = 28;
                  const x = pts.length === 1 ? W/2 : (i / (pts.length - 1)) * W;
                  const y = H - ((p.score - minS) / (maxS - minS)) * H;
                  return <circle key={i} cx={x.toFixed(1)} cy={y.toFixed(1)} r="2.5" fill="#2176d2" />;
                })}
                {pts.length === 0 && (
                  <line x1="0" y1="14" x2="160" y2="14" stroke="#222" strokeWidth="1" strokeDasharray="4,4" />
                )}
              </svg>
            </div>
            <span style={{ width:mobile?60:80, textAlign:"right", fontSize:11, color:trend.color, flexShrink:0, fontWeight:500 }}>
              {trend.label}
            </span>
            <span style={{ width:44, textAlign:"right", fontSize:11, color:"#555", flexShrink:0 }}>
              {pts.length > 0 ? pts[pts.length-1].score.toFixed(1) : "—"}
            </span>
          </div>
        );
      })}
      <div style={{ fontSize:11, color:"#333", paddingTop:8, textAlign:"center" }}>
        Trend labels update when adjacent weeks differ by &gt;10 pts
      </div>
    </div>
  );
}

// ── LIVE LUCK INDEX ────────────────────────────────────────────────────────────
function CSLuckIndex({ managers, currentWeek }) {
  const mobile = useMobile();

  if (!managers || managers.length === 0) return (
    <div style={{ color:"#555", fontSize:14, padding:"32px 0", textAlign:"center" }}>No data available yet.</div>
  );

  // Expected wins: each week, count how many other managers you would have beaten
  // We approximate using season PF and games played
  const luck = React.useMemo(() => {
    const n = managers.length;
    const gamesPlayed = managers[0] ? managers[0].wins + managers[0].losses : 0;
    if (gamesPlayed === 0) return managers.map(m => ({ ...m, expectedWins: 0, luckDelta: 0 }));

    // Expected win% per week = rank among all scorers / (n-1)
    // Approximate: use season PF rank to estimate expected wins per game
    const sorted = [...managers].sort((a, b) => b.pf - a.pf);
    return sorted.map((m, i) => {
      // Expected wins based on PF rank: top scorer would beat everyone each week
      const pfRank = i; // 0 = best
      const expectedWPct = (n - 1 - pfRank) / (n - 1);
      const expectedWins = parseFloat((expectedWPct * gamesPlayed).toFixed(1));
      const actualWins = m.wins;
      const luckDelta = parseFloat((actualWins - expectedWins).toFixed(1));
      return { ...m, expectedWins, luckDelta };
    }).sort((a, b) => a.luckDelta - b.luckDelta); // unluckiest first
  }, [managers]);

  const maxAbs = Math.max(...luck.map(m => Math.abs(m.luckDelta)), 0.5);

  return (
    <div style={{ display:"flex", flexDirection:"column", gap:0 }}>
      <div style={{ fontSize:11, color:"#555", background:"#111", borderRadius:6, padding:"6px 12px", marginBottom:12, lineHeight:1.5 }}>
        Actual wins minus expected wins · expected = how many managers you'd beat each week by PF
      </div>
      <div style={{ display:"flex", alignItems:"center", gap:8, padding:"0 4px 6px", fontSize:11, color:"#555", borderBottom:"1px solid #222", marginBottom:6 }}>
        <span style={{ width:mobile?70:90, flexShrink:0 }}>Manager</span>
        <span style={{ flex:1, textAlign:"center" }}>← unlucky · lucky →</span>
        <span style={{ width:36, textAlign:"right", flexShrink:0 }}>±W</span>
        <span style={{ width:mobile?48:56, textAlign:"right", flexShrink:0 }}>Actual</span>
        <span style={{ width:mobile?48:56, textAlign:"right", flexShrink:0 }}>Expect</span>
      </div>
      {luck.map(m => {
        const pct = Math.abs(m.luckDelta) / maxAbs * 48;
        const isLucky = m.luckDelta >= 0;
        const color = isLucky ? "#2176d2" : "#d42b2b";
        const gp = m.wins + m.losses;
        return (
          <div key={m.name} style={{ display:"flex", alignItems:"center", gap:8, padding:mobile?"8px 4px":"9px 4px", borderBottom:"1px solid #111" }}>
            <span style={{ width:mobile?70:90, flexShrink:0, fontSize:mobile?12:13, fontWeight:500, color:"#fff", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
              {m.name.split(" ")[0]}
            </span>
            <div style={{ flex:1, minWidth:0, position:"relative" }}>
              <div style={{ background:"#1a1a1a", borderRadius:3, height:8, position:"relative" }}>
                <div style={{ position:"absolute", left:"50%", top:0, bottom:0, width:1.5, background:"#333" }} />
                {isLucky ? (
                  <div style={{ position:"absolute", left:"50%", width:`${pct}%`, height:8, background:color, borderRadius:"0 3px 3px 0" }} />
                ) : (
                  <div style={{ position:"absolute", right:`${50}%`, width:`${pct}%`, height:8, background:color, borderRadius:"3px 0 0 3px" }} />
                )}
              </div>
            </div>
            <span style={{ width:36, textAlign:"right", fontSize:13, fontWeight:500, color, flexShrink:0 }}>
              {m.luckDelta > 0 ? "+" : ""}{m.luckDelta}
            </span>
            <span style={{ width:mobile?48:56, textAlign:"right", fontSize:12, color:"#fff", flexShrink:0 }}>
              {m.wins}–{m.losses}
            </span>
            <span style={{ width:mobile?48:56, textAlign:"right", fontSize:12, color:"#555", flexShrink:0 }}>
              {m.expectedWins}–{gp > 0 ? (gp - m.expectedWins).toFixed(1) : "0"}
            </span>
          </div>
        );
      })}
      <div style={{ fontSize:11, color:"#333", paddingTop:8, textAlign:"center" }}>
        Expected record based on season PF rank · updates live each page load
      </div>
    </div>
  );
}

// ── WEEKLY RECAP ──────────────────────────────────────────────────────────────
function CSWeeklyRecap({ managers, matchups, transactions, currentWeek }) {
  const mobile = useMobile();

  if (!matchups || matchups.length === 0 || !managers || managers.length === 0) return (
    <div style={{ color:"#555", fontSize:14, padding:"32px 0", textAlign:"center" }}>
      No matchup data available yet for Week {currentWeek}.
    </div>
  );

  const MANAGER_AVG = {
    "Aaron Fay":104.24,"Ben de Ruiter":96.0,"Casey Rhoda":93.9,
    "Eric Graef":108.18,"Greg Cady":105.37,"Greg Mulder":109.11,
    "James Lazette":109.81,"Jon Vander Molen":103.01,"Jonathon Israel":85.7,
    "Joshua Van Groningen":108.94,"Christian Manes":101.85,
    "Ross Van Groningen":105.63,"Spencer Hower":104.23,"Steve Vander Molen":107.44,
    "Tim Hoekstra":78.31,"Tommy Van Groningen":67.72,"Trey Hugen":110.28,
    "Tyler Goslinga":109.43,"Vance Sipma":102.75,"Zac Dewey":101.49,
  };

  // Flatten all scores this week
  const allScores = matchups.flatMap(m => [
    { name: m.teamA.name, score: m.teamA.points, won: m.teamA.points > m.teamB.points, opponent: m.teamB.name, oppScore: m.teamB.points },
    { name: m.teamB.name, score: m.teamB.points, won: m.teamB.points > m.teamA.points, opponent: m.teamA.name, oppScore: m.teamA.points },
  ]);

  const sorted = [...allScores].sort((a, b) => b.score - a.score);
  const highscorer = sorted[0];
  const lowscorer  = sorted[sorted.length - 1];

  // Blowout & nail-biter
  const margins = matchups.map(m => ({
    ...m, margin: Math.abs(m.teamA.points - m.teamB.points),
    winner: m.teamA.points > m.teamB.points ? m.teamA : m.teamB,
    loser:  m.teamA.points > m.teamB.points ? m.teamB : m.teamA,
  }));
  const blowout   = [...margins].sort((a, b) => b.margin - a.margin)[0];
  const nailbiter = [...margins].sort((a, b) => a.margin - b.margin)[0];

  // Cursed: highest scorer who lost
  const cursed = [...allScores].filter(s => !s.won).sort((a, b) => b.score - a.score)[0];

  // Streaks from managers
  const longestWin  = [...managers].filter(m => m.streak > 0).sort((a, b) => b.streak - a.streak)[0];
  const longestLoss = [...managers].filter(m => m.streak < 0).sort((a, b) => a.streak - b.streak)[0];

  // ── All-time record checks ──
  // Get 12-team top scores (current era)
  const topScores12 = DATA.topScoresBySegment?.["10_12"] || DATA.topScoresBySegment?.["12_14"] || [];
  const allTopScores = Object.values(DATA.topScoresBySegment || {}).flat()
    .sort((a, b) => b.Points - a.Points);
  const worstScoresAll = Object.values(DATA.worstScoresBySegment || {}).flat()
    .sort((a, b) => a.Points - b.Points);
  const allBlowouts = DATA.biggestBlowouts || [];
  const allClosest  = DATA.closestMatchups  || [];
  const allStreaks   = DATA.winStreaks       || [];

  // Count how many all-time top/worst scores each manager has
  // Use the same pre-computed arrays the High & Low Score Weeks report uses
  const topCountByMgr = {};
  (DATA.mostTopWeeks || []).forEach(m => { topCountByMgr[m.Manager] = m["Top Weeks"]; });
  const worstCountByMgr = {};
  (DATA.mostLowWeeks || []).forEach(m => { worstCountByMgr[m.Manager] = m["Low Weeks"]; });

  const histRank = (score, list, field, ascending=false) => {
    const sorted = [...list].sort((a,b) => ascending ? a[field]-b[field] : b[field]-a[field]);
    const rank = sorted.findIndex(s => ascending ? score <= s[field] : score >= s[field]);
    return rank >= 0 && rank < 10 ? rank + 1 : null;
  };

  const highRank    = histRank(highscorer?.score, allTopScores, 'Points');
  const lowRank     = histRank(lowscorer?.score, worstScoresAll, 'Points', true);
  const blowRank    = histRank(blowout?.margin, allBlowouts, 'Margin');
  const nailRank    = histRank(nailbiter?.margin, allClosest, 'Margin', true);
  const streakRank  = longestWin ? histRank(longestWin.streak, allStreaks, 'Streak') : null;

  const firstName = n => n ? n.split(" ")[0] : "—";

  const Story = ({ label, labelColor="#555", accent, children, stat }) => (
    <div style={{
      background:"#0a0a0a", border:"1px solid #1a1a1a",
      borderLeft: accent ? `3px solid ${accent}` : "1px solid #1a1a1a",
      borderRadius: accent ? "0 8px 8px 0" : 8,
      padding: mobile ? "10px 12px" : "12px 16px", marginBottom:8
    }}>
      <div style={{ fontSize:10, fontWeight:500, textTransform:"uppercase", letterSpacing:1.5, color:labelColor, marginBottom:5 }}>{label}</div>
      <div style={{ fontSize: mobile?13:14, color:"#fff", lineHeight:1.6 }}>{children}</div>
      {stat && <div style={{ fontSize:11, color:"#555", marginTop:5 }}>{stat}</div>}
    </div>
  );

  const MatchupPill = ({ winner, winScore, loser, loseScore }) => (
    <div style={{ display:"inline-flex", alignItems:"center", gap:6, background:"#111", borderRadius:99, padding:"3px 10px", fontSize:12, marginTop:6 }}>
      <span style={{ fontWeight:500, color:"#fff" }}>{firstName(winner)}</span>
      <span style={{ color:"#2176d2", fontWeight:500 }}>{winScore.toFixed(1)}</span>
      <span style={{ color:"#333" }}>vs</span>
      <span style={{ color:"#555" }}>{firstName(loser)}</span>
      <span style={{ color:"#d42b2b" }}>{loseScore.toFixed(1)}</span>
    </div>
  );

  const histBadge = (rank) => rank ? (
    <span style={{ display:"inline-block", background:"#1a2a3a", color:"#2176d2", fontSize:10, padding:"1px 6px", borderRadius:4, marginLeft:6, fontWeight:500 }}>
      #{rank} all-time
    </span>
  ) : null;

  return (
    <div style={{ display:"flex", flexDirection:"column", gap:0 }}>
      <div style={{ fontSize:13, color:"#555", marginBottom:12, paddingBottom:8, borderBottom:"1px solid #222" }}>
        Week {currentWeek} · Auto-generated from live Sleeper data
      </div>

      {highscorer && (
        <Story label="High score of the week" labelColor="#2176d2" accent="#2176d2"
          stat={`${(highscorer.score - (MANAGER_AVG[highscorer.name]||100)).toFixed(1)} pts above career avg of ${(MANAGER_AVG[highscorer.name]||100).toFixed(1)}${topCountByMgr[highscorer.name] ? ` · ${topCountByMgr[highscorer.name]} all-time top score${topCountByMgr[highscorer.name] > 1 ? "s" : ""} in league history` : ""}`}>
          {firstName(highscorer.name)} put up <span style={{color:"#2176d2",fontWeight:500}}>{highscorer.score.toFixed(1)} points</span> — the highest score of the week.
          {highRank && <>{histBadge(highRank)} That ranks among the best single-week scores in league history.</>}
        </Story>
      )}

      {lowscorer && (
        <Story label="Low score of the week" labelColor="#d42b2b" accent="#d42b2b"
          stat={`${Math.abs(lowscorer.score - (MANAGER_AVG[lowscorer.name]||100)).toFixed(1)} pts below career avg of ${(MANAGER_AVG[lowscorer.name]||100).toFixed(1)}${worstCountByMgr[lowscorer.name] ? ` · ${worstCountByMgr[lowscorer.name]} all-time low score${worstCountByMgr[lowscorer.name] > 1 ? "s" : ""} in league history` : ""}`}>
          {firstName(lowscorer.name)} had a rough one, managing just <span style={{color:"#d42b2b",fontWeight:500}}>{lowscorer.score.toFixed(1)} points</span> — the lowest score in the league this week.
          {lowRank && <>{histBadge(lowRank)} One of the worst scores in league history.</>}
        </Story>
      )}

      {blowout && (
        <Story label="Blowout of the week"
          stat={`Margin: ${blowout.margin.toFixed(1)} pts`}>
          {firstName(blowout.winner.name)} left no doubt, winning by <span style={{color:"#fff",fontWeight:500}}>{blowout.margin.toFixed(1)} points</span>.
          {blowRank && <>{histBadge(blowRank)} One of the biggest blowouts in league history.</>}
          <div><MatchupPill winner={blowout.winner.name} winScore={blowout.winner.points} loser={blowout.loser.name} loseScore={blowout.loser.points} /></div>
        </Story>
      )}

      {nailbiter && nailbiter.margin < 10 && (
        <Story label="Nail-biter of the week"
          stat={`Margin: ${nailbiter.margin.toFixed(1)} pts`}>
          The closest game came down to just <span style={{color:"#fff",fontWeight:500}}>{nailbiter.margin.toFixed(1)} points</span> — {firstName(nailbiter.loser.name)} will be checking injury reports tonight.
          {nailRank && <>{histBadge(nailRank)} One of the closest matchups in league history.</>}
          <div><MatchupPill winner={nailbiter.winner.name} winScore={nailbiter.winner.points} loser={nailbiter.loser.name} loseScore={nailbiter.loser.points} /></div>
        </Story>
      )}

      {cursed && (
        <Story label="Cursed week award" labelColor="#BA7517" accent="#BA7517"
          stat={`${cursed.score.toFixed(1)} pts · Lost anyway`}>
          {firstName(cursed.name)} scored <span style={{color:"#BA7517",fontWeight:500}}>{cursed.score.toFixed(1)} points</span> — a score that would have beaten {allScores.filter(s => s.score < cursed.score).length} of {allScores.length - 1} managers this week. Unfortunately, they drew the wrong opponent. The fantasy gods have no mercy.
        </Story>
      )}

      {(longestWin || longestLoss) && (
        <Story label="Streak watch">
          {longestWin && <>
            <span style={{color:"#2176d2",fontWeight:500}}>{firstName(longestWin.name)}</span> is riding a <span style={{fontWeight:500}}>{longestWin.streak}-game win streak</span>.
            {streakRank && <>{histBadge(streakRank)} Approaching historic territory.</>}
          </>}
          {longestWin && longestLoss && " "}
          {longestLoss && <>
            <span style={{color:"#d42b2b",fontWeight:500}}>{firstName(longestLoss.name)}</span> has dropped {Math.abs(longestLoss.streak)} straight and needs a win badly.
          </>}
        </Story>
      )}

      <div style={{ height:1, background:"#1a1a1a", margin:"8px 0 12px" }} />
      <div style={{ fontSize:11, color:"#555", textTransform:"uppercase", letterSpacing:1, marginBottom:8 }}>Full results — Week {currentWeek}</div>

      <div style={{ display:"grid", gridTemplateColumns: mobile ? "1fr" : "1fr 1fr", gap:6 }}>
        {matchups.map((m, i) => {
          const aWon = m.teamA.points > m.teamB.points;
          return (
            <div key={i} style={{ background:"#0a0a0a", border:"1px solid #1a1a1a", borderRadius:8, padding:"10px 12px" }}>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:4 }}>
                <span style={{ fontSize:13, fontWeight:500, color: aWon?"#fff":"#555" }}>{firstName(m.teamA.name)}</span>
                <span style={{ fontSize:13, fontWeight:500, color: aWon?"#2176d2":"#555" }}>{m.teamA.points.toFixed(1)}</span>
              </div>
              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                <span style={{ fontSize:13, color: !aWon?"#fff":"#555" }}>{firstName(m.teamB.name)}</span>
                <span style={{ fontSize:13, color: !aWon?"#2176d2":"#555" }}>{m.teamB.points.toFixed(1)}</span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function CurrentSeasonTab() {
  const mobile = useMobile();
  const [section, setSection] = React.useState("home");
  const { loading, error, leagueStatus, currentWeek, managers, matchups, transactions, lastFetched, refresh } = useSleeperLive();

  React.useEffect(() => { refresh(); }, [refresh]);

  const isOffseason = !leagueStatus || leagueStatus === "pre_draft" || leagueStatus === "drafting";
  const hasData     = managers.length > 0;

  const CS_TILES = [
    { key: "standings",      emoji: "🧾", label: "Standings",        sub: "Live W/L, PF, PA, streak & playoff picture",         color: "#2ecc71" },
    { key: "matchups",       emoji: "🕰️", label: "Week " + (currentWeek || "—") + " Matchups", sub: "Current week scores with historic alert detection",   color: "#e9c46a" },
    { key: "transactions",   emoji: "🔄", label: "Transactions",     sub: "Recent adds, drops & trades with player detail",      color: "#9b5de5" },
    { key: "powerrankings",  emoji: "📊", label: "Power Rankings",   sub: "Composite W%, PF & streak score for every manager",   color: "#2176d2" },
    { key: "scoringsnapshot",emoji: "📸", label: "Scoring Snapshot", sub: "This week's score vs each manager's all-time average", color: "#f4a261" },
    { key: "scoringtrends",  emoji: "📈", label: "Scoring Trends",   sub: "Week-by-week sparklines for all 12 managers",         color: "#2ecc71" },
    { key: "weeklyrecap",   emoji: "📰", label: "Commissioner's Report", sub: "Auto-generated weekly recap with all-time record alerts", color: "#e9c46a" },
  ];

  const activeTitle = CS_TILES.find(t => t.key === section);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: mobile ? 16 : 24 }}>

      

      {/* ── BACK BAR ── */}
      {section !== "home" && (
        <div style={{ display: "flex", alignItems: "center", gap: 10, borderBottom: "1px solid #222222", paddingBottom: 10 }}>
          <button onClick={() => setSection("home")} style={{
            background: "#1a1a1a", border: "1px solid #333", borderRadius: 8,
            color: "#aaa", cursor: "pointer", fontSize: mobile ? 13 : 14,
            padding: mobile ? "6px 12px" : "7px 16px", whiteSpace: "nowrap", flexShrink: 0,
          }}>← 2026 Season</button>
          <div style={{ fontFamily: "'Cooper Black', Georgia, serif", fontSize: mobile ? 18 : 22,
            color: "#e9c46a", letterSpacing: 2, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
            {activeTitle?.emoji} {activeTitle?.label}
          </div>
          {/* Refresh button — visible in section views */}
          <button onClick={refresh} disabled={loading} style={{
            marginLeft: "auto", flexShrink: 0,
            background: loading ? "#1a1a1a" : "#2176d2", color: loading ? "#555" : "#fff",
            border: "none", borderRadius: 8, padding: "6px 14px",
            fontWeight: 700, fontSize: 12, cursor: loading ? "not-allowed" : "pointer",
          }}>{loading ? "…" : "↻"}</button>
        </div>
      )}

      {/* ── HOME: tile grid ── */}
      {section === "home" && (
        <div style={{ display: "flex", flexDirection: "column", gap: mobile ? 16 : 20 }}>

          {/* Tab header with refresh */}
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: 10 }}>
            <div style={{ fontSize: mobile ? 13 : 14, color: "#555", letterSpacing: 1,
              textTransform: "uppercase", fontFamily: "'Cooper Black', Georgia, serif" }}>
              📡 Select a report
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              {lastFetched && (
                <span style={{ fontSize: 11, color: "#444" }}>
                  Updated {lastFetched.toLocaleTimeString()}
                </span>
              )}
              <button onClick={refresh} disabled={loading} style={{
                background: loading ? "#1a1a1a" : "#2176d2", color: loading ? "#555" : "#fff",
                border: "none", borderRadius: 8, padding: "6px 14px",
                fontWeight: 700, fontSize: 12, cursor: loading ? "not-allowed" : "pointer",
              }}>{loading ? "Loading…" : "↻ Refresh"}</button>
            </div>
          </div>

          {/* Error */}
          {error && (
            <div style={{ background: "rgba(33,118,210,0.12)", border: "1px solid #2176d2", borderRadius: 8, padding: "10px 14px", color: "#2176d2", fontSize: 13 }}>
              ⚠️ {error}
            </div>
          )}

          {/* Loading */}
          {loading && !hasData && (
            <div style={{ color: "#555", fontSize: 14, padding: "20px 0", textAlign: "center" }}>
              Connecting to Sleeper…
            </div>
          )}

          {/* Off-season state */}
          {!loading && isOffseason && <CSOffseason />}

          {/* Tile grid — only when data is live */}
          {hasData && !isOffseason && (
            <div style={{ display: "grid", gridTemplateColumns: mobile ? "1fr 1fr" : "1fr 1fr 1fr", gap: mobile ? 10 : 14 }}>
              {CS_TILES.map(t => (
                <button key={t.key} onClick={() => setSection(t.key)} style={{
                  background: "#0a0a0a",
                  border: `1px solid ${t.color}33`,
                  borderTop: `3px solid ${t.color}`,
                  borderRadius: 10,
                  padding: mobile ? "14px 10px" : "20px 16px",
                  cursor: "pointer",
                  textAlign: "left",
                  transition: "border-color 0.15s, background 0.15s",
                }}>
                  <div style={{ fontSize: mobile ? 26 : 32, lineHeight: 1, marginBottom: 8 }}>{t.emoji}</div>
                  <div style={{ color: t.color, fontFamily: "'Cooper Black', Georgia, serif",
                    fontSize: mobile ? 15 : 17, letterSpacing: 1, marginBottom: 4 }}>{t.label}</div>
                  <div style={{ color: "#444", fontSize: 11, lineHeight: 1.4 }}>{t.sub}</div>
                </button>
              ))}
            </div>
          )}
        </div>
      )}

      {/* ── SECTION VIEWS ── */}
      {section === "standings"    && <CSStandings managers={managers} ddLogos={true} />}
      {section === "matchups"     && matchups.length > 0 && <CSMatchupCards matchups={matchups} week={currentWeek} />}
      {section === "matchups"     && matchups.length === 0 && !loading && (
        <div style={{ color: "#555", fontSize: 14, padding: "32px 0", textAlign: "center" }}>
          No matchup data available yet for Week {currentWeek}.
        </div>
      )}
      {section === "transactions" && <CSTransactions transactions={transactions} />}
      {section === "powerrankings"   && <CSPowerRankings managers={managers} currentWeek={currentWeek} />}
      {section === "scoringsnapshot" && <CSScoringSnapshot managers={managers} currentWeek={currentWeek} />}
      {section === "scoringtrends"   && <CSScoringTrends managers={managers} currentWeek={currentWeek} />}
      {section === "luckindex"       && <CSLuckIndex managers={managers} currentWeek={currentWeek} />}
      {section === "weeklyrecap"     && <CSWeeklyRecap managers={managers} matchups={matchups} transactions={transactions} currentWeek={currentWeek} />}

    </div>
  );
}

