// ── SORTABLE STANDINGS TABLE ──────────────────────────────────────────────────
const SORT_CONFIGS = {
  rsRank:        { label: "RS Rank",       asc: (a, b) => a.RSRank - b.RSRank },
  manager:       { label: "Manager",       asc: (a, b) => a.Manager.localeCompare(b.Manager) },
  teamName:      { label: "Team Name",     asc: (a, b) => a["Team Name"].localeCompare(b["Team Name"]) },
  wins:          { label: "Record",        asc: (a, b) => a.Wins - b.Wins || a.PF - b.PF },
  pf:            { label: "Points For",    asc: (a, b) => a.PF - b.PF },
  pa:            { label: "Points Against",asc: (a, b) => a.PA - b.PA },
  playoffFinish: { label: "Playoff Finish",asc: (a, b) => a.PlayoffFinish - b.PlayoffFinish },
};

function StandingsTable({ standings, playoffCount, year }) {
  const mobile = useMobile();
  const { open: openMatchup } = useMatchup();
  const [sortKey, setSortKey] = useState("rsRank");
  const [sortDir, setSortDir] = useState("asc");

  const handleSort = (key) => {
    if (sortKey === key) {
      setSortDir(d => d === "asc" ? "desc" : "asc");
    } else {
      setSortKey(key);
      setSortDir("asc");
    }
  };

  const sorted = [...standings].sort((a, b) => {
    const result = SORT_CONFIGS[sortKey].asc(a, b);
    return sortDir === "asc" ? result : -result;
  });

  const cols = [
    { key: "rsRank",        header: "RS Rank" },
    { key: "manager",       header: "Manager" },
    { key: "teamName",      header: "Team Name" },
    { key: "wins",          header: "Record" },
    { key: "pf",            header: "Points For" },
    { key: "pa",            header: "Points Against" },
    { key: "playoffFinish", header: "Playoff Finish" },
  ];

  const arrow = (key) => sortKey === key ? (sortDir === "asc" ? " ↑" : " ↓") : "";

  const rowBg = (i) => i % 2 === 0 ? "#0d0d0d" : "#1a1a1a";
  if (mobile) return (
    <div style={{ display:"flex", flexDirection:"column", gap:4 }}>
      {sorted.map((s, i) => {
        const isPlayoff = s.ReachedPlayoffs === "Playoffs";
        const recColor = s.Wins > s.Losses ? "#2a9d8f" : s.Wins < s.Losses ? "#2176d2" : "#aaa";
        return (
          <div key={s.Manager} style={{ background: rowBg(i), borderRadius:6, padding:mobile ? "5px 7px" : "8px 10px", display:"flex", alignItems:"center", gap:8 }}>
            <span style={{ fontFamily:"'Cooper Black',Georgia,serif", fontSize:16, color: s.RSRank <= playoffCount ? "#e9c46a" : "#555", minWidth:22, textAlign:"center" }}>{rank(s.RSRank-1)}</span>
            <div style={{ flex:1, minWidth:0 }}>
              <MgrName name={s.Manager} />
              <div style={{ color:"#555", fontSize:11, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{s["Team Name"]}</div>
            </div>
            <div style={{ textAlign:"right", flexShrink:0 }}>
              <div style={{ color: recColor, fontWeight:600, fontSize:13 }}>{s.Record}</div>
              <div style={{ color:"#e9c46a", fontSize:11 }}>{s.PF.toFixed(1)} PF</div>
            </div>
            <div style={{ textAlign:"right", flexShrink:0, minWidth:36 }}>
              {isPlayoff
                ? <span style={{ color: s.PlayoffFinish===1 ? "#e9c46a" : "#2a9d8f", fontWeight:600, fontSize:12 }}>{s.PlayoffFinish===1 ? "👑" : `#${s.PlayoffFinish}`}</span>
                : <span style={{ color:"#444", fontSize:11 }}>—</span>}
            </div>
          </div>
        );
      })}
    </div>
  );

  return (
    <div style={{ overflowX: "auto" }}>
      <table style={{ width: "100%", borderCollapse: "collapse", fontSize: mobile ? 14 : 13 }}>
        <thead>
          <tr>
            {cols.map(col => (
              <th
                key={col.key}
                onClick={() => handleSort(col.key)}
                style={{
                  display: mobile && ["teamName","pa"].includes(col.key) ? "none" : undefined,
                  textAlign: "left", padding: "8px 12px", borderBottom: "1px solid #222222",
                  color: sortKey === col.key ? "#fff" : "#2176d2",
                  fontFamily: "'Cooper Black', Georgia, serif", letterSpacing: 1, fontSize: 14,
                  whiteSpace: "nowrap", cursor: "pointer", userSelect: "none",
                  background: sortKey === col.key ? "#181818" : "transparent",
                }}
              >
                {col.header}{arrow(col.key)}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {sorted.map((s, i) => {
            const isPlayoff = s.ReachedPlayoffs === "Playoffs";
            return (
              <tr key={mgr(s.Manager)} style={{ background: rowBg(i) }}>
                <td style={{ padding:mobile ? "6px 8px" : "9px 12px", borderBottom:"1px solid #1a1a1a", whiteSpace:"nowrap" }}>
                  <span style={{ fontFamily:"'Cooper Black',Georgia,serif", fontSize:17, color: s.RSRank<=playoffCount ? "#e9c46a" : "#555" }}>{rank(s.RSRank-1)}</span>
                </td>
                <td style={{ padding:mobile ? "6px 8px" : "9px 12px", borderBottom:"1px solid #1a1a1a", whiteSpace:"nowrap" }}>
                  <span style={{ display:"inline-flex", alignItems:"center", gap:5 }}><MgrName name={s.Manager} /></span>
                </td>
                <td style={{ display: mobile ? "none" : undefined, padding:mobile ? "6px 8px" : "9px 12px", borderBottom:"1px solid #1a1a1a", whiteSpace:"nowrap" }}>
                  <em style={{ color:"#aaa" }}>{s["Team Name"]}</em>
                </td>
                <td style={{ padding:mobile ? "6px 8px" : "9px 12px", borderBottom:"1px solid #1a1a1a", whiteSpace:"nowrap" }}>
                   <span style={{ color: s.Wins>s.Losses ? "#2a9d8f" : s.Wins<s.Losses ? "#2176d2" : "#aaa" }}>{s.Record}</span>
                </td>
                <td style={{ padding:mobile ? "6px 8px" : "9px 12px", borderBottom:"1px solid #1a1a1a", whiteSpace:"nowrap" }}>
                  <span style={{ color:"#e9c46a" }}>{s.PF.toFixed(1)}</span>
                </td>
                <td style={{ display: mobile ? "none" : undefined, padding:mobile ? "6px 8px" : "9px 12px", borderBottom:"1px solid #1a1a1a", whiteSpace:"nowrap" }}>
                  <span style={{ color:"#2176d2" }}>{s.PA > 0 ? s.PA.toFixed(1) : "—"}</span>
                </td>
                <td style={{ padding:mobile ? "6px 8px" : "9px 12px", borderBottom:"1px solid #1a1a1a", whiteSpace:"nowrap" }}>
                  {isPlayoff
                    ? <span style={{ color: s.PlayoffFinish===1 ? "#e9c46a" : "#2a9d8f", fontWeight:600 }}>{s.PlayoffFinish===1 ? "👑 " : ""}#{s.PlayoffFinish}</span>
                    : <span style={{ color:"#555" }}>Eliminated</span>}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

// ── PLAYOFF BRACKET ───────────────────────────────────────────────────────────
function PlayoffBracket({ year, playoffTeams }) {
  const mobile = useMobile();

  const byS = {};
  playoffTeams.forEach(t => { byS[t.RSRank] = t; });
  const n = playoffTeams.length;

  const wt = (a, b) => a.PlayoffFinish < b.PlayoffFinish ? a : b;

  // ── Dimensions ──────────────────────────────────────────────────────────────
  const CARD_W  = mobile ? 126 : 168;
  const CARD_H  = 72;
  const COL_GAP = mobile ? 20 : 40;
  const SLOT_GAP = 10;
  const LABEL_H  = 28;

  // ── Bracket data ─────────────────────────────────────────────────────────────
  let r1items, r2items, r3item;

  if (n === 6) {
    const wc1 = wt(byS[3], byS[6]);
    const wc2 = wt(byS[4], byS[5]);
    const sf1 = wt(byS[1], wc2);
    const sf2 = wt(byS[2], wc1);
    r1items = [
      { bye: byS[1] },
      { a: byS[4], b: byS[5] },
      { bye: byS[2] },
      { a: byS[3], b: byS[6] },
    ];
    r2items = [
      { a: byS[1], b: wc2 },
      { a: byS[2], b: wc1 },
    ];
    r3item = { a: sf1, b: sf2, isChamp: true };
  } else {
    // 8-team
    const q1 = wt(byS[1], byS[8]);
    const q2 = wt(byS[4], byS[5]);
    const q3 = wt(byS[2], byS[7]);
    const q4 = wt(byS[3], byS[6]);
    const sf1 = wt(q1, q2);
    const sf2 = wt(q3, q4);
    r1items = [
      { a: byS[1], b: byS[8] },
      { a: byS[4], b: byS[5] },
      { a: byS[2], b: byS[7] },
      { a: byS[3], b: byS[6] },
    ];
    r2items = [
      { a: q1, b: q2 },
      { a: q3, b: q4 },
    ];
    r3item = { a: sf1, b: sf2, isChamp: true };
  }

  // ── Position math ────────────────────────────────────────────────────────────
  const R1_SLOT_H = CARD_H + SLOT_GAP;
  const TOTAL_H   = LABEL_H + 4 * R1_SLOT_H - SLOT_GAP;
  const TOTAL_W   = 3 * CARD_W + 2 * COL_GAP;

  const r1CY   = (i) => LABEL_H + i * R1_SLOT_H + CARD_H / 2;
  const r1TopY = (i) => LABEL_H + i * R1_SLOT_H;
  const r2CY   = (i) => (r1CY(i * 2) + r1CY(i * 2 + 1)) / 2;
  const r2TopY = (i) => r2CY(i) - CARD_H / 2;
  const r3CY   = (r2CY(0) + r2CY(1)) / 2;
  const r3TopY = r3CY - CARD_H / 2;

  const colX = [0, CARD_W + COL_GAP, 2 * (CARD_W + COL_GAP)];
  const midX = [CARD_W + COL_GAP / 2, CARD_W + COL_GAP + CARD_W + COL_GAP / 2];

  const lc  = "#253050";
  const lcc = "#6a5a20";

  // ── Sub-components ───────────────────────────────────────────────────────────
  const TeamRow = ({ team, isWinner }) => {
    const isChamp = team.PlayoffFinish === 1;
    return (
      <div style={{
        display: "flex", alignItems: "center", gap: 5,
        height: CARD_H / 2, paddingLeft: 8, paddingRight: 6,
        opacity: isWinner ? 1 : 0.28,
      }}>
        <span style={{
          fontFamily: "'Cooper Black',Georgia,serif",
          fontSize: 11, color: isWinner ? "#2176d2" : "#333",
          minWidth: 14, textAlign: "center", flexShrink: 0,
        }}>#{team.RSRank}</span>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{
            color: isWinner ? (isChamp ? "#e9c46a" : getColor(team.Manager)) : "#3a3a5a",
            fontWeight: isWinner ? 700 : 400,
            fontSize: mobile ? 11 : 12,
            overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap",
          }}>
            {isChamp && isWinner ? "👑 " : ""}{firstName(team.Manager)}
          </div>
          <div style={{
            fontSize: 11, color: isWinner ? "#445" : "#222",
            overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap",
            fontStyle: "italic",
          }}>{team["Team Name"]}</div>
        </div>
      </div>
    );
  };

  const BracketCard = ({ item, style }) => {
    if (item.bye) {
      const t = item.bye;
      return (
        <div style={{
          position: "absolute", width: CARD_W, height: CARD_H,
          background: "#000000",
          border: `1px solid ${getColor(t.Manager)}22`,
          borderLeft: `3px solid ${getColor(t.Manager)}55`,
          borderRadius: 6, overflow: "hidden",
          display: "flex", flexDirection: "column", justifyContent: "center",
          ...style,
        }}>
          <div style={{ paddingLeft: 10, paddingRight: 8 }}>
            <div style={{ fontSize: 11, color: "#2a3a4a", fontFamily: "'Cooper Black',Georgia,serif", letterSpacing: 1.5, marginBottom: 4 }}>BYE</div>
            <div style={{ display: "flex", alignItems: "center", gap: 5 }}>
              <span style={{ fontFamily: "'Cooper Black',Georgia,serif", fontSize: 11, color: "#2176d2", minWidth: 14 }}>#{t.RSRank}</span>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ color: getColor(t.Manager), fontWeight: 700, fontSize: mobile ? 11 : 12, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                  {firstName(t.Manager)}
                </div>
                <div style={{ fontSize: 11, color: "#445", fontStyle: "italic", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                  {t["Team Name"]}
                </div>
              </div>
            </div>
          </div>
        </div>
      );
    }

    const winner = wt(item.a, item.b);
    const [topT, botT] = item.a.RSRank < item.b.RSRank ? [item.a, item.b] : [item.b, item.a];

    return (
      <div style={{
        position: "absolute", width: CARD_W, height: CARD_H,
        background: item.isChamp ? "#161608" : "#0a0a0a",
        border: `1px solid ${item.isChamp ? "#e9c46a33" : "#1e2040"}`,
        borderRadius: 6, overflow: "hidden",
        ...style,
      }}>
        <TeamRow team={topT} isWinner={topT === winner} />
        <div style={{ borderTop: "1px solid #18183a" }} />
        <TeamRow team={botT} isWinner={botT === winner} />
      </div>
    );
  };

  const LABELS = n === 6
    ? ["WILDCARD", "SEMIFINALS", "CHAMPIONSHIP"]
    : ["QUARTERFINALS", "SEMIFINALS", "CHAMPIONSHIP"];

  return (
    <div style={{ overflowX: "auto" }}>
      <div style={{ position: "relative", width: TOTAL_W, height: TOTAL_H, minWidth: TOTAL_W }}>

        {/* Round labels */}
        {LABELS.map((label, i) => (
          <div key={i} style={{
            position: "absolute", left: colX[i], top: 0,
            width: CARD_W, height: LABEL_H,
            display: "flex", alignItems: "center", justifyContent: "center",
            fontFamily: "'Cooper Black',Georgia,serif",
            fontSize: mobile ? 13 : 13,
            color: i === 2 ? "#e9c46a" : "#2176d2",
            letterSpacing: 2,
          }}>{label}</div>
        ))}

        {/* SVG connector lines */}
        <svg style={{ position: "absolute", top: 0, left: 0, width: TOTAL_W, height: TOTAL_H, pointerEvents: "none", overflow: "visible" }}>
          {/* R1 → R2 */}
          {r2items.map((_, i) => {
            const tCY = r1CY(i * 2);
            const bCY = r1CY(i * 2 + 1);
            const mX  = midX[0];
            const rCY = r2CY(i);
            return (
              <g key={i}>
                <line x1={colX[0] + CARD_W} y1={tCY} x2={mX}        y2={tCY} stroke={lc} strokeWidth={1} />
                <line x1={colX[0] + CARD_W} y1={bCY} x2={mX}        y2={bCY} stroke={lc} strokeWidth={1} />
                <line x1={mX}               y1={tCY} x2={mX}         y2={bCY} stroke={lc} strokeWidth={1} />
                <line x1={mX}               y1={rCY} x2={colX[1]}    y2={rCY} stroke={lc} strokeWidth={1} />
              </g>
            );
          })}
          {/* R2 → R3 */}
          <line x1={colX[1] + CARD_W} y1={r2CY(0)} x2={midX[1]} y2={r2CY(0)} stroke={lcc} strokeWidth={1} />
          <line x1={colX[1] + CARD_W} y1={r2CY(1)} x2={midX[1]} y2={r2CY(1)} stroke={lcc} strokeWidth={1} />
          <line x1={midX[1]}          y1={r2CY(0)} x2={midX[1]} y2={r2CY(1)} stroke={lcc} strokeWidth={1} />
          <line x1={midX[1]}          y1={r3CY}    x2={colX[2]} y2={r3CY}    stroke={lcc} strokeWidth={1} />
        </svg>

        {/* R1 cards */}
        {r1items.map((item, i) => (
          <BracketCard key={i} item={item} style={{ top: r1TopY(i), left: colX[0] }} />
        ))}

        {/* R2 cards */}
        {r2items.map((item, i) => (
          <BracketCard key={i} item={item} style={{ top: r2TopY(i), left: colX[1] }} />
        ))}

        {/* R3 card */}
        <BracketCard item={r3item} style={{ top: r3TopY, left: colX[2] }} />

      </div>
    </div>
  );
}
// ── SEASON EXPLORER TAB ───────────────────────────────────────────────────────
function SeasonExplorerTab({ pendingYear }) {
  const mobile = useMobile();
  const years = Object.keys(ALL_SEASONS).map(Number).sort((a, b) => b - a);
  const [selectedYear, setSelectedYear] = useState(pendingYear || 2025);
  const standings = ALL_SEASONS[selectedYear];
  const champion = CHAMPION_BY_YEAR[selectedYear];
  const playoffTeams = standings.filter(s => s.ReachedPlayoffs === "Playoffs");
  const topPF = standings.reduce((a, b) => a.PF > b.PF ? a : b);
  const topWins = standings.reduce((a, b) => a.Wins > b.Wins ? a : b);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 24 }}>

      {/* Year Selector */}
      <div style={{ display: "flex", alignItems: "center", gap: mobile ? 8 : 16, flexWrap: "wrap" }}>
        <span style={{ color: "#666", fontSize: mobile ? 14 : 13 }}>Season:</span>
        <div style={{ position: "relative", display: "inline-block" }}>
          <select
            value={selectedYear}
            onChange={e => setSelectedYear(Number(e.target.value))}
            style={{
              background: "#1a1a1a",
              color: "#fff",
              border: "1px solid #2176d2",
              borderRadius: 8,
              padding: "8px 40px 8px 16px",
              fontSize: 20,
              fontFamily: "'Cooper Black', Georgia, serif",
              letterSpacing: 2,
              cursor: "pointer",
              appearance: "none",
              WebkitAppearance: "none",
              outline: "none",
              minWidth: 120,
            }}
          >
            {years.map(y => (
              <option key={y} value={y} style={{ background: "#1a1a1a", color: "#fff" }}>
                {y}
              </option>
            ))}
          </select>
          <span style={{ position: "absolute", right: 12, top: "50%", transform: "translateY(-50%)", color: "#2176d2", pointerEvents: "none", fontSize: mobile ? 14 : 12 }}>▼</span>
        </div>
        <span style={{ color: "#555", fontSize: mobile ? 14 : 13 }}>
          Champion: <span style={{ color: getColor(champion) }}>{champion}</span>
        </span>
      </div>

      {/* Season Header Cards */}
      <div style={{ display: "flex", gap: 16, flexWrap: "wrap" }}>
        <StatCard label="Champion" value={firstName(champion)} sub={`${ALL_SEASONS[selectedYear].find(s => s.Manager === champion)?.["Team Name"] || ""}`} color="#e9c46a" />
        <StatCard label="Best Record" value={firstName(topWins.Manager)} sub={`${topWins.Record}`} color="#2176d2" />
        <StatCard label="Most Points" value={firstName(topPF.Manager)} sub={`${topPF.PF.toFixed(1)} PF`} color="#2a9d8f" />
        <StatCard label="Teams" value={standings.length} sub={`${playoffTeams.length} made playoffs`} color="#f4a261" />
      </div>

      {/* Regular Season Standings */}
      <Card>
        <SectionTitle>{selectedYear} Regular Season Standings</SectionTitle>
        <StandingsTable standings={standings} playoffCount={playoffTeams.length} year={selectedYear} />
        <div style={{ marginTop: 12, paddingTop: 12, borderTop: "1px solid #141414", fontSize: mobile ? 14 : 12, color: "#555" }}>
          * Playoff Finish reflects final postseason result, not regular season seeding
        </div>
      </Card>

      {/* Playoff Bracket */}
      <Card>
        <SectionTitle>{selectedYear} Playoff Bracket</SectionTitle>
        <PlayoffBracket year={selectedYear} playoffTeams={playoffTeams} />
      </Card>

    </div>
  );
}

// ── CHAMPIONS TAB ─────────────────────────────────────────────────────────────

// ── LEADERBOARD TAB ───────────────────────────────────────────────────────────
// ── PLAYOFF & TITLES TABLE ────────────────────────────────────────────────────
function PlayoffTitlesTable() {
  const mobile = useMobile();
  const [sortKey, setSortKey] = useState("PlayoffApps");
  const [sortDir, setSortDir] = useState("desc");
  const [showAlumni, setShowAlumni] = useState(true);

  const titleCounts = DATA.leagueWinners.reduce((acc, w) => {
    acc[w.Manager] = (acc[w.Manager] || 0) + 1;
    return acc;
  }, {});

  const handleSort = (key) => {
    if (sortKey === key) setSortDir(d => d === "asc" ? "desc" : "asc");
    else { setSortKey(key); setSortDir("desc"); }
  };

  const arrow = (key) => sortKey === key ? (sortDir === "asc" ? " ↑" : " ↓") : "";

  const baseData = showAlumni ? DATA.wPct : DATA.wPct.filter(m => m.Active);

  const sorted = [...baseData].sort((a, b) => {
    let result = 0;
    if      (sortKey === "Manager")    result = a.Manager.localeCompare(b.Manager);
    else if (sortKey === "PlayoffApps")result = a.PlayoffApps - b.PlayoffApps;
    else if (sortKey === "Seasons")    result = a.Seasons - b.Seasons;
    else if (sortKey === "App%")       result = (a.PlayoffApps / a.Seasons) - (b.PlayoffApps / b.Seasons);
    else if (sortKey === "Titles")     result = (titleCounts[a.Manager] || 0) - (titleCounts[b.Manager] || 0);
    return sortDir === "asc" ? result : -result;
  });

  const cols = [
    { key: "Manager",     label: "Manager"         },
    { key: "Seasons",     label: "Seasons"          },
    { key: "PlayoffApps", label: "Playoff Apps"     },
    { key: "App%",        label: "App %"            },
    { key: "Titles",      label: "🎖️ Titles"        },
  ].filter(c => !mobile || c.key !== "Seasons");

  return (
    <>
      <div style={{ display:"flex", alignItems:"center", gap:12, marginBottom: 12 }}>
        <button onClick={() => setShowAlumni(s => !s)} style={{
          background: showAlumni ? "#1a1a1a" : "#2176d2",
          color: showAlumni ? "#aaa" : "#fff",
          border: `1px solid ${showAlumni ? "#444" : "#2176d2"}`,
          borderRadius: 6, padding: "6px 16px", cursor: "pointer", fontSize: mobile ? 14 : 13,
        }}>
          {showAlumni ? "👁️ Show All" : "👁️ Active Only"}
        </button>
        {showAlumni && <span style={{ fontSize: mobile ? 14 : 12, color: "#555" }}>💀🪦⚰️ = no longer in the league</span>}
      </div>
      <SectionTitle>Playoff Appearances &amp; Titles</SectionTitle>
      {mobile ? (
        <div style={{ display:"flex", flexDirection:"column", gap:4 }}>
          {sorted.map((m,i) => {
            const titles = titleCounts[m.Manager] || 0;
            const appPct = m.PlayoffApps / m.Seasons;
            return (
              <div key={mgr(m.Manager)} style={{ background: i%2===0?"#0d0d0d":"#1a1a1a", borderRadius:6, padding:mobile ? "5px 7px" : "8px 10px", display:"flex", alignItems:"center", gap:8 }}>
                <span style={{ fontFamily:"'Cooper Black',Georgia,serif", fontSize:16, color: i<3?"#e9c46a":"#555", minWidth:22, textAlign:"center" }}>{rank(i)}</span>
                <div style={{ flex:1, minWidth:0 }}>
                  <MgrName name={m.Manager} />
                  <div style={{ fontSize:11, color:"#555" }}>{m.PlayoffApps} apps · {m.Seasons} seasons</div>
                </div>
                <div style={{ textAlign:"right", flexShrink:0 }}>
                  <div style={{ color: appPct>=0.6?"#e9c46a":appPct>=0.4?"#2a9d8f":"#2176d2", fontWeight:700, fontFamily:"'Cooper Black',Georgia,serif", fontSize:16 }}>{(appPct*100).toFixed(0)}%</div>
                  <div style={{ fontSize:13 }}>{titles>0 ? "🏆".repeat(titles) : <span style={{ color:"#444" }}>—</span>}</div>
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        <div style={{ overflowX:"auto" }}>
          <table style={{ width:"100%", borderCollapse:"collapse", fontSize:13 }}>
            <thead>
              <tr>
                <th style={{ textAlign:"left", padding:"8px 12px", borderBottom:"1px solid #222222", color:"#2176d2", fontFamily:"'Cooper Black',Georgia,serif", letterSpacing:1, fontSize:14 }}>Rank</th>
                {cols.map(col => (
                  <th key={col.key} onClick={() => handleSort(col.key)} style={{
                    textAlign:"left", padding:"8px 12px", borderBottom:"1px solid #222222",
                    color: sortKey===col.key?"#fff":"#2176d2",
                    fontFamily:"'Cooper Black',Georgia,serif", letterSpacing:1, fontSize:14,
                    whiteSpace:"nowrap", cursor:"pointer", userSelect:"none",
                    background: sortKey===col.key?"#181818":"transparent",
                  }}>{col.label}{arrow(col.key)}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {sorted.map((m,i) => {
                const titles = titleCounts[m.Manager] || 0;
                const appPct = m.PlayoffApps / m.Seasons;
                return (
                  <tr key={mgr(m.Manager)} style={{ background: i%2===0?"#0d0d0d":"#1a1a1a" }}>
                    <td style={{ padding:mobile ? "6px 8px" : "9px 12px", borderBottom:"1px solid #1a1a1a", color: i<3?"#e9c46a":"#666", fontFamily:"'Cooper Black',Georgia,serif", fontSize:16 }}>{rank(i)}</td>
                    <td style={{ padding:mobile ? "6px 8px" : "9px 12px", borderBottom:"1px solid #1a1a1a" }}><span style={{ display:"inline-flex", alignItems:"center", gap:5 }}><MgrName name={m.Manager} /></span></td>
                    <td style={{ padding:mobile ? "6px 8px" : "9px 12px", borderBottom:"1px solid #1a1a1a", color:"#aaa" }}>{m.Seasons}</td>
                    <td style={{ padding:mobile ? "6px 8px" : "9px 12px", borderBottom:"1px solid #1a1a1a", color:"#2a9d8f" }}>{m.PlayoffApps}</td>
                    <td style={{ padding:mobile ? "6px 8px" : "9px 12px", borderBottom:"1px solid #1a1a1a" }}>
                      <span style={{ color: appPct>=0.6?"#e9c46a":appPct>=0.4?"#2a9d8f":"#2176d2" }}>{(appPct*100).toFixed(0)}%</span>
                    </td>
                    <td style={{ padding:mobile ? "6px 8px" : "9px 12px", borderBottom:"1px solid #1a1a1a" }}>
                      {titles>0 ? <span style={{ color:"#e9c46a", fontWeight:600 }}>{"🏆".repeat(titles)}</span> : <span style={{ color:"#444" }}>—</span>}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </>
  );
}

// ── SortTh — module-level sortable table header ───────────────────────────────
function SortTh({ label, sortK, activeSortKey, activeSortDir, onSort }) {
  const arrow = activeSortKey === sortK ? (activeSortDir === "asc" ? " ↑" : " ↓") : "";
  return (
    <th onClick={() => onSort(sortK)} style={{
      textAlign: "left", padding: "8px 12px", borderBottom: "1px solid #222222",
      color: activeSortKey === sortK ? "#fff" : "#2176d2",
      fontFamily: "'Cooper Black', Georgia, serif", letterSpacing: 1, fontSize: 14,
      whiteSpace: "nowrap", cursor: "pointer", userSelect: "none",
      background: activeSortKey === sortK ? "#181818" : "transparent",
    }}>{label}{arrow}</th>
  );
}

function LeaderboardTab() {
  const mobile = useMobile();
  const { open: openSeason } = useSeason();
  const { open: openTeamName } = useTeamName();
  const { open: openMatchup } = useMatchup();

  // ── Section nav ──
  const [section, setSection] = useState("home");

  // ── All-Time Standings state ──
  const [sortKey, setSortKey]           = useState("W%");
  const [sortDir, setSortDir]           = useState("desc");
  const [showInactive, setShowInactive] = useState(false);

  // ── Best Seasons state ──
  const [recSort,    setRecSort]    = useState("WPct");
  const [recDir,     setRecDir]     = useState("desc");
  const [recAlumni,  setRecAlumni]  = useState(true);
  const [recZeroPPR, setRecZeroPPR] = useState(true);
  const [recHalfPPR, setRecHalfPPR] = useState(true);
  const [rec10,      setRec10]      = useState(true);
  const [rec12,      setRec12]      = useState(true);
  const [rec14,      setRec14]      = useState(true);

  // ── Worst Seasons state (separate section, same filters, always ascending) ──
  const [worstSort, setWorstSort] = useState("WPct");
  const [worstDir,  setWorstDir]  = useState("asc");
  const [worstAlumni,  setWorstAlumni]  = useState(true);
  const [worstZeroPPR, setWorstZeroPPR] = useState(true);
  const [worstHalfPPR, setWorstHalfPPR] = useState(true);
  const [worst10, setWorst10] = useState(true);
  const [worst12, setWorst12] = useState(true);
  const [worst14, setWorst14] = useState(true);

  // ── Win Streaks state ──
  const [winStreakAlumni, setWinStreakAlumni] = useState(true);
  const [winStreakSort, setWinStreakSort] = useState("Streak");
  const [winStreakDir, setWinStreakDir] = useState("desc");

  // ── Loss Streaks state ──
  const [lossStreakAlumni, setLossStreakAlumni] = useState(true);
  const [lossStreakSort, setLossStreakSort] = useState("Streak");
  const [lossStreakDir, setLossStreakDir] = useState("desc");

  // ── All-Time Standings logic ──
  const handleSort = (key) => {
    if (sortKey === key) setSortDir(d => d === "asc" ? "desc" : "asc");
    else { setSortKey(key); setSortDir(key === "Avg Finish" ? "asc" : "desc"); }
  };
  const arrow = (key, active, dir) => (active||sortKey) === key ? ((dir||sortDir) === "asc" ? " ↑" : " ↓") : "";
  const baseData = showInactive ? DATA.wPct : DATA.wPct.filter(m => m.Active);
  const sorted = [...baseData].sort((a, b) => {
    let result = 0;
    if (sortKey === "Manager")         result = a.Manager.localeCompare(b.Manager);
    else if (sortKey === "Seasons")    result = a.Seasons - b.Seasons;
    else if (sortKey === "W%")         result = a["W%"] - b["W%"];
    else if (sortKey === "W")          result = a.Wins - b.Wins;
    else if (sortKey === "L")          result = a.Losses - b.Losses;
    else if (sortKey === "Avg Pts")    result = a["Avg Weekly Pts"] - b["Avg Weekly Pts"];
    else if (sortKey === "Avg Finish") result = a["Avg Finish"] - b["Avg Finish"];
    return sortDir === "asc" ? result : -result;
  });
  const MOBILE_HIDE_LEADERBOARD = ["Seasons", "Avg Finish"];
  const cols = [
    { key: "Rank",       label: "Rank",       sortable: false },
    { key: "Manager",    label: "Manager",    sortable: true  },
    { key: "Seasons",    label: "Seasons",    sortable: true  },
    { key: "W%",         label: "W%",         sortable: true  },
    { key: "W",          label: "W",          sortable: true  },
    { key: "L",          label: "L",          sortable: true  },
    { key: "Avg Pts",    label: "Avg Pts/Wk", sortable: true  },
    { key: "Avg Finish", label: "Avg Finish", sortable: true  },
  ].filter(c => !mobile || !MOBILE_HIDE_LEADERBOARD.includes(c.key));

  // ── Season Records shared logic ──
  const top20Fixed = (() => {
    const best  = [...DATA.seasonRecords].sort((a, b) => b.WPct - a.WPct || b.PF - a.PF);
    const worst = [...DATA.seasonRecords].sort((a, b) => a.WPct - b.WPct || a.PF - b.PF);
    const sliceWithTies = (arr) => {
      if (arr.length <= 20) return arr.slice(0, 20);
      const cutoff = arr[19];
      return arr.filter((r, i) => i < 20 || (r.WPct === cutoff.WPct && r.PF === cutoff.PF));
    };
    return { best: sliceWithTies(best), worst: sliceWithTies(worst) };
  })();

  // ── Best Seasons logic ──
  const bestPool = top20Fixed.best.filter(r =>
    (recZeroPPR || r.PPR !== 0) && (recHalfPPR || r.PPR !== 0.5) &&
    (rec10 || r.Teams !== 10) && (rec12 || r.Teams !== 12) && (rec14 || r.Teams !== 14) &&
    (recAlumni || r.Active)
  );
  const sortedBest = [...bestPool].map((item, i) => ({...item, _rank: i})).sort((a, b) => {
    let r = 0;
    if      (recSort === "Manager") r = a.Manager.localeCompare(b.Manager);
    else if (recSort === "Year")    r = a.Year - b.Year;
    else if (recSort === "Wins")    r = a.Wins - b.Wins;
    else if (recSort === "Losses")  r = a.Losses - b.Losses;
    else if (recSort === "WPct")    r = a.WPct - b.WPct;
    else if (recSort === "PF")      r = a.PF - b.PF;
    else if (recSort === "Finish")  r = (a.Finish ?? 99) - (b.Finish ?? 99);
    return recDir === "asc" ? r : -r;
  });
  const handleBestSort = (key) => {
    if (recSort === key) setRecDir(d => d === "asc" ? "desc" : "asc");
    else { setRecSort(key); setRecDir(key === "Manager" ? "asc" : "desc"); }
  };

  // ── Worst Seasons logic ──
  const worstPool = top20Fixed.worst.filter(r =>
    (worstZeroPPR || r.PPR !== 0) && (worstHalfPPR || r.PPR !== 0.5) &&
    (worst10 || r.Teams !== 10) && (worst12 || r.Teams !== 12) && (worst14 || r.Teams !== 14) &&
    (worstAlumni || r.Active)
  );
  const sortedWorst = [...worstPool].map((item, i) => ({...item, _rank: i})).sort((a, b) => {
    let r = 0;
    if      (worstSort === "Manager") r = a.Manager.localeCompare(b.Manager);
    else if (worstSort === "Year")    r = a.Year - b.Year;
    else if (worstSort === "Wins")    r = a.Wins - b.Wins;
    else if (worstSort === "Losses")  r = a.Losses - b.Losses;
    else if (worstSort === "WPct")    r = a.WPct - b.WPct;
    else if (worstSort === "PF")      r = a.PF - b.PF;
    else if (worstSort === "Finish")  r = (a.Finish ?? 99) - (b.Finish ?? 99);
    return worstDir === "asc" ? r : -r;
  });
  const handleWorstSort = (key) => {
    if (worstSort === key) setWorstDir(d => d === "asc" ? "desc" : "asc");
    else { setWorstSort(key); setWorstDir(key === "Manager" ? "desc" : "asc"); }
  };

  // SortTh is now module-level

  // ── Win/Loss streak pools ──
  // "Currently active" = streak extended into or through the most recent season (2025)
  // Top-20: sort by streak length desc, ties broken by most recent (EndYear desc, EndWeek desc), take exactly 20
  const topStreak = (arr, alumniFlag) => {
    const filtered = arr.filter(s => alumniFlag || s.Active);
    const sorted = [...filtered].sort((a, b) =>
      b.Streak !== a.Streak ? b.Streak - a.Streak :
      b.EndYear !== a.EndYear ? b.EndYear - a.EndYear :
      b.EndWeek - a.EndWeek
    );
    return sorted.slice(0, 20).map((s, i) => ({...s, _rank: i}));
  };
  const winPool  = topStreak(DATA.winStreaks,  winStreakAlumni);
  const lossPool = topStreak(DATA.lossStreaks, lossStreakAlumni);

  const Divider = () => <div style={{ width: 1, height: 28, background: "#222222", margin: "0 4px" }} />;
  const LabelGroup = ({ label, children }) => (
    <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
      <span style={{ fontSize: mobile ? 14 : 13, color: "#555", whiteSpace: "nowrap" }}>{label}</span>
      {children}
    </div>
  );

  // ── Shared season records table renderer ──
const SeasonRecordsTable = ({ pool, sortK, sortD, onSort, titleText, onMatchup, onSeason }) => (
    <div style={{ display:"flex", flexDirection:"column", gap:16 }}>
      <Card>
        <SectionTitle>{titleText}</SectionTitle>
        {mobile ? (
          <div style={{ display:"flex", flexDirection:"column", gap:4 }}>
            {pool.map((r,i) => {
              const finishLabel = r.Finish===1?"🏆":r.Finish===2?"🥈":r.Finish===3?"🥉":r.Finish!=null?`${r.Finish}th`:"—";
              return (
                <div key={`${r.Manager}-${r.Year}`} style={{ background: i%2===0?"#0d0d0d":"#1a1a1a", borderRadius:6, padding:"5px 7px", display:"flex", alignItems:"center", gap:8 }}>
                  <span style={{ fontFamily:"'Cooper Black',Georgia,serif", fontSize:16, color: r._rank<3?"#e9c46a":"#555", minWidth:22, textAlign:"center" }}>{rank(r._rank)}</span>
                  <div style={{ flex:1, minWidth:0 }}>
                    <MgrSpan name={r.Manager} style={{ fontSize:13, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap", display:"block" }}>{r.Manager}</MgrSpan>
                    <div style={{ fontSize:11, color:"#555" }}><span onClick={e=>{e.stopPropagation();openSeason(r.Year,{x:e.clientX,y:e.clientY});}} style={{ cursor:"pointer", textDecoration:"underline", textDecorationStyle:"dotted", textDecorationColor:"#55566", textUnderlineOffset:3, color:"#555" }}>{r.Year}</span> · <span style={{ color:"#2a9d8f" }}>{pct(r.WPct)}</span> W%</div>
                  </div>
                  <div style={{ textAlign:"right", flexShrink:0 }}>
                    <div style={{ color:"#e9c46a", fontWeight:600, fontSize:13 }}>{r.PF.toFixed(1)}</div>
                    <div style={{ fontSize:12 }}>{finishLabel}</div>
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          <div style={{ overflowX:"auto" }}>
            <table style={{ width:"100%", borderCollapse:"collapse", fontSize:13 }}>
              <thead><tr>
                <th style={{ textAlign:"left", padding:"8px 12px", borderBottom:"1px solid #222222", color:"#2176d2", fontFamily:"'Cooper Black',Georgia,serif", letterSpacing:1, fontSize:14 }}>Rank</th>
                {[["Manager","Manager"],["Year","Year"],["WPct","W–L"],["WPct_pct","W%"],["PF","Points For"],["Finish","Finish"],["Team","Team"]].map(([k,l]) => (
                  <SortTh key={k} label={l} sortK={k === "WPct_pct" ? "WPct" : k} activeSortKey={sortK} activeSortDir={sortD} onSort={onSort} />
                ))}
              </tr></thead>
              <tbody>
                {pool.map((r,i) => (
                  <tr key={`${r.Manager}-${r.Year}`} style={{ background: i%2===0?"#0d0d0d":"#1a1a1a" }}>
                    <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a", color: r._rank<3?"#e9c46a":"#666", fontFamily:"'Cooper Black',Georgia,serif", fontSize:16 }}>{rank(r._rank)}</td>
                    <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a" }}><MgrName name={r.Manager} /></td>
                    <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a" }}><span onClick={e=>{e.stopPropagation();onSeason && onSeason(r.Year,{x:e.clientX,y:e.clientY});}} style={{color:"#aaa",cursor:"pointer",textDecoration:"underline",textDecorationStyle:"dotted",textDecorationColor:"#aaa66",textUnderlineOffset:3}}>{r.Year}</span></td>
                    <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a" }}><span onClick={e => { e.stopPropagation(); onMatchup && onMatchup(r.Manager, r.Year, { x: e.clientX, y: e.clientY }); }} style={{ color:"#81b29a", fontWeight:600, cursor:"pointer", textDecoration:"underline", textDecorationStyle:"dotted", textDecorationColor:"#81b29a66", textUnderlineOffset:3 }}>{r.Wins}–{r.Losses}</span></td>

                    <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a" }}><span style={{ color:"#2a9d8f", fontWeight:600 }}>{pct(r.WPct)}</span></td>
                    <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a" }}><span style={{ color:"#e9c46a" }}>{r.PF.toFixed(1)}</span></td>
                    <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a" }}>
                      <span style={{ color: r.Finish===1?"#e9c46a":r.Finish<=3?"#aaa":"#555", fontFamily:"'Cooper Black',Georgia,serif", fontSize:15 }}>
                        {r.Finish===1?"🏆 1st":r.Finish===2?"🥈 2nd":r.Finish===3?"🥉 3rd":r.Finish!=null?`${r.Finish}th`:"—"}
                      </span>
                    </td>
                    <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a" }}><em onClick={e=>{e.stopPropagation();openTeamName(r.Team,r.Manager,r.Year,{x:e.clientX,y:e.clientY});}} style={{color:"#888",fontSize:12,cursor:"pointer",textDecoration:"underline",textDecorationStyle:"dotted",textDecorationColor:"#88866",textUnderlineOffset:3}}>{r.Team}</em></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </Card>
    </div>
  );

  // ── Shared streak table renderer ──
  const StreakTable = ({ pool, streakColor, label, sortKey: skKey, sortDir: skDir, onSort: skOnSort }) => {
    const skArrow = (key) => skKey === key ? (skDir === "asc" ? " ↑" : " ↓") : "";
    const sortedPool = [...pool].sort((a, b) => {
      let result = 0;
      if (skKey === "Streak") result = a.Streak - b.Streak;
      else if (skKey === "Manager") result = a.Manager.localeCompare(b.Manager);
      else if (skKey === "StartYear") result = (a.StartYear||0) - (b.StartYear||0) || (a.StartWeek||0) - (b.StartWeek||0);
      else if (skKey === "EndYear") result = (a.EndYear||0) - (b.EndYear||0) || (a.EndWeek||0) - (b.EndWeek||0);
      return skDir === "asc" ? result : -result;
    });
    const SkTh = ({ lbl, sk, color }) => (
      <th onClick={() => skOnSort(sk)} style={{ textAlign:"left", padding:"8px 12px", borderBottom:"1px solid #222222", color: skKey === sk ? "#fff" : (color || "#2176d2"), fontFamily:"'Cooper Black',Georgia,serif", letterSpacing:1, fontSize:14, cursor:"pointer", userSelect:"none", whiteSpace:"nowrap" }}>
        {lbl}{skArrow(sk)}
      </th>
    );
    return (
    <Card>
      <SectionTitle>{label}</SectionTitle>
      {mobile ? (
        <div style={{ display:"flex", flexDirection:"column", gap:4 }}>
          {sortedPool.map((s,i) => (
            <div key={`${s.Manager}-${i}`} style={{ background: i%2===0?"#0d0d0d":"#1a1a1a", borderRadius:6, padding:"5px 7px", display:"flex", alignItems:"center", gap:8 }}>
              <span style={{ fontFamily:"'Cooper Black',Georgia,serif", fontSize:16, color: i<3?"#e9c46a":"#555", minWidth:22, textAlign:"center" }}>{rank(i)}</span>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ display:"inline-flex", alignItems:"center", gap:5 }}>
                  <MgrName name={s.Manager} />
                  {s.currentStreak && <span style={{ background:"#2a9d8f", color:"#fff", fontSize:11, fontWeight:700, padding:"1px 5px", borderRadius:10, letterSpacing:0.5 }}>ACTIVE</span>}
                </div>
                <div style={{ color:"#555", fontSize:11 }}>{s.StartYear ? `${s.StartYear} Wk${s.StartWeek} → ${s.EndYear} Wk${s.EndWeek}` : "—"}</div>
              </div>
              <span style={{ color:streakColor, fontFamily:"'Cooper Black',Georgia,serif", fontSize:22, flexShrink:0 }}>{s.Streak}</span>
            </div>
          ))}
        </div>
      ) : (
        <div style={{ overflowX:"auto" }}>
          <table style={{ width:"100%", borderCollapse:"collapse", fontSize:13 }}>
            <thead><tr>
              <th style={{ textAlign:"left", padding:"8px 12px", borderBottom:"1px solid #222222", color:"#2176d2", fontFamily:"'Cooper Black',Georgia,serif", letterSpacing:1, fontSize:14 }}>Rank</th>
              <SkTh lbl="Manager" sk="Manager" color="#2176d2" />
              <SkTh lbl="Streak" sk="Streak" color="#2176d2" />
              <SkTh lbl="Started" sk="StartYear" color="#2176d2" />
              <SkTh lbl="Ended" sk="EndYear" color="#2176d2" />
              <th style={{ textAlign:"left", padding:"8px 12px", borderBottom:"1px solid #222222", color:"#2176d2", fontFamily:"'Cooper Black',Georgia,serif", letterSpacing:1, fontSize:14 }}>Status</th>
            </tr></thead>
            <tbody>
              {sortedPool.map((s,i) => (
                <tr key={`${s.Manager}-${i}`} style={{ background: i%2===0?"#0d0d0d":"#1a1a1a" }}>
                  <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a", color: i<3?"#e9c46a":"#666", fontFamily:"'Cooper Black',Georgia,serif", fontSize:16 }}>{rank(i)}</td>
                  <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a" }}><span style={{ display:"inline-flex", alignItems:"center", gap:5 }}><MgrName name={s.Manager} /></span></td>
                  <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a" }}>
                    <span style={{ color:streakColor, fontFamily:"'Cooper Black',Georgia,serif", fontSize:20 }}>{s.Streak}</span>
                    <span style={{ color:"#555", fontSize:11, marginLeft:6 }}>{label.toLowerCase().includes("win") ? "wins" : "losses"}</span>
                  </td>
                  <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a", color:"#666", fontSize:12 }}>{s.StartYear ? `${s.StartYear} Wk ${s.StartWeek}` : "—"}</td>
                  <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a", color:"#666", fontSize:12 }}>{s.EndYear ? `${s.EndYear} Wk ${s.EndWeek}` : "—"}</td>
                  <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a" }}>
                    {s.currentStreak
                      ? <span style={{ background:"#2a9d8f", color:"#fff", fontSize:11, fontWeight:700, padding:"2px 10px", borderRadius:12, letterSpacing:0.5, whiteSpace:"nowrap" }}>🔥 Active</span>
                      : <span style={{ color:"#333", fontSize:12 }}>—</span>
                    }
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </Card>
  );
  };

  // ── Shared season filter bar ──
  const SeasonFilterBar = ({ zeroPPR, setZeroPPR, halfPPR, setHalfPPR, t10, setT10, t12, setT12, t14, setT14, alumni, setAlumni }) => (
    <FilterBar>
      <LabelGroup label="PPR:">
        <ToggleBtn active={zeroPPR} onToggle={() => setZeroPPR(s=>!s)} label="0" />
        <ToggleBtn active={halfPPR} onToggle={() => setHalfPPR(s=>!s)} label="0.5" />
      </LabelGroup>
      <Divider />
      <LabelGroup label="Teams:">
        <ToggleBtn active={t10} onToggle={() => setT10(s=>!s)} label="10" />
        <ToggleBtn active={t12} onToggle={() => setT12(s=>!s)} label="12" />
        <ToggleBtn active={t14} onToggle={() => setT14(s=>!s)} label="14" />
      </LabelGroup>
      <Divider />
      <ToggleBtn active={alumni} onToggle={() => setAlumni(s=>!s)} label={alumni ? "👁️ Show All" : "👁️ Active Only"} />
    </FilterBar>
  );

  // ── Tile definitions ──
  const LB_TILES = [
    { key: "standings",    emoji: "📋", label: "All-Time Standings",       sub: "Career W/L records, win % & scoring averages",          color: "#2176d2"  },
    { key: "playoffs",     emoji: "🏟️", label: "Playoff Appearances",      sub: "Playoff app rate, appearances & championship titles",    color: "#2a9d8f"  },
    { key: "bestseasons",  emoji: "🌠", label: "Best Seasons",             sub: "Top single-season win % & scoring performances",        color: "#e9c46a"  },
    { key: "worstseasons", emoji: "☠️", label: "Worst Seasons",            sub: "The dark side — lowest win % seasons in history",       color: "#9b5de5"  },
    { key: "winstreaks",   emoji: "🔥", label: "Winning Streaks",          sub: "Longest win streaks all-time, including active runs",   color: "#f4a261"  },
    { key: "lossstreaks",  emoji: "🧊", label: "Losing Streaks",           sub: "Longest loss streaks all-time, including active skids", color: "#a8dadc"  },
  ];

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: mobile ? 16 : 24 }}>

      {/* ── BACK BAR ── */}
      {section !== "home" && (
        <div style={{ display: "flex", alignItems: "center", gap: 10, borderBottom: "1px solid #222222", paddingBottom: 10 }}>
          <button onClick={() => setSection("home")} style={{
            background: "#1a1a1a", border: "1px solid #333", borderRadius: 8,
            color: "#aaa", cursor: "pointer", fontSize: mobile ? 13 : 14,
            padding: mobile ? "6px 12px" : "7px 16px", whiteSpace: "nowrap", flexShrink: 0,
          }}>← Leaderboard</button>
          <div style={{ fontFamily: "'Cooper Black', Georgia, serif", fontSize: mobile ? 18 : 22, color: "#e9c46a", letterSpacing: 2, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
            {LB_TILES.find(t => t.key === section)?.emoji} {LB_TILES.find(t => t.key === section)?.label}
          </div>
        </div>
      )}

      {/* ── HOME TILE GRID ── */}
      {section === "home" && (
        <div style={{ display: "flex", flexDirection: "column", gap: mobile ? 16 : 20 }}>
          <div style={{ fontSize: mobile ? 13 : 14, color: "#555", letterSpacing: 1, textTransform: "uppercase", fontFamily: "'Cooper Black', Georgia, serif" }}>
            📊 Select a section
          </div>
          <div style={{ display: "grid", gridTemplateColumns: mobile ? "1fr 1fr" : "1fr 1fr 1fr", gap: mobile ? 10 : 14 }}>
            {LB_TILES.map(t => (
              <button key={t.key} onClick={() => setSection(t.key)} style={{
                background: "#0a0a0a",
                border: `1px solid ${t.color}33`,
                borderTop: `3px solid ${t.color}`,
                borderRadius: 10,
                padding: mobile ? "14px 10px" : "20px 16px",
                cursor: "pointer",
                textAlign: "left",
                transition: "border-color 0.15s, background 0.15s",
              }}>
                <div style={{ fontSize: mobile ? 26 : 32, lineHeight: 1, marginBottom: 8 }}>{t.emoji}</div>
                <div style={{ color: t.color, fontFamily: "'Cooper Black', Georgia, serif",
                  fontSize: mobile ? 15 : 17, letterSpacing: 1, marginBottom: 4 }}>{t.label}</div>
                <div style={{ color: "#444", fontSize: mobile ? 11 : 11, lineHeight: 1.4 }}>{t.sub}</div>
              </button>
            ))}
          </div>
        </div>
      )}

      {/* ── ALL-TIME STANDINGS ── */}
      {section === "standings" && (
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <button onClick={() => setShowInactive(s => !s)} style={{
              background: showInactive ? "#1a1a1a" : "#2176d2",
              color: showInactive ? "#aaa" : "#fff",
              border: `1px solid ${showInactive ? "#444" : "#2176d2"}`,
              borderRadius: 6, padding: "6px 16px", cursor: "pointer", fontSize: mobile ? 14 : 13,
            }}>
              {showInactive ? "👁️ Show All" : "👁️ Active Only"}
            </button>
            {showInactive && <span style={{ fontSize: mobile ? 14 : 12, color: "#555" }}>💀🪦⚰️ = no longer in the league</span>}
          </div>
          <Card>
            <SectionTitle>All-Time Standings</SectionTitle>
            {mobile ? (
              <div style={{ display:"flex", flexDirection:"column", gap:4 }}>
                {sorted.map((m,i) => (
                  <div key={m.Manager} style={{ background: i%2===0?"#0d0d0d":"#1a1a1a", borderRadius:6, padding:mobile ? "5px 7px" : "8px 10px", display:"flex", alignItems:"center", gap:8 }}>
                    <span style={{ fontFamily:"'Cooper Black',Georgia,serif", fontSize:16, color: i<3?"#e9c46a":"#555", minWidth:22, textAlign:"center" }}>{rank(i)}</span>
                    <div style={{ flex:1, minWidth:0 }}>
                      <div style={{ display:"inline-flex", alignItems:"center", gap:5 }}><ManagerLogo name={m.Manager} /><MgrSpan name={m.Manager}>{shortMgr(m.Manager, mobile)}</MgrSpan></div>
                      <div style={{ fontSize:11, color:"#555" }}>{m.Seasons} seasons · avg {m["Avg Weekly Pts"].toFixed(1)} pts/wk</div>
                    </div>
                    <div style={{ textAlign:"right", flexShrink:0 }}>
                      <div style={{ color:"#2a9d8f", fontWeight:700, fontFamily:"'Cooper Black',Georgia,serif", fontSize:16 }}>{pct(m["W%"])}</div>
                      <div style={{ fontSize:11, color:"#555" }}>{m.Wins}W {m.Losses}L</div>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div style={{ overflowX:"auto" }}>
                <table style={{ width:"100%", borderCollapse:"collapse", fontSize:13 }}>
                  <thead><tr>
                    {cols.map(col => (
                      <th key={col.key} onClick={col.sortable ? () => handleSort(col.key) : undefined} style={{
                        textAlign:"left", padding:"8px 12px", borderBottom:"1px solid #222222",
                        color: sortKey===col.key?"#fff":"#2176d2",
                        fontFamily:"'Cooper Black',Georgia,serif", letterSpacing:1, fontSize:14, whiteSpace:"nowrap",
                        cursor: col.sortable?"pointer":"default", userSelect:"none",
                        background: sortKey===col.key?"#181818":"transparent",
                      }}>{col.label}{col.sortable ? arrow(col.key) : ""}</th>
                    ))}
                  </tr></thead>
                  <tbody>
                    {sorted.map((m,i) => (
                      <tr key={mgr(m.Manager)} style={{ background: i%2===0?"#0d0d0d":"#1a1a1a" }}>
                        <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a", color: i<3?"#e9c46a":"#666", fontFamily:"'Cooper Black',Georgia,serif", fontSize:16 }}>{rank(i)}</td>
                        <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a" }}><span style={{ display:"inline-flex", alignItems:"center", gap:5 }}><MgrName name={m.Manager} /></span></td>
                        <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a" }}><span style={{ color:"#aaa" }}>{m.Seasons}</span></td>
                        <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a" }}><span style={{ color:"#2a9d8f", fontWeight:600 }}>{pct(m["W%"])}</span></td>
                        <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a" }}><span style={{ color:"#81b29a" }}>{m.Wins}</span></td>
                        <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a" }}><span style={{ color:"#2176d2" }}>{m.Losses}</span></td>
                        <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a" }}><span style={{ color:"#e9c46a" }}>{m["Avg Weekly Pts"].toFixed(1)}</span></td>
                        <td style={{ padding:"9px 12px", borderBottom:"1px solid #1a1a1a" }}><span style={{ color:"#aaa" }}>{m["Avg Finish"].toFixed(1)}</span></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </Card>

        </div>
      )}

      {/* ── PLAYOFF APPEARANCES & TITLES ── */}
      {section === "playoffs" && (
        <Card>
          <PlayoffTitlesTable />
        </Card>
      )}

      {/* ── BEST SEASONS ── */}
      {section === "bestseasons" && (
        <div style={{ display:"flex", flexDirection:"column", gap:16 }}>
          <SeasonFilterBar
            zeroPPR={recZeroPPR} setZeroPPR={setRecZeroPPR}
            halfPPR={recHalfPPR} setHalfPPR={setRecHalfPPR}
            t10={rec10} setT10={setRec10} t12={rec12} setT12={setRec12} t14={rec14} setT14={setRec14}
            alumni={recAlumni} setAlumni={setRecAlumni}
          />
          <SeasonRecordsTable pool={sortedBest} sortK={recSort} sortD={recDir} onSort={handleBestSort} onMatchup={openMatchup} onSeason={openSeason} titleText="🌟 Best Single Seasons All-Time" />
        </div>
      )}

      {/* ── WORST SEASONS ── */}
      {section === "worstseasons" && (
        <div style={{ display:"flex", flexDirection:"column", gap:16 }}>
          <SeasonFilterBar
            zeroPPR={worstZeroPPR} setZeroPPR={setWorstZeroPPR}
            halfPPR={worstHalfPPR} setHalfPPR={setWorstHalfPPR}
            t10={worst10} setT10={setWorst10} t12={worst12} setT12={setWorst12} t14={worst14} setT14={setWorst14}
            alumni={worstAlumni} setAlumni={setWorstAlumni}
          />
          <SeasonRecordsTable pool={sortedWorst} sortK={worstSort} sortD={worstDir} onSort={handleWorstSort} onMatchup={openMatchup} onSeason={openSeason} titleText="💀 Worst Single Seasons All-Time" />
        </div>
      )}

      {/* ── WINNING STREAKS ── */}
      {section === "winstreaks" && (
        <div style={{ display:"flex", flexDirection:"column", gap:16 }}>
          <FilterBar>
            <ToggleBtn active={winStreakAlumni} onToggle={() => setWinStreakAlumni(s=>!s)} label={winStreakAlumni ? "👁️ Show All" : "👁️ Active Only"} />
          </FilterBar>
          <StreakTable pool={winPool} streakColor="#e9c46a" label="🔥 Longest Winning Streaks All-Time" sortKey={winStreakSort} sortDir={winStreakDir} onSort={(key) => { if (winStreakSort === key) setWinStreakDir(d => d === "asc" ? "desc" : "asc"); else { setWinStreakSort(key); setWinStreakDir(key === "Manager" ? "asc" : "desc"); } }} />
        </div>
      )}

      {/* ── LOSING STREAKS ── */}
      {section === "lossstreaks" && (
        <div style={{ display:"flex", flexDirection:"column", gap:16 }}>
          <FilterBar>
            <ToggleBtn active={lossStreakAlumni} onToggle={() => setLossStreakAlumni(s=>!s)} label={lossStreakAlumni ? "👁️ Show All" : "👁️ Active Only"} />
          </FilterBar>
          <StreakTable pool={lossPool} streakColor="#2176d2" label="🧊 Longest Losing Streaks All-Time" sortKey={lossStreakSort} sortDir={lossStreakDir} onSort={(key) => { if (lossStreakSort === key) setLossStreakDir(d => d === "asc" ? "desc" : "asc"); else { setLossStreakSort(key); setLossStreakDir(key === "Manager" ? "asc" : "desc"); } }} />
        </div>
      )}

    </div>
  );
}
// ── SCORES TAB ────────────────────────────────────────────────────────────────
function ScoresTab() {
  const mobile = useMobile();
  const { open: openScore } = useScore();
  const { open: openTeamName } = useTeamName();
  const { open: openSeason } = useSeason();
  const [view, setView]         = useState("top");
  const [sortKey, setSortKey]   = useState("Points");
  const [sortDir, setSortDir]   = useState("desc");
  const [weeksSortKey, setWeeksSortKey]   = useState("Top Weeks");
  const [weeksSortDir, setWeeksSortDir]   = useState("desc");
  const [showZeroPPR, setShowZeroPPR]     = useState(true);
  const [show14Teams, setShow14Teams]     = useState(true);
  const [showAlumni, setShowAlumni]       = useState(true);

  const VIEWS = [
    { key: "top",    label: "🔥 Top Scores"     },
    { key: "worst",  label: "💀 Worst Scores"    },
    { key: "unlucky",label: "😤 Unlucky Losses"  },
    { key: "lucky",  label: "🍀 Lucky Wins"      },
  ];

  const dataMap = {
    top:     DATA.topScores,
    worst:   DATA.worstScores,
    unlucky: DATA.unluckyLosses,
    lucky:   DATA.worstWins,
  };

  const handleSort = (key) => {
    if (sortKey === key) setSortDir(d => d === "asc" ? "desc" : "asc");
    else { setSortKey(key); setSortDir(key === "Manager" || key === "Team" || key === "Playoffs?" ? "asc" : "desc"); }
  };
  const handleWeeksSort = (key) => {
    if (weeksSortKey === key) setWeeksSortDir(d => d === "asc" ? "desc" : "asc");
    else { setWeeksSortKey(key); setWeeksSortDir("desc"); }
  };

  const arrow = (key, active, dir) => active === key ? (dir === "asc" ? " ↑" : " ↓") : "";

  const currentData = (dataMap[view] || []).filter(s =>
    (showZeroPPR || s.PPR > 0) &&
    (show14Teams || s.Teams !== 14) &&
    (showAlumni || s.Active)
  );
  const sorted = [...currentData].map((item, i) => ({...item, _rank: i})).sort((a, b) => {
    let result = 0;
    if      (sortKey === "Points")   result = a.Points - b.Points;
    else if (sortKey === "Manager")  result = a.Manager.localeCompare(b.Manager);
    else if (sortKey === "Team")     result = a["Team Name"].localeCompare(b["Team Name"]);
    else if (sortKey === "Year")     result = a.Year - b.Year;
    else if (sortKey === "Week")     result = a.Week - b.Week;
    else if (sortKey === "Playoffs?")result = a["Reached Playoffs"].localeCompare(b["Reached Playoffs"]);
    return sortDir === "asc" ? result : -result;
  });

  // Combine top+low weeks data for the bottom table
  const weeksMgrs = DATA.mostTopWeeks.map(m => {
    const low = DATA.mostLowWeeks.find(l => l.Manager === m.Manager);
    return {
      Manager: m.Manager,
      "Top Weeks": m["Top Weeks"],
      "Low Weeks": low ? low["Low Weeks"] : 0,
      "Years in League": m["Years in League"],
    };
  });
  // Add anyone in low but not top
  DATA.mostLowWeeks.forEach(l => {
    if (!weeksMgrs.find(m => m.Manager === l.Manager)) {
      weeksMgrs.push({ Manager: l.Manager, "Top Weeks": 0, "Low Weeks": l["Low Weeks"], "Years in League": l["Years in League"] });
    }
  });
  const sortedWeeks = [...weeksMgrs].sort((a, b) => {
    let result = 0;
    if      (weeksSortKey === "Manager")      result = a.Manager.localeCompare(b.Manager);
    else if (weeksSortKey === "Top Weeks")    result = a["Top Weeks"] - b["Top Weeks"];
    else if (weeksSortKey === "Top Avg")      result = (a["Top Weeks"] / a["Years in League"]) - (b["Top Weeks"] / b["Years in League"]);
    else if (weeksSortKey === "Low Weeks")    result = a["Low Weeks"] - b["Low Weeks"];
    else if (weeksSortKey === "Low Avg")      result = (a["Low Weeks"] / a["Years in League"]) - (b["Low Weeks"] / b["Years in League"]);
    else if (weeksSortKey === "Years in League") result = a["Years in League"] - b["Years in League"];
    return weeksSortDir === "asc" ? result : -result;
  });

  const scoreCols = [
    { key: "Points",   label: view === "worst" ? "Points (Low→High)" : "Points" },
    { key: "Manager",  label: "Manager"  },
    { key: "Team",     label: "Team"     },
    { key: "Year",     label: "Year"     },
    { key: "Week",     label: "Wk"       },
    { key: "Playoffs?",label: "Playoffs?"},
  ];
  const weekCols = [
    { key: "Manager",         label: "Manager"        },
    { key: "Years in League", label: "Seasons"        },
    { key: "Top Weeks",       label: "🔥 Top Weeks"  },
    { key: "Top Avg",         label: "🗓️ Per Season"  },
    { key: "Low Weeks",       label: "💀 Low Weeks"  },
    { key: "Low Avg",         label: "🔄 Per Season"  },
  ];

  const pointColor = view === "worst" ? "#2176d2" : view === "unlucky" ? "#f4a261" : view === "lucky" ? "#2a9d8f" : "#e9c46a";

  // Stat highlight cards
  const allTimeHigh   = DATA.topScores[0];
  const allTimeLow    = DATA.worstScores[0];
  const unluckiest    = DATA.unluckyLosses[0];
  const luckiestWin   = DATA.worstWins[0];

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 24 }}>

      {/* View toggle */}
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center" }}>
        {VIEWS.map(({ key, label }) => (
          <button key={key} onClick={() => { setView(key); setSortKey("Points"); setSortDir(key === "worst" || key === "lucky" ? "asc" : "desc"); }} style={{
            background: view === key ? "#2176d2" : "#1a1a1a",
            color: view === key ? "#fff" : "#aaa",
            border: `1px solid ${view === key ? "#2176d2" : "#333"}`,
            borderRadius: 6, padding: "7px 18px", cursor: "pointer", fontSize: 14,
          }}>{label}</button>
        ))}
        <div style={{ width: 1, height: 28, background: "#222222", margin: "0 4px" }} />
        <button onClick={() => setShowZeroPPR(s => !s)} style={{
          background: showZeroPPR ? "#1a1a1a" : "#2176d2",
          color: showZeroPPR ? "#aaa" : "#fff",
          border: `1px solid ${showZeroPPR ? "#444" : "#2176d2"}`,
          borderRadius: 6, padding: "7px 18px", cursor: "pointer", fontSize: mobile ? 14 : 13,
        }}>
          {showZeroPPR ? "0 PPR: Shown" : "0 PPR: Hidden"}
        </button>
        <button onClick={() => setShow14Teams(s => !s)} style={{
          background: show14Teams ? "#1a1a1a" : "#2176d2",
          color: show14Teams ? "#aaa" : "#fff",
          border: `1px solid ${show14Teams ? "#444" : "#2176d2"}`,
          borderRadius: 6, padding: "7px 18px", cursor: "pointer", fontSize: mobile ? 14 : 13,
        }}>
          {show14Teams ? "14 Teams: Shown" : "14 Teams: Hidden"}
        </button>
        <button onClick={() => setShowAlumni(s => !s)} style={{
          background: showAlumni ? "#1a1a1a" : "#2176d2",
          color: showAlumni ? "#aaa" : "#fff",
          border: `1px solid ${showAlumni ? "#444" : "#2176d2"}`,
          borderRadius: 6, padding: "7px 18px", cursor: "pointer", fontSize: mobile ? 14 : 13,
        }}>
          {showAlumni ? "👁️ Show All" : "👁️ Active Only"}
        </button>
      </div>

      {/* Scores table */}
      <Card>
        <SectionTitle>
          {VIEWS.find(v => v.key === view)?.label} — All-Time
        </SectionTitle>
        <div style={{ overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: mobile ? 13 : 13 }}>
            <thead>
              <tr>
                <th style={{ textAlign: "left", padding: mobile ? "6px 8px" : "8px 12px", borderBottom: "1px solid #222222", color: "#2176d2", fontFamily: "'Cooper Black', Georgia, serif", letterSpacing: 1, fontSize: 14 }}>Rank</th>
                {scoreCols.map(col => (
                  <th key={col.key} onClick={() => handleSort(col.key)} style={{
                    textAlign: "left", padding: "8px 12px", borderBottom: "1px solid #222222",
                    color: sortKey === col.key ? "#fff" : "#2176d2",
                    fontFamily: "'Cooper Black', Georgia, serif", letterSpacing: 1, fontSize: 14,
                    whiteSpace: "nowrap", cursor: "pointer", userSelect: "none",
                    background: sortKey === col.key ? "#181818" : "transparent",
                  }}>
                    {col.label}{arrow(col.key, sortKey, sortDir)}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {sorted.map((s, i) => (
                <tr key={`${mgr(s.Manager)}-${s.Year}-${s.Week}`} style={{ background: i % 2 === 0 ? "#0d0d0d" : "#1a1a1a" }}>
                  <td style={{ padding: mobile ? "6px 8px" : mobile ? "6px 8px" : "9px 12px", borderBottom: "1px solid #1a1a1a", color: i < 3 ? pointColor : "#666", fontFamily: "'Cooper Black', Georgia, serif", fontSize: 16 }}>
                    {rank(i)}
                  </td>
                  <td style={{ padding: mobile ? "6px 8px" : mobile ? "6px 8px" : "9px 12px", borderBottom: "1px solid #1a1a1a" }}>
                    <span style={{ color: pointColor, fontFamily: "'Cooper Black', Georgia, serif", fontSize: 17 }}>{s.Points}</span>
                  </td>
                  <td style={{ padding: mobile ? "6px 8px" : mobile ? "6px 8px" : "9px 12px", borderBottom: "1px solid #1a1a1a", whiteSpace: "nowrap" }}>
                    <span style={{ display:"inline-flex", alignItems:"center", gap:5 }}><ManagerLogo name={s.Manager} /><MgrSpan name={s.Manager}>{mgr(s.Manager)}</MgrSpan></span>
                  </td>
                  <td style={{ padding: mobile ? "6px 8px" : mobile ? "6px 8px" : "9px 12px", borderBottom: "1px solid #1a1a1a" }}>
                    <em onClick={e=>{e.stopPropagation();openTeamName(s["Team Name"],s.Manager,s.Year,{x:e.clientX,y:e.clientY});}} style={{ color:"#aaa", cursor:"pointer", textDecoration:"underline", textDecorationStyle:"dotted", textDecorationColor:"#aaa6", textUnderlineOffset:3 }}>{s["Team Name"]}</em>
                  </td>
                  <td style={{ padding: mobile ? "6px 8px" : mobile ? "6px 8px" : "9px 12px", borderBottom: "1px solid #1a1a1a", color: "#aaa" }}>{s.Year}</td>
                  <td style={{ padding: mobile ? "6px 8px" : mobile ? "6px 8px" : "9px 12px", borderBottom: "1px solid #1a1a1a", color: "#aaa" }}>{s.Week}</td>
                  <td style={{ padding: mobile ? "6px 8px" : mobile ? "6px 8px" : "9px 12px", borderBottom: "1px solid #1a1a1a" }}>{playoffBadge(s["Reached Playoffs"])}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </Card>

      {/* Stat cards */}
      <div style={{ display: "flex", gap: 16, flexWrap: "wrap" }}>
        <StatCard label="All-Time High Score" value={allTimeHigh.Points} sub={`${allTimeHigh.Manager} · ${allTimeHigh.Year} Wk ${allTimeHigh.Week}`} color="#e9c46a" />
        <StatCard label="All-Time Low Score"  value={allTimeLow.Points}  sub={`${allTimeLow.Manager} · ${allTimeLow.Year} Wk ${allTimeLow.Week}`}  color="#2176d2" />
        <StatCard label="Unluckiest Loss"     value={unluckiest.Points}  sub={`${unluckiest.Manager} · ${unluckiest.Year} Wk ${unluckiest.Week}`}  color="#f4a261" />
        <StatCard label="Luckiest Win"        value={luckiestWin.Points} sub={`${luckiestWin.Manager} · ${luckiestWin.Year} Wk ${luckiestWin.Week}`} color="#2a9d8f" />
      </div>

      {/* High/Low weeks table */}
      <Card>
        <SectionTitle>High &amp; Low Score Weeks All-Time</SectionTitle>
        <div style={{ overflowX: "auto" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontSize: mobile ? 13 : 13 }}>
            <thead>
              <tr>
                <th style={{ textAlign: "left", padding: mobile ? "6px 8px" : "8px 12px", borderBottom: "1px solid #222222", color: "#2176d2", fontFamily: "'Cooper Black', Georgia, serif", letterSpacing: 1, fontSize: 14 }}>Rank</th>
                {weekCols.map(col => (
                  <th key={col.key} onClick={() => handleWeeksSort(col.key)} style={{
                    textAlign: "left", padding: "8px 12px", borderBottom: "1px solid #222222",
                    color: weeksSortKey === col.key ? "#fff" : "#2176d2",
                    fontFamily: "'Cooper Black', Georgia, serif", letterSpacing: 1, fontSize: 14,
                    whiteSpace: "nowrap", cursor: "pointer", userSelect: "none",
                    background: weeksSortKey === col.key ? "#181818" : "transparent",
                  }}>
                    {col.label}{arrow(col.key, weeksSortKey, weeksSortDir)}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {sortedWeeks.map((m, i) => (
                <tr key={mgr(m.Manager)} style={{ background: i % 2 === 0 ? "#0d0d0d" : "#1a1a1a" }}>
                  <td style={{ padding: mobile ? "6px 8px" : mobile ? "6px 8px" : "9px 12px", borderBottom: "1px solid #1a1a1a", color: i < 3 ? "#e9c46a" : "#666", fontFamily: "'Cooper Black', Georgia, serif", fontSize: 16 }}>
                    {rank(i)}
                  </td>
                  <td style={{ padding: mobile ? "6px 8px" : mobile ? "6px 8px" : "9px 12px", borderBottom: "1px solid #1a1a1a", whiteSpace: "nowrap" }}>
                    <MgrName name={m.Manager} />
                  </td>
                  <td style={{ padding: mobile ? "6px 8px" : mobile ? "6px 8px" : "9px 12px", borderBottom: "1px solid #1a1a1a", color: "#aaa" }}>{m["Years in League"]}</td>
                  <td style={{ padding: mobile ? "6px 8px" : mobile ? "6px 8px" : "9px 12px", borderBottom: "1px solid #1a1a1a" }}>
                    <span style={{ color: "#e9c46a", fontWeight: 600 }}>{m["Top Weeks"]}</span>
                  </td>
                  <td style={{ padding: mobile ? "6px 8px" : mobile ? "6px 8px" : "9px 12px", borderBottom: "1px solid #1a1a1a" }}>
                    <span style={{ color: "#e9c46a99" }}>{(m["Top Weeks"] / m["Years in League"]).toFixed(1)}</span>
                  </td>
                  <td style={{ padding: mobile ? "6px 8px" : mobile ? "6px 8px" : "9px 12px", borderBottom: "1px solid #1a1a1a" }}>
                    <span style={{ color: "#d42b2b", fontWeight: 600 }}>{m["Low Weeks"]}</span>
                  </td>
                  <td style={{ padding: mobile ? "6px 8px" : mobile ? "6px 8px" : "9px 12px", borderBottom: "1px solid #1a1a1a" }}>
                    <span style={{ color: "#2176d299" }}>{(m["Low Weeks"] / m["Years in League"]).toFixed(1)}</span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </Card>

    </div>
  );
}

// ── MANAGER AI PROFILE ────────────────────────────────────────────────────────
function ManagerAIProfile() {
  const mobile   = useMobile();
  const profiles = DATA.managerProfiles || {};

  const currentMgrs = Object.keys(DATA.eraProfiles || {})
    .filter(m => DATA.eraProfiles[m].active).sort();

  const [selectedMgr, setSelectedMgr] = React.useState(currentMgrs[0] || "");
  const [showAlumni,  setShowAlumni]  = React.useState(false);
  const allMgrs = Object.keys(DATA.eraProfiles || {}).sort();
  const mgrList = showAlumni
    ? [...currentMgrs, ...allMgrs.filter(m => !currentMgrs.includes(m))]
    : currentMgrs;

  const profile = profiles[selectedMgr] || null;
  const era     = (DATA.eraProfiles || {})[selectedMgr] || null;

  const SECTIONS = [
    { key:"story",     emoji:"📖", label:"Career Story",
      hint:"Their arc across the full history of the league — how they arrived, evolved, and where they stand." },
    { key:"style",     emoji:"🎮", label:"Playing Style",
      hint:"How they manage week to week — tendencies, habits, and what makes them tick." },
    { key:"moments",   emoji:"⚡", label:"Signature Moments",
      hint:"The games, seasons, and plays that defined their legacy in the No Fun League." },
    { key:"rivalries", emoji:"🤝", label:"Rivalries",
      hint:"The head-to-head dynamics that have shaped their seasons." },
    { key:"legacy",    emoji:"🪶", label:"Legacy",
      hint:"Their place in league history — what the record books say and what the other managers remember." },
  ];

  function PendingCard({ section }) {
    return (
      <div style={{ background:"#080808", border:"1px dashed #222222",
                    borderRadius:8, padding:mobile?"14px 16px":"16px 20px",
                    display:"flex", flexDirection:"column", gap:8 }}>
        <div style={{ display:"flex", alignItems:"center", gap:8 }}>
          <span style={{ fontSize:mobile?16:18 }}>{section.emoji}</span>
          <span style={{ fontFamily:"'Cooper Black',Georgia,serif",
                         fontSize:mobile?16:18, color:"#222222", letterSpacing:1.5 }}>
            {section.label}
          </span>
        </div>
        <div style={{ display:"flex", flexDirection:"column", gap:6, marginTop:2 }}>
          {[100,85,70,50].map((w,i) => (
            <div key={i} style={{ height:10, borderRadius:4, background:"#0d0d0d", width:`${w}%` }} />
          ))}
        </div>
        <div style={{ fontSize:10, color:"#252540", fontStyle:"italic", lineHeight:1.5 }}>
          {section.hint}
        </div>
      </div>
    );
  }

  function LiveCard({ section, text }) {
    return (
      <div style={{ background:"#0a0a0a", border:"1px solid #1a1a1a",
                    borderLeft:"3px solid #a8dadc", borderRadius:8,
                    padding:mobile?"14px 16px":"16px 20px",
                    display:"flex", flexDirection:"column", gap:8 }}>
        <div style={{ display:"flex", alignItems:"center", gap:8 }}>
          <span style={{ fontSize:mobile?16:18 }}>{section.emoji}</span>
          <span style={{ fontFamily:"'Cooper Black',Georgia,serif",
                         fontSize:mobile?16:18, color:"#a8dadc", letterSpacing:1.5 }}>
            {section.label}
          </span>
        </div>
        <p style={{ fontSize:mobile?12:13, color:"#aaa", lineHeight:1.75, margin:0 }}>
          {text}
        </p>
      </div>
    );
  }

  return (
    <div style={{ display:"flex", flexDirection:"column", gap:mobile?16:24 }}>

      {/* Manager picker */}
      <div>
        <div style={{ fontSize:11, fontWeight:700, color:"#888", textTransform:"uppercase",
                      letterSpacing:0.8, marginBottom:8 }}>Select Manager</div>
        <div style={{ display:"flex", alignItems:"center", gap:10, flexWrap:"wrap" }}>
          <select value={selectedMgr} onChange={e=>setSelectedMgr(e.target.value)}
            style={{ background:"#0a0a0a", border:"1px solid #333", borderRadius:6,
                     color:"#e9e9f0", fontSize:mobile?12:13, padding:"6px 10px", cursor:"pointer" }}>
            {mgrList.map(m => <option key={m} value={m}>{m}</option>)}
          </select>
          <label style={{ display:"flex", alignItems:"center", gap:6, fontSize:11,
                          color:"#555", cursor:"pointer" }}>
            <input type="checkbox" checked={showAlumni}
                   onChange={e=>setShowAlumni(e.target.checked)}
                   style={{ accentColor:"#e9c46a" }} />
            Show alumni
          </label>
        </div>
      </div>

      {/* Career snapshot */}
      {era && (
        <div style={{ background:"#0a0a0a", border:"1px solid #1a1a1a", borderRadius:8,
                      padding:mobile?"10px 14px":"12px 18px",
                      display:"flex", gap:mobile?14:24, flexWrap:"wrap", alignItems:"center" }}>
          {[
            { label:"Seasons",   val: era.seasons },
            { label:"Record",    val: `${era.totalW}-${era.totalL}` },
            { label:"W%",        val: `${(era.allTimeWPct*100).toFixed(0)}%` },
            { label:"Titles",    val: era.titles, color:"#e9c46a" },
            { label:"Avg Score", val: era.avgScore?.toFixed(1) },
          ].map(({label, val, color}) => (
            <div key={label} style={{ textAlign:"center" }}>
              <div style={{ fontFamily:"'Cooper Black',Georgia,serif",
                            fontSize:mobile?18:22, color:color||"#aaa",
                            letterSpacing:1, lineHeight:1 }}>{val}</div>
              <div style={{ fontSize:9, color:"#444", letterSpacing:0.5,
                            textTransform:"uppercase" }}>{label}</div>
            </div>
          ))}
          <div style={{ marginLeft:"auto" }}>
            {profile
              ? <span style={{ fontSize:11, color:"#a8dadc", fontWeight:700 }}>✅ Profile loaded</span>
              : <span style={{ fontSize:11, color:"#252540", fontStyle:"italic" }}>AI narrative pending</span>
            }
          </div>
        </div>
      )}

      {/* Profile sections */}
      <div style={{ display:"flex", flexDirection:"column", gap:mobile?10:12 }}>
        {SECTIONS.map(section => {
          const text = profile?.[section.key];
          return text
            ? <LiveCard    key={section.key} section={section} text={text} />
            : <PendingCard key={section.key} section={section} />;
        })}
      </div>

      <div style={{ fontSize:10, color:"#252540", textAlign:"center", paddingBottom:8 }}>
        Profiles generated by Claude via pre-deploy script · Embedded as static data
      </div>

    </div>
  );
}


// ── MANAGERS TAB ─────────────────────────────────────────────────────────────
function ManagersTab({ pendingManager }) {
  const mobile = useMobile();
  const [section, setSection] = useState(pendingManager ? "spotlight" : "home");

  const MGR_TILES = [
    { key: "spotlight", emoji: "🔍", label: "Manager Spotlight",  sub: "Full career profile — stats, timeline, H2H, playoffs & NFL twin", color: "#a8dadc" },
    { key: "roster",    emoji: "🗂️", label: "Roster",             sub: "The full cast — active managers & league alumni at a glance",      color: "#2a9d8f" },
    { key: "compare",   emoji: "⚖️",  label: "Compare",            sub: "Side-by-side career comparison for any two managers",              color: "#64b5f6" },
    { key: "trophy",    emoji: "🎗️", label: "Trophy Case",        sub: "Titles, finals appearances & toilet bowl crowns",                   color: "#e9c46a" },
    { key: "arc",       emoji: "📈", label: "Career Arc",         sub: "Season-by-season W% trend for any manager",                        color: "#f4a261" },
    { key: "matrix",    emoji: "🔲", label: "H2H Matrix",         sub: "Full head-to-head record grid across all managers",                 color: "#2ecc71" },
    { key: "nfltwin",   emoji: "🎭", label: "NFL Twins",          sub: "Every manager's NFL franchise twin — colors, logo & fit",           color: "#2176d2" },
    { key: "rankings",  emoji: "🏅", label: "Manager Rankings",   sub: "Sortable all-time stat bars — W%, scoring, playoffs & more",        color: "#9b5de5" },
    { key: "aiprofile", emoji: "🤖", label: "Manager Profile",     sub: "AI-generated deep dive — career story, personality & legacy",          color: "#a8dadc" },
  ];

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: mobile ? 16 : 24 }}>

      {/* ── BACK BAR ── */}
      {section !== "home" && (
        <div style={{ display: "flex", alignItems: "center", gap: 10, borderBottom: "1px solid #222222", paddingBottom: 10 }}>
          <button onClick={() => setSection("home")} style={{
            background: "#1a1a1a", border: "1px solid #333", borderRadius: 8,
            color: "#aaa", cursor: "pointer", fontSize: mobile ? 13 : 14,
            padding: mobile ? "6px 12px" : "7px 16px", whiteSpace: "nowrap", flexShrink: 0,
          }}>← Managers</button>
          <div style={{ fontFamily: "'Cooper Black', Georgia, serif", fontSize: mobile ? 18 : 22,
            color: "#e9c46a", letterSpacing: 2, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
            {MGR_TILES.find(t => t.key === section)?.emoji} {MGR_TILES.find(t => t.key === section)?.label}
          </div>
        </div>
      )}

      {/* ── HOME TILE GRID ── */}
      {section === "home" && (
        <div style={{ display: "flex", flexDirection: "column", gap: mobile ? 16 : 20 }}>
          <div style={{ fontSize: mobile ? 13 : 14, color: "#555", letterSpacing: 1,
            textTransform: "uppercase", fontFamily: "'Cooper Black', Georgia, serif" }}>
            🧑‍💼 Select a section
          </div>
          <div style={{ display: "grid", gridTemplateColumns: mobile ? "1fr 1fr" : "1fr 1fr 1fr", gap: mobile ? 10 : 14 }}>
            {MGR_TILES.map(t => (
              <button key={t.key} onClick={() => setSection(t.key)} style={{
                background: "#0a0a0a",
                border: `1px solid ${t.color}33`,
                borderTop: `3px solid ${t.color}`,
                borderRadius: 10,
                padding: mobile ? "14px 10px" : "20px 16px",
                cursor: "pointer",
                textAlign: "left",
                transition: "border-color 0.15s, background 0.15s",
              }}>
                <div style={{ fontSize: mobile ? 26 : 32, lineHeight: 1, marginBottom: 8 }}>{t.emoji}</div>
                <div style={{ color: t.color, fontFamily: "'Cooper Black', Georgia, serif",
                  fontSize: mobile ? 15 : 17, letterSpacing: 1, marginBottom: 4 }}>{t.label}</div>
                <div style={{ color: "#444", fontSize: mobile ? 11 : 11, lineHeight: 1.4 }}>{t.sub}</div>
              </button>
            ))}
          </div>
        </div>
      )}

      {section === "spotlight" && <EraProfilesSection pendingManager={pendingManager} />}
      {section === "compare"   && <ManagerCompareSection />}
      {section === "roster"    && <RosterSection />}
      {section === "trophy"    && <TrophyCaseSection />}
      {section === "arc"       && <CareerArcSection />}
      {section === "matrix"    && <H2HMatrixSection />}
      {section === "nfltwin"   && <NFLTwinGallery />}
      {section === "rankings"  && <ManagerRankingsSection />}
      {section === "aiprofile" && <ManagerAIProfile />}
    </div>
  );
}

// ── ROSTER SECTION ────────────────────────────────────────────────────────────
function RosterSection() {
  const mobile = useMobile();
  const [showAlumni, setShowAlumni] = useState(false);
  const allMgrs = Object.keys(DATA.eraProfiles);
  const uniqueMgrs = [...new Set(allMgrs)];
  const activeMgrs = uniqueMgrs.filter(m => !ALUMNI.has(m)).sort();
  const alumniMgrs = uniqueMgrs.filter(m =>  ALUMNI.has(m)).sort();
  const displayed  = showAlumni ? [...activeMgrs, ...alumniMgrs] : activeMgrs;

  return (
    <Card>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
        <SectionTitle>🃏 League Roster</SectionTitle>
        <ToggleBtn active={showAlumni} onToggle={() => setShowAlumni(s => !s)}
          label={showAlumni ? "👁️ Show All" : "👁️ Active Only"} />
      </div>
      <div style={{ display: "grid", gridTemplateColumns: mobile ? "1fr 1fr" : "1fr 1fr 1fr 1fr", gap: mobile ? 8 : 12 }}>
        {displayed.map(name => {
          const p       = DATA.eraProfiles[name];
          const isAlum  = ALUMNI.has(name);
          const col     = getColor(name);
          const twin    = DATA.mgrNFLTwin[name];
          const twinData = twin ? DATA.nflTeams[twin] : null;
          const titles  = DATA.leagueWinners.filter(w => w.Manager === name).length;
          return (
            <div key={name} style={{
              background: "#0a0a0a", border: `1px solid ${col}33`,
              borderTop: `3px solid ${col}`, borderRadius: 8,
              padding: mobile ? "10px 10px" : "14px 14px",
              opacity: isAlum ? 0.7 : 1,
            }}>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
                <ManagerLogo name={name} size={28} />
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ color: col, fontWeight: 700, fontSize: mobile ? 12 : 13,
                    overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                    {firstName(name)}{isAlum ? " 💀" : ""}
                  </div>
                  <div style={{ color: "#555", fontSize: 11 }}>
                    {p?.firstYear}{p?.firstYear !== p?.lastYear ? `–${p?.lastYear}` : ""}
                  </div>
                </div>
                {titles > 0 && (
                  <span style={{ fontSize: 14 }}>{"🏆".repeat(titles)}</span>
                )}
              </div>
              <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                <span style={{ background: "#1a1a1a", borderRadius: 4, padding: "2px 6px",
                  fontSize: 11, color: "#aaa" }}>
                  {p?.totalW}W–{p?.totalL}L
                </span>
                <span style={{ background: "#1a1a1a", borderRadius: 4, padding: "2px 6px",
                  fontSize: 11, color: "#2a9d8f" }}>
                  {((p?.totalW / (p?.totalW + p?.totalL)) * 100 || 0).toFixed(0)}%
                </span>
                {twin && twinData && (
                  <TeamLogo teamData={twinData} size={20} />
                )}
              </div>
            </div>
          );
        })}
      </div>
      {!showAlumni && (
        <div style={{ color: "#444", fontSize: mobile ? 12 : 11, marginTop: 12, paddingTop: 8, borderTop: "1px solid #1a1a1a" }}>
          {alumniMgrs.length} alumni hidden · toggle to show all
        </div>
      )}
    </Card>
  );
}

// ── TROPHY CASE SECTION ───────────────────────────────────────────────────────
function TrophyCaseSection() {
  const mobile = useMobile();
  const { open: openTrophy } = useTrophy();
  const [showAlumni, setShowAlumni] = useState(false);

  const allMgrs = [...new Set(Object.keys(DATA.eraProfiles))].sort();
  const displayed = allMgrs.filter(m => showAlumni || !ALUMNI.has(m));

  const champCounts   = {};
  const runnerUpCounts = {};
  DATA.leagueWinners.forEach(w => {
    champCounts[w.Manager] = (champCounts[w.Manager] || 0) + 1;
  });
  // Finals appearances from playoff gameLog
  DATA.playoffData.gameLog
    .filter(g => g.championship && g.bracket === "winners")
    .forEach(g => {
      runnerUpCounts[g.manager] = (runnerUpCounts[g.manager] || 0) + 1;
    });

  // Toilet bowl crowns (lost 💩 King Game)
  const toiletCrowns = {};
  DATA.playoffData.gameLog
    .filter(g => g.roundName === "💩 King Game" && !g.win)
    .forEach(g => {
      toiletCrowns[g.manager] = (toiletCrowns[g.manager] || 0) + 1;
    });

  // 3rd place finishes (won the 3rd Place Game)
  const thirdPlaceCounts = {};
  DATA.playoffData.gameLog
    .filter(g => g.roundName === "3rd Place Game" && g.win)
    .forEach(g => {
      thirdPlaceCounts[g.manager] = (thirdPlaceCounts[g.manager] || 0) + 1;
    });

  const rows = displayed.map(name => ({
    name,
    titles:  champCounts[name]      || 0,
    finals:  runnerUpCounts[name]   || 0,
    third:   thirdPlaceCounts[name] || 0,
    poop:    toiletCrowns[name]     || 0,
    isAlum:  ALUMNI.has(name),
  })).sort((a, b) => b.titles - a.titles || b.finals - a.finals || b.third - a.third || b.poop - a.poop);

  return (
    <Card>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 16 }}>
        <SectionTitle>🎖️ Trophy Case</SectionTitle>
        <ToggleBtn active={showAlumni} onToggle={() => setShowAlumni(s => !s)}
          label={showAlumni ? "👁️ Show All" : "👁️ Active Only"} />
      </div>
      <div style={{ overflowX: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: mobile ? 13 : 13 }}>
          <thead>
            <tr style={{ borderBottom: "2px solid #222222" }}>
              <th style={{ textAlign: "left", padding: "8px 10px", color: "#555", fontSize: 11, fontWeight: 600, letterSpacing: 0.5 }}>Manager</th>
              <th style={{ textAlign: "center", padding: "8px 10px", color: "#e9c46a", fontSize: 14 }}>🏆</th>
              <th style={{ textAlign: "center", padding: "8px 10px", color: "#aaa", fontSize: 14 }}>🥈</th>
              <th style={{ textAlign: "center", padding: "8px 10px", color: "#cd7f32", fontSize: 14 }}>🥉</th>
              <th style={{ textAlign: "center", padding: "8px 10px", color: "#9b5de5", fontSize: 14 }}>💩</th>
              <th style={{ textAlign: "left", padding: "8px 10px", color: "#555", fontSize: 11, fontWeight: 600, letterSpacing: 0.5 }}>Hardware</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((r, i) => {
              const col = getColor(r.name);
              return (
                <tr key={r.name} style={{ borderBottom: "1px solid #141414", background: i % 2 === 0 ? "transparent" : "#080808", opacity: r.isAlum ? 0.55 : 1 }}>
                  <td style={{ padding: mobile ? "6px 8px" : "8px 10px" }}>
                    <span style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
                      <ManagerLogo name={r.name} />
                      <span style={{ color: col, fontWeight: 600 }}>{mgr(r.name)}</span>
                      {r.isAlum && <span style={{ color: "#555", fontSize: 11 }}>💀</span>}
                    </span>
                  </td>
                  <td style={{ textAlign: "center", padding: mobile ? "6px 8px" : "8px 10px", color: "#e9c46a", fontFamily: "'Cooper Black',Georgia,serif", fontSize: 18 }}>
                    {r.titles > 0
                      ? DATA.leagueWinners.filter(w => w.Manager === r.name).map(w => (
                          <span key={w.Year} onClick={e => { e.stopPropagation(); openTrophy(r.name, w.Year, { x: e.clientX, y: e.clientY }); }}
                            style={{ cursor:"pointer", marginRight:2, display:"inline-block", fontSize:18 }} title={String(w.Year)}>🏆</span>
                        ))
                      : <span style={{ color: "#222222" }}>—</span>}
                  </td>
                  <td style={{ textAlign: "center", padding: mobile ? "6px 8px" : "8px 10px", color: "#aaa", fontFamily: "'Cooper Black',Georgia,serif", fontSize: 18 }}>
                    {r.finals > r.titles ? r.finals - r.titles : r.finals > 0 && r.titles === 0 ? r.finals : <span style={{ color: "#222222" }}>—</span>}
                  </td>
                  <td style={{ textAlign: "center", padding: mobile ? "6px 8px" : "8px 10px", color: "#cd7f32", fontFamily: "'Cooper Black',Georgia,serif", fontSize: 18 }}>
                    {r.third > 0 ? r.third : <span style={{ color: "#222222" }}>—</span>}
                  </td>
                  <td style={{ textAlign: "center", padding: mobile ? "6px 8px" : "8px 10px", color: "#9b5de5", fontFamily: "'Cooper Black',Georgia,serif", fontSize: 18 }}>
                    {r.poop > 0 ? r.poop : <span style={{ color: "#222222" }}>—</span>}
                  </td>
                  <td style={{ padding: mobile ? "6px 8px" : "8px 10px", fontSize: 16 }}>
                    {"🏆".repeat(r.titles)}{"🥈".repeat(Math.max(0, r.finals - r.titles))}{"🥉".repeat(r.third)}{"💩".repeat(r.poop)}
                    {r.titles === 0 && r.finals === 0 && r.third === 0 && r.poop === 0 && <span style={{ color: "#222222", fontSize: 12 }}>—</span>}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      <div style={{ color: "#444", fontSize: mobile ? 12 : 11, marginTop: 10, paddingTop: 8, borderTop: "1px solid #1a1a1a" }}>
        🏆 Championships · 🥈 Runner-up finishes · 🥉 3rd place finishes · 💩 Toilet bowl crowns (2022–present)
      </div>
    </Card>
  );
}

// ── CAREER ARC SECTION ────────────────────────────────────────────────────────
function CareerArcSection() {
  const mobile = useMobile();
  const { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
          ReferenceLine, Cell } = Recharts;

  const allMgrs    = [...new Set(Object.keys(DATA.eraProfiles))].sort();
  const activeMgrs = allMgrs.filter(m => !ALUMNI.has(m));
  const alumniMgrs = allMgrs.filter(m =>  ALUMNI.has(m));
  const [arcMgr, setArcMgr] = useState(activeMgrs[0] || allMgrs[0]);

  const seasons   = DATA.seasonHistories[arcMgr] || [];
  const col       = getColor(arcMgr);
  const leagueAvg = 0.5;

  const chartData = seasons.map(s => ({
    year:     s.year,
    wpct:     parseFloat(((s.W / (s.W + s.L)) * 100).toFixed(1)),
    W:        s.W,
    L:        s.L,
    PF:       s.PF,
    finish:   s.PlayoffFinish,
    playoffs: s.playoffs,
    team:     s.team,
  }));

  const finishColor = (f) => f === 1 ? "#e9c46a" : f <= 2 ? "#aaa" : f <= 3 ? "#cd7f32" : f <= 6 ? "#2a9d8f" : "#555";

  return (
    <Card>
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 16, flexWrap: "wrap" }}>
        <SectionTitle>📈 Career Arc</SectionTitle>
        <div style={{ position: "relative" }}>
          <select value={arcMgr} onChange={e => setArcMgr(e.target.value)} style={{
            background: "#1a1a1a", color: "#fff", border: "1px solid #333", borderRadius: 6,
            padding: "6px 28px 6px 10px", fontSize: 13, cursor: "pointer",
            appearance: "none", WebkitAppearance: "none", outline: "none",
          }}>
            <optgroup label="Active">{activeMgrs.map(m => <option key={m} value={m}>{m}</option>)}</optgroup>
            <optgroup label="Alumni 💀">{alumniMgrs.map(m => <option key={m} value={m}>{m}</option>)}</optgroup>
          </select>
          <span style={{ position: "absolute", right: 8, top: "50%", transform: "translateY(-50%)", color: "#2176d2", pointerEvents: "none", fontSize: 11 }}>▼</span>
        </div>
      </div>

      {/* Stat pills */}
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 16 }}>
        {[
          { label: "Seasons",   value: seasons.length },
          { label: "Career W%", value: ((DATA.eraProfiles[arcMgr]?.allTimeWPct || 0) * 100).toFixed(1) + "%" },
          { label: "Best",      value: DATA.eraProfiles[arcMgr]?.bestSeason?.year,  color: "#2a9d8f" },
          { label: "Worst",     value: DATA.eraProfiles[arcMgr]?.worstSeason?.year, color: "#2176d2" },
          { label: "Titles",    value: DATA.leagueWinners.filter(w => w.Manager === arcMgr).length + " 🏆" },
        ].map(s => (
          <div key={s.label} style={{ background: "#0a0a0a", borderRadius: 6, padding: "8px 12px", textAlign: "center" }}>
            <div style={{ fontSize: 11, color: "#555", letterSpacing: 1, textTransform: "uppercase", marginBottom: 2 }}>{s.label}</div>
            <div style={{ color: s.color || col, fontFamily: "'Cooper Black',Georgia,serif", fontSize: 20 }}>{s.value ?? "—"}</div>
          </div>
        ))}
      </div>

      {/* Bar chart */}
      {chartData.length > 0 ? (
        <>
          <div style={{ width: "100%", height: mobile ? 180 : 220 }}>
            <ResponsiveContainer>
              <BarChart data={chartData} margin={{ top: 4, right: 8, left: -20, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#1a1a1a" />
                <XAxis dataKey="year" tick={{ fill: "#555", fontSize: 11 }} />
                <YAxis domain={[0, 100]} tick={{ fill: "#555", fontSize: 11 }}
                  tickFormatter={v => v + "%"} />
                <ReferenceLine y={50} stroke="#222222" strokeDasharray="4 2" />
                <Tooltip
                  contentStyle={{ background: "#0a0a0a", border: "1px solid #222222", borderRadius: 6, fontSize: 12 }}
                  formatter={(val, name, props) => {
                    const d = props.payload;
                    return [`${d.W}W–${d.L}L (${val}%)`, d.team || arcMgr];
                  }}
                  labelFormatter={y => `${y} Season`}
                />
                <Bar dataKey="wpct" radius={[3, 3, 0, 0]}>
                  {chartData.map((d, i) => (
                    <Cell key={i} fill={d.playoffs ? col : col + "55"} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
          <div style={{ color: "#444", fontSize: 11, marginTop: 8 }}>
            <span style={{ color: col }}>■</span> Playoff season &nbsp;
            <span style={{ color: col + "55" }}>■</span> Missed playoffs &nbsp;
            Reference line = .500
          </div>
          {/* Season timeline */}
          <div style={{ display: "flex", flexDirection: "column", gap: 4, marginTop: 14 }}>
            {[...chartData].reverse().map(s => (
              <div key={s.year} style={{ display: "flex", alignItems: "center", gap: mobile ? 8 : 12,
                background: "#080808", borderRadius: 5, padding: mobile ? "5px 8px" : "6px 10px" }}>
                <span style={{ fontFamily: "'Cooper Black',Georgia,serif", fontSize: 16, color: "#2176d2", minWidth: 38 }}>{s.year}</span>
                <span style={{ flex: 1, color: "#555", fontSize: mobile ? 11 : 12, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{s.team}</span>
                <span style={{ color: col, fontSize: 13, fontWeight: 600, minWidth: 48 }}>{s.W}W–{s.L}L</span>
                <span style={{ color: finishColor(s.finish), fontSize: mobile ? 11 : 12, minWidth: 60, textAlign: "right" }}>
                  {s.finish === 1 ? "🏆 Champ" : s.finish === 2 ? "🏁 Finals" : s.finish <= 6 ? `Playoffs` : `#${s.finish}`}
                </span>
              </div>
            ))}
          </div>
        </>
      ) : (
        <div style={{ color: "#555", fontSize: 13 }}>No season data available.</div>
      )}
    </Card>
  );
}

// ── H2H MATRIX SECTION ────────────────────────────────────────────────────────
function H2HMatrixSection() {
  const mobile    = useMobile();
  const { open: openRivalry } = useRivalry();
  const [showAll, setShowAll] = useState(false);
  const allMgrs   = [...new Set(Object.keys(DATA.h2h))].sort();
  const activeMgrs = allMgrs.filter(m => !ALUMNI.has(m));
  const matrixMgrs = showAll ? allMgrs : activeMgrs;

  const thSt = {
    padding: "6px 4px", borderBottom: "1px solid #222222",
    color: "#2176d2", fontFamily: "'Cooper Black',Georgia,serif",
    fontSize: mobile ? 11 : 11, textAlign: "center", whiteSpace: "nowrap",
  };

  return (
    <Card>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 12, flexWrap: "wrap", gap: 8 }}>
        <SectionTitle>🆚 Head-to-Head Matrix</SectionTitle>
        <ToggleBtn active={showAll} onToggle={() => setShowAll(s => !s)}
          label={showAll ? "👁️ Show All" : "👁️ Active Only"} />
      </div>
      <div style={{ fontSize: mobile ? 12 : 12, color: "#555", marginBottom: 12 }}>
        Each cell shows W–L from the <span style={{ color: "#2176d2" }}>row manager's</span> perspective. 🟢 winning &nbsp;🔴 losing &nbsp;⚪ even
      </div>
      <div style={{ overflowX: "auto" }}>
        <table style={{ borderCollapse: "collapse", fontSize: mobile ? 11 : 11 }}>
          <thead>
            <tr>
              <th style={{ ...thSt, textAlign: "left", minWidth: mobile ? 70 : 100, paddingLeft: 8 }}>Manager</th>
              {matrixMgrs.map(m => (
                <th key={m} style={{ ...thSt, minWidth: mobile ? 28 : 38 }}>
                  <div style={{ writingMode: "vertical-rl", transform: "rotate(180deg)",
                    color: getColor(m), fontSize: mobile ? 11 : 11, padding: "4px 0" }}>
                    {firstName(m)}
                  </div>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {matrixMgrs.map((rowMgr, ri) => {
              const rec = DATA.h2h[rowMgr] || {};
              const rowCol = getColor(rowMgr);
              return (
                <tr key={rowMgr} style={{ borderBottom: "1px solid #1a1a1a",
                  background: ri % 2 === 0 ? "transparent" : "#080808",
                  opacity: ALUMNI.has(rowMgr) ? 0.6 : 1 }}>
                  <td style={{ padding: mobile ? "5px 4px 5px 8px" : "6px 6px 6px 10px",
                    fontWeight: 600, color: rowCol, whiteSpace: "nowrap", fontSize: mobile ? 10 : 12 }}>
                    {firstName(rowMgr)}
                  </td>
                  {matrixMgrs.map(colMgr => {
                    if (colMgr === rowMgr) return (
                      <td key={colMgr} style={{ background: "#080808", textAlign: "center",
                        padding: mobile ? "5px 2px" : "6px 4px", color: "#222222", fontSize: 11 }}>—</td>
                    );
                    const r = rec[colMgr];
                    if (!r || (r.W === 0 && r.L === 0)) return (
                      <td key={colMgr} style={{ textAlign: "center", padding: mobile ? "5px 2px" : "6px 4px", color: "#222222" }}>—</td>
                    );
                    const winning = r.W > r.L;
                    const even    = r.W === r.L;
                    const cellBg  = winning ? "#0d2218" : even ? "#1a1a1a" : "#200d0d";
                    const cellCol = winning ? "#2ecc71"  : even ? "#aaa"    : "#2176d2";
                    return (
                      <td key={colMgr}
                        onClick={e => openRivalry(rowMgr, colMgr, { x: e.clientX, y: e.clientY })}
                        style={{ textAlign: "center", padding: mobile ? "5px 2px" : "6px 4px",
                          background: cellBg, color: cellCol, fontWeight: 600,
                          fontSize: mobile ? 11 : 11, whiteSpace: "nowrap",
                          cursor: "pointer", transition: "filter 0.1s" }}
                        onMouseEnter={e => e.currentTarget.style.filter = "brightness(1.4)"}
                        onMouseLeave={e => e.currentTarget.style.filter = "brightness(1)"}>
                        {r.W}–{r.L}
                      </td>
                    );
                  })}
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      <div style={{ color: "#444", fontSize: mobile ? 11 : 11, marginTop: 10, paddingTop: 8, borderTop: "1px solid #1a1a1a" }}>
        All-time regular season + playoff matchups · 🟢 winning record &nbsp;🔴 losing &nbsp;⚪ even
      </div>
    </Card>
  );
}

