// ── DRAMA INDEX SECTION ─────────────────────────────────────────────────────
// ── DRAMA INDEX SECTION ───────────────────────────────────────────────────
function DramaSection() {
  const mobile = useMobile();
  const { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
          Cell, ReferenceLine, RadarChart, Radar, PolarGrid, PolarAngleAxis } = Recharts;

  const [dramaTab,  setDramaTab]  = useState("rankings");
  const [dramaSort, setDramaSort] = useState("boPct");
  const [dramaMgr,  setDramaMgr]  = useState("Ross Van Groningen");
  const [gameView,  setGameView]  = useState("blowouts");
  const [alumniShow,setAlumniShow]= useState(false);

  const allMgrNames  = Object.keys(DATA.dramaData).sort();
  const activeMgrs   = allMgrNames.filter(m => !ALUMNI.has(m));
  const alumniMgrs   = allMgrNames.filter(m =>  ALUMNI.has(m));

  const dramaList = Object.entries(DATA.dramaData)
    .map(([m, d]) => ({ mgr: m, ...d }))
    .filter(d => d.games >= 10 && (alumniShow || !ALUMNI.has(d.mgr)));

  const sorted = [...dramaList].sort((a, b) => {
    if (dramaSort === "nbPct")     return b.nbPct - a.nbPct;
    if (dramaSort === "avgMargin") return b.avgMargin - a.avgMargin;
    return b.boPct - a.boPct;
  });

  // Drama score = weighted combo of blowout%, nail-biter%, avgMargin
  const dramaScore = d => parseFloat(((d.boPct * 40) + (d.nbPct * 30) + ((d.avgMargin / 30) * 30)).toFixed(1));
  const withScore  = sorted.map(d => ({ ...d, score: dramaScore(d) }));
  const byScore    = [...withScore].sort((a, b) => b.score - a.score);
  const leagueBO   = dramaList.reduce((s, d) => s + d.boPct, 0) / dramaList.length;
  const leagueNB   = dramaList.reduce((s, d) => s + d.nbPct, 0) / dramaList.length;
  const leagueAM   = dramaList.reduce((s, d) => s + d.avgMargin, 0) / dramaList.length;

  const mgrDrama = DATA.dramaData[dramaMgr];

  // YoY drama: spread between high and low scores each year
  const yoyDrama = DATA.yoyScoring.map(y => ({
    year: y.year,
    spread: parseFloat((y.high - y.low).toFixed(1)),
    avg: y.avg,
    high: y.high,
    low: y.low,
  }));

  const TabBtn = ({ k, label }) => (
    <button onClick={() => setDramaTab(k)} style={{
      background: dramaTab === k ? "#2176d2" : "#1a1a1a",
      color: dramaTab === k ? "#fff" : "#aaa",
      border: `1px solid ${dramaTab === k ? "#2176d2" : "#333"}`,
      borderRadius: 6, padding: mobile ? "6px 10px" : "7px 16px",
      cursor: "pointer", fontSize: mobile ? 13 : 13, whiteSpace: "nowrap", flexShrink: 0,
    }}>{label}</button>
  );

  const SortBtn = ({ k, label }) => (
    <button onClick={() => setDramaSort(k)} style={{
      background: dramaSort === k ? "#2176d2" : "#1a1a1a",
      color: dramaSort === k ? "#fff" : "#aaa",
      border: `1px solid ${dramaSort === k ? "#2176d2" : "#333"}`,
      borderRadius: 6, padding: "5px 12px",
      cursor: "pointer", fontSize: mobile ? 10 : 12, whiteSpace: "nowrap",
    }}>{label}</button>
  );

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
      {/* Header */}
      <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", borderBottom: "1px solid #222222", paddingBottom: 12 }}>
        <div style={{ fontFamily: "'Cooper Black',Georgia,serif", fontSize: mobile ? 16 : 20, color: "#e9c46a", letterSpacing: 2, flex: 1 }}>
          🎢 Chaos Meter
        </div>
        <div style={{ fontSize:13, color:"#555", marginBottom:8, marginTop:-4 }}>Who plays in blowouts vs. nail-biters — and how wild their average game is.</div>
        <ToggleBtn active={alumniShow} onToggle={() => setAlumniShow(s => !s)} label={alumniShow ? "👁️ Show All" : "👁️ Active Only"} />
      </div>

      {/* Sub-nav */}
      <div style={{ display: "flex", gap: 6, flexWrap: "nowrap", overflowX: "auto", scrollbarWidth: "none" }}>
        <TabBtn k="rankings"  label="📐 Rankings" />
        <TabBtn k="games"     label="🎬 Greatest Games" />
        <TabBtn k="spotlight" label="👤 My Games" />
        <TabBtn k="yoy"       label="🗓️ Year by Year" />
      </div>

      {/* ── RANKINGS ── */}
      {dramaTab === "rankings" && (
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          {/* Hero callout cards */}
          <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
            {(() => {
              const mostBO  = [...dramaList].sort((a,b) => b.boPct - a.boPct)[0];
              const mostNB  = [...dramaList].sort((a,b) => b.nbPct - a.nbPct)[0];
              const biggest = [...dramaList].sort((a,b) => b.avgMargin - a.avgMargin)[0];
              const tightest= [...dramaList].sort((a,b) => a.avgMargin - b.avgMargin)[0];
              return [
                { label:"💥 Most Blowouts",    d: mostBO,   accent:"#2176d2", stat:`${(mostBO.boPct*100).toFixed(1)}%`,    sub:"of games decided by 30+" },
                { label:"🤏 Most Nail-biters", d: mostNB,   accent:"#2a9d8f", stat:`${(mostNB.nbPct*100).toFixed(1)}%`,    sub:"of games decided by <10" },
                { label:"📏 Widest Margins",   d: biggest,  accent:"#f4a261", stat:`${biggest.avgMargin} pts`,             sub:"avg winning margin" },
                { label:"🔬 Tightest Games",   d: tightest, accent:"#e9c46a", stat:`${tightest.avgMargin} pts`,            sub:"avg winning margin" },
              ].map(({ label, d, accent, stat, sub }) => (
                <div key={label} style={{ flex: 1, minWidth: mobile ? "calc(50% - 5px)" : 150,
                  background: "#0a0a0a", border: `1px solid ${accent}44`,
                  borderLeft: `4px solid ${accent}`, borderRadius: 8, padding: "12px 14px" }}>
                  <div style={{ fontSize: 11, color: accent, fontFamily: "'Cooper Black',Georgia,serif", letterSpacing: 1.5, marginBottom: 4 }}>{label}</div>
                  <div style={{ color: getColor(d.mgr), fontWeight: 600, fontSize: mobile ? 12 : 13, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}><MgrName name={d.mgr} /></div>
                  <div style={{ color: accent, fontFamily: "'Cooper Black',Georgia,serif", fontSize: 22, marginTop: 2 }}>{stat}</div>
                  <div style={{ color: "#444", fontSize: 11, marginTop: 2 }}>{sub}</div>
                </div>
              ));
            })()}
          </div>

          <Card>
            <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", marginBottom: 12 }}>
              <SectionTitle>Manager Drama Rankings</SectionTitle>
              <div style={{ display: "flex", gap: 6, marginLeft: "auto", flexWrap: "wrap" }}>
                <SortBtn k="boPct"     label="💥 Blowout %" />
                <SortBtn k="nbPct"     label="🤏 Nail-biter %" />
                <SortBtn k="avgMargin" label="📏 Avg Margin" />
              </div>
            </div>
            <div style={{ fontSize: mobile ? 13 : 11, color: "#555", marginBottom: 12 }}>
              Blowout = margin &gt;30 pts · Nail-biter = margin &lt;10 pts · Min 10 games · League avg: {(leagueBO*100).toFixed(1)}% blowout / {(leagueNB*100).toFixed(1)}% nail-biter
            </div>

            {/* Chart */}
            {/* Table */}
            {mobile ? (
              <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                {sorted.map((d, i) => (
                  <div key={d.mgr} style={{ background: i%2===0?"#0d0d0d":"#1a1a1a", borderRadius: 6, padding: "9px 10px" }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
                      <span style={{ color: "#555", fontFamily: "'Cooper Black',Georgia,serif", fontSize: 14, minWidth: 24 }}>{rank(i)}</span>
                      <span style={{ color: getColor(d.mgr), fontWeight: 600, fontSize: mobile ? 14 : 13, flex: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{mgr(d.mgr)}</span>
                      <span style={{ color: "#555", fontSize: mobile ? 13 : 11 }}>{d.games}g</span>
                    </div>
                    <div style={{ display: "flex", gap: 12, fontSize: mobile ? 13 : 11 }}>
                      <span>💥 <b style={{ color: "#2176d2" }}>{(d.boPct*100).toFixed(1)}%</b></span>
                      <span>🤏 <b style={{ color: "#2a9d8f" }}>{(d.nbPct*100).toFixed(1)}%</b></span>
                      <span>📏 <b style={{ color: "#e9c46a" }}>{d.avgMargin}</b></span>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div style={{ overflowX: "auto" }}>
                <table style={{ width: "100%", borderCollapse: "collapse", fontSize: mobile ? 14 : 13 }}>
                  <thead><tr>
                    {[["#",""],["Manager",""],["Games",""],["💥 Blowout%","boPct"],["Blowouts",""],["🤏 Nail-biter%","nbPct"],["Nail-biters",""],["📏 Avg Margin","avgMargin"]].map(([h, k]) => (
                      <th key={h} onClick={() => k && setDramaSort(k)} style={{
                        textAlign: "left", padding: mobile ? "5px 7px" : "8px 10px", borderBottom: "1px solid #222222",
                        color: dramaSort === k ? "#e9c46a" : "#2176d2",
                        fontFamily: "'Cooper Black',Georgia,serif", letterSpacing: 1, fontSize: mobile ? 14 : 13,
                        cursor: k ? "pointer" : "default", whiteSpace: "nowrap",
                      }}>{h}{dramaSort === k ? " ▼" : ""}</th>
                    ))}
                  </tr></thead>
                  <tbody>
                    {sorted.map((d, i) => {
                      const aboveBO = d.boPct > leagueBO;
                      const aboveNB = d.nbPct > leagueNB;
                      return (
                        <tr key={d.mgr} style={{ background: i%2===0?"#0d0d0d":"#1a1a1a" }}>
                          <td style={{ padding:mobile ? "5px 7px" : "8px 10px", borderBottom:"1px solid #1a1a1a", color: i<3?"#e9c46a":"#555", fontFamily:"'Cooper Black',Georgia,serif", fontSize:15 }}>{rank(i)}</td>
                          <td style={{ padding:mobile ? "5px 7px" : "8px 10px", borderBottom:"1px solid #1a1a1a" }}><MgrName name={d.mgr} /></td>
                          <td style={{ padding:mobile ? "5px 7px" : "8px 10px", borderBottom:"1px solid #1a1a1a", color:"#555", fontSize:12 }}>{d.games}</td>
                          <td style={{ padding:mobile ? "5px 7px" : "8px 10px", borderBottom:"1px solid #1a1a1a" }}>
                            <div style={{ display:"flex", alignItems:"center", gap:6 }}>
                              <div style={{ width:50, height:5, background:"#181818", borderRadius:3, overflow:"hidden" }}>
                                <div style={{ width:`${Math.min(d.boPct/0.55*100,100)}%`, height:"100%", background:"#2176d2", borderRadius:3 }} />
                              </div>
                              <span style={{ color: aboveBO?"#2176d2":"#555" }}>{(d.boPct*100).toFixed(1)}%</span>
                            </div>
                          </td>
                          <td style={{ padding:mobile ? "5px 7px" : "8px 10px", borderBottom:"1px solid #1a1a1a", color:"#555", fontSize:12 }}>{d.blowouts}</td>
                          <td style={{ padding:mobile ? "5px 7px" : "8px 10px", borderBottom:"1px solid #1a1a1a" }}>
                            <div style={{ display:"flex", alignItems:"center", gap:6 }}>
                              <div style={{ width:50, height:5, background:"#181818", borderRadius:3, overflow:"hidden" }}>
                                <div style={{ width:`${Math.min(d.nbPct/0.20*100,100)}%`, height:"100%", background:"#2a9d8f", borderRadius:3 }} />
                              </div>
                              <span style={{ color: aboveNB?"#2a9d8f":"#555" }}>{(d.nbPct*100).toFixed(1)}%</span>
                            </div>
                          </td>
                          <td style={{ padding:mobile ? "5px 7px" : "8px 10px", borderBottom:"1px solid #1a1a1a", color:"#555", fontSize:12 }}>{d.nailbiters}</td>
                          <td style={{ padding:mobile ? "5px 7px" : "8px 10px", borderBottom:"1px solid #1a1a1a" }}>
                            <span style={{ color:"#e9c46a", fontFamily:"'Cooper Black',Georgia,serif", fontSize:15 }}>{d.avgMargin}</span>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </Card>
        </div>
      )}

      {/* ── GREATEST GAMES ── */}
      {dramaTab === "games" && (
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          <div style={{ display: "flex", gap: 6 }}>
            {[["blowouts","💥 Blowout Games"],["nailbiters","🤏 Closest Games"]].map(([k,l]) => (
              <button key={k} onClick={() => setGameView(k)} style={{
                background: gameView===k ? "#2176d2" : "#1a1a1a",
                color: gameView===k ? "#fff" : "#aaa",
                border: `1px solid ${gameView===k?"#2176d2":"#333"}`,
                borderRadius: 6, padding: "7px 16px", cursor: "pointer", fontSize: mobile?11:13,
              }}>{l}</button>
            ))}
          </div>

          {(() => {
            const games = gameView === "blowouts" ? DATA.biggestBlowouts : DATA.closestMatchups;
            const accentW = gameView === "blowouts" ? "#2176d2" : "#2a9d8f";
            const accentL = gameView === "blowouts" ? "#555" : "#2176d2";
            return (
              <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
                {games.map((g, i) => (
                  <div key={i} style={{
                    background: i===0 ? "#150a0a" : i%2===0?"#0d0d0d":"#1a1a1a",
                    borderRadius: 8, padding: mobile?"10px 12px":"12px 16px",
                    border: i===0 ? `1px solid ${accentW}44` : "1px solid transparent",
                  }}>
                    {/* Game header */}
                    <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:6 }}>
                      <span style={{ fontSize:11, color:"#555", fontFamily:"'Cooper Black',Georgia,serif", letterSpacing:1 }}>
                        <YearSpan year={g.Year} /> WK{g.Week} · {g.Teams}-team · {g.PPR===0?"0PPR":g.PPR===0.5?"Half-PPR":"Full PPR"}
                      </span>
                      <span style={{
                        fontFamily:"'Cooper Black',Georgia,serif", fontSize: mobile?18:22,
                        color: gameView==="blowouts" ? "#2176d2" : "#2a9d8f",
                      }}>
                        {gameView==="blowouts" ? `+${g.Margin}` : `±${g.Margin}`} pts
                      </span>
                    </div>
                    {/* Matchup */}
                    <div style={{ display:"flex", alignItems:"center", gap: mobile?8:16, flexWrap: mobile?"wrap":"nowrap" }}>
                      {/* Winner */}
                      <div style={{ flex:1, minWidth:0 }}>
<MgrSpan name={g.Winner} style={{ fontWeight:600, fontSize:mobile?13:14, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap", display:"block" }}>
{g.Winner}</MgrSpan>

                        <div style={{ color:"#555", fontSize:11, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap", fontStyle:"italic" }}>
                          {g.WinnerTeam}
                        </div>
                      </div>
                      {/* Scores */}
                      <div style={{ display:"flex", alignItems:"center", gap:8, flexShrink:0 }}>
                        <span style={{ fontFamily:"'Cooper Black',Georgia,serif", fontSize: mobile?20:26, color:accentW }}>{g.WinnerPts}</span>
                        <span style={{ color:"#333", fontSize:14 }}>vs</span>
                        <span style={{ fontFamily:"'Cooper Black',Georgia,serif", fontSize: mobile?20:26, color: gameView==="nailbiters"?"#2176d2":"#444" }}>{g.LoserPts}</span>
                      </div>
                      {/* Loser */}
                      <div style={{ flex:1, minWidth:0, textAlign: mobile?"left":"right" }}>
<MgrSpan name={g.Loser} style={{ fontWeight:600, fontSize:mobile?13:14, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap", display:"block" }}>
{g.Loser}</MgrSpan>

                        <div style={{ color:"#555", fontSize:11, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap", fontStyle:"italic" }}>
                          {g.LoserTeam}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            );
          })()}
        </div>
      )}

      {/* ── MANAGER SPOTLIGHT ── */}
      {dramaTab === "spotlight" && (
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          {/* Manager picker */}
          <div style={{ display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
            <span style={{ color: "#555", fontSize: mobile ? 14 : 13 }}>Manager:</span>
            <div style={{ position: "relative" }}>
              <select value={dramaMgr} onChange={e => setDramaMgr(e.target.value)} style={{
                background: "#1a1a1a", color: "#fff", border: "1px solid #333", borderRadius: 6,
                padding: "7px 32px 7px 12px", fontSize: 14, cursor: "pointer",
                appearance: "none", WebkitAppearance: "none", outline: "none",
              }}>
                <optgroup label="Active">{activeMgrs.map(m => <option key={m} value={m}>{m}</option>)}</optgroup>
                <optgroup label="Alumni 💀🪦⚰️">{alumniMgrs.map(m => <option key={m} value={m}>{m}</option>)}</optgroup>
              </select>
              <span style={{ position:"absolute", right:10, top:"50%", transform:"translateY(-50%)", color:"#2176d2", pointerEvents:"none", fontSize:11 }}>▼</span>
            </div>
          </div>

          {mgrDrama && (() => {
            const d         = mgrDrama;
            const normal    = d.games - d.blowouts - d.nailbiters;
            const normalPct = normal / d.games;
            const mScore    = dramaScore(d);
            const leagueScore = withScore.reduce((s,x) => s + x.score, 0) / withScore.length;
            const rank_pos  = byScore.findIndex(x => x.mgr === dramaMgr) + 1;

            // Breakdown bar data
            const breakdownData = [
              { label: "💥 Blowout",    pct: d.boPct,   count: d.blowouts,   color: "#2176d2" },
              { label: "😐 Normal",     pct: normalPct, count: normal,       color: "#555" },
              { label: "🤏 Nail-biter", pct: d.nbPct,   count: d.nailbiters, color: "#2a9d8f" },
            ];

            // Games involving this manager from blowouts/close lists
            const mgrBlowouts = DATA.biggestBlowouts.filter(g => g.Winner === dramaMgr || g.Loser === dramaMgr).slice(0, 3);
            const mgrClose    = DATA.closestMatchups.filter(g => g.Winner === dramaMgr || g.Loser === dramaMgr).slice(0, 3);

            return (
              <>
                {/* Summary cards */}
                <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
                  {[
                    { label:"Drama Rank",    v: `#${rank_pos}/${byScore.length}`, c: rank_pos<=3?"#e9c46a":"#aaa" },
                    { label:"Drama Score",   v: mScore,                            c: mScore > leagueScore ? "#2176d2" : "#555" },
                    { label:"💥 Blowout%",   v: `${(d.boPct*100).toFixed(1)}%`,   c: "#2176d2" },
                    { label:"🤏 Nail-biter%",v: `${(d.nbPct*100).toFixed(1)}%`,   c: "#2a9d8f" },
                    { label:"Avg Margin",    v: `${d.avgMargin} pts`,             c: "#e9c46a" },
                    { label:"Total Games",   v: d.games,                           c: "#555" },
                  ].map(({ label, v, c }) => (
                    <div key={label} style={{ background:"#0a0a0a", borderRadius:8, padding:"10px 14px", textAlign:"center", flex:1, minWidth: mobile?80:100 }}>
                      <div style={{ fontSize:11, color:"#555", fontFamily:"'Cooper Black',Georgia,serif", letterSpacing:1.5, marginBottom:3 }}>{label}</div>
                      <div style={{ color:c, fontFamily:"'Cooper Black',Georgia,serif", fontSize: mobile?16:20 }}>{v}</div>
                    </div>
                  ))}
                </div>

                {/* Game type breakdown */}
                <Card>
                  <SectionTitle>Game Type Breakdown</SectionTitle>
                  <div style={{ display:"flex", gap:16, alignItems:"center", marginBottom:16 }}>
                    <div style={{ flex:1, display:"flex", flexDirection:"column", gap:6 }}>
                      {breakdownData.map(({ label, pct, count, color }) => (
                        <div key={label}>
                          <div style={{ display:"flex", justifyContent:"space-between", marginBottom:3 }}>
                            <span style={{ color:"#aaa", fontSize:12 }}>{label}</span>
                            <span style={{ color, fontFamily:"'Cooper Black',Georgia,serif", fontSize:14 }}>
                              {(pct*100).toFixed(1)}% <span style={{ color:"#555", fontSize:11 }}>({count})</span>
                            </span>
                          </div>
                          <div style={{ height:8, background:"#181818", borderRadius:4, overflow:"hidden" }}>
                            <div style={{ width:`${pct*100}%`, height:"100%", background:color, borderRadius:4,
                              opacity: 0.85, transition:"width 0.3s" }} />
                          </div>
                        </div>
                      ))}
                    </div>
                    {/* vs league avg comparison */}
                    {!mobile && (
                      <div style={{ width:160, flexShrink:0 }}>
                        <div style={{ fontSize:11, color:"#555", fontFamily:"'Cooper Black',Georgia,serif", letterSpacing:1.5, marginBottom:8, textAlign:"center" }}>VS LEAGUE AVG</div>
                        {[
                          { label:"Blowout%",  mVal:(d.boPct*100).toFixed(1),  lVal:(leagueBO*100).toFixed(1), better: d.boPct > leagueBO,   color:"#2176d2" },
                          { label:"Nail-biter%",mVal:(d.nbPct*100).toFixed(1), lVal:(leagueNB*100).toFixed(1), better: d.nbPct > leagueNB,   color:"#2a9d8f" },
                          { label:"Avg Margin", mVal:d.avgMargin,               lVal:leagueAM.toFixed(1),       better: d.avgMargin > leagueAM,color:"#e9c46a" },
                        ].map(({ label, mVal, lVal, better, color }) => (
                          <div key={label} style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:8, fontSize:11 }}>
                            <span style={{ color:"#555" }}>{label}</span>
                            <span style={{ color, fontFamily:"'Cooper Black',Georgia,serif", fontSize:14 }}>
                              {mVal}%{label==="Avg Margin"?"":""} {better ? "▲" : "▼"}
                            </span>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                </Card>

                {/* Notable games */}
                <div style={{ display:"flex", gap:12, flexWrap:"wrap" }}>
                  {mgrBlowouts.length > 0 && (
                    <div style={{ flex:1, minWidth: mobile?"100%":280 }}>
                      <div style={{ fontSize:11, color:"#2176d2", fontFamily:"'Cooper Black',Georgia,serif", letterSpacing:1.5, marginBottom:8 }}>💥 THEIR BIGGEST BLOWOUTS</div>
                      <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
                        {mgrBlowouts.map((g, i) => {
                          const won = g.Winner === dramaMgr;
                          return (
                            <div key={i} style={{ background:"#0d0d0d", borderRadius:6, padding:mobile ? "6px 8px" : "9px 12px", borderLeft:`3px solid ${won?"#2176d2":"#444"}` }}>
                              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline" }}>
                                <span style={{ color: won?"#2176d2":"#555", fontFamily:"'Cooper Black',Georgia,serif", fontSize:18 }}>
                                  {won ? `W +${g.Margin}` : `L −${g.Margin}`}
                                </span>
                                <span style={{ color:"#555", fontSize:11 }}><YearSpan year={g.Year} /> Wk{g.Week}</span>
                              </div>
                              <div style={{ color:"#777", fontSize:11 }}>
                                vs <span style={{ color: getColor(won?g.Loser:g.Winner) }}>{won?g.Loser:g.Winner}</span>
                                {" · "}{won?g.WinnerPts:g.LoserPts}–{won?g.LoserPts:g.WinnerPts}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  )}

                  {mgrClose.length > 0 && (
                    <div style={{ flex:1, minWidth: mobile?"100%":280 }}>
                      <div style={{ fontSize:11, color:"#2a9d8f", fontFamily:"'Cooper Black',Georgia,serif", letterSpacing:1.5, marginBottom:8 }}>🤏 THEIR CLOSEST GAMES</div>
                      <div style={{ display:"flex", flexDirection:"column", gap:6 }}>
                        {mgrClose.map((g, i) => {
                          const won = g.Winner === dramaMgr;
                          return (
                            <div key={i} style={{ background:"#0d0d0d", borderRadius:6, padding:mobile ? "6px 8px" : "9px 12px", borderLeft:`3px solid ${won?"#2a9d8f":"#555"}` }}>
                              <div style={{ display:"flex", justifyContent:"space-between", alignItems:"baseline" }}>
                                <span style={{ color: won?"#2a9d8f":"#555", fontFamily:"'Cooper Black',Georgia,serif", fontSize:18 }}>
                                  {won ? `W ±${g.Margin}` : `L ±${g.Margin}`}
                                </span>
                                <span style={{ color:"#555", fontSize:11 }}><YearSpan year={g.Year} /> Wk{g.Week}</span>
                              </div>
                              <div style={{ color:"#777", fontSize:11 }}>
                                vs <span style={{ color: getColor(won?g.Loser:g.Winner) }}>{won?g.Loser:g.Winner}</span>
                                {" · "}{won?g.WinnerPts:g.LoserPts}–{won?g.LoserPts:g.WinnerPts}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </div>
                  )}
                </div>
              </>
            );
          })()}
        </div>
      )}

      {/* ── YEAR BY YEAR ── */}
      {dramaTab === "yoy" && (
        <div style={{ display: "flex", flexDirection: "column", gap: 16 }}>
          {/* Callout cards */}
          <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
            {(() => {
              const mostDrama  = yoyDrama.reduce((b, d) => d.spread > b.spread ? d : b);
              const leastDrama = yoyDrama.reduce((b, d) => d.spread < b.spread ? d : b);
              const highScore  = yoyDrama.reduce((b, d) => d.high > b.high ? d : b);
              const lowScore   = yoyDrama.reduce((b, d) => d.low < b.low ? d : b);
              return [
                { label:"🎭 Most Dramatic Season", v: mostDrama.year,  sub:`${mostDrama.spread} pt spread (${mostDrama.high} high / ${mostDrama.low} low)`, c:"#2176d2" },
                { label:"😴 Most Boring Season",   v: leastDrama.year, sub:`${leastDrama.spread} pt spread`, c:"#555" },
                { label:"🚀 All-Time High Score",  v: highScore.high,  sub:`${highScore.year}`,               c:"#81b29a" },
                { label:"💀 All-Time Low Score",   v: lowScore.low,    sub:`${lowScore.year}`,                c:"#2176d2" },
              ].map(({ label, v, sub, c }) => (
                <div key={label} style={{ flex:1, minWidth: mobile?"calc(50% - 5px)":150, background:"#0a0a0a", borderLeft:`4px solid ${c}`, borderRadius:8, padding:"12px 14px" }}>
                  <div style={{ fontSize:11, color:c, fontFamily:"'Cooper Black',Georgia,serif", letterSpacing:1.5, marginBottom:4 }}>{label}</div>
                  <div style={{ color:c, fontFamily:"'Cooper Black',Georgia,serif", fontSize:26 }}>{v}</div>
                  <div style={{ color:"#444", fontSize:11, marginTop:2 }}>{sub}</div>
                </div>
              ));
            })()}
          </div>

          {/* High-low spread chart */}
          <Card>
            <SectionTitle>Weekly Score Spread by Season</SectionTitle>
            <div style={{ fontSize:11, color:"#555", marginBottom:12 }}>High-to-low range each season — wider = more dramatic year.</div>
            <div style={{ height:240 }}>
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={yoyDrama} margin={{ top:4, right:8, left:0, bottom:8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#1e2040" vertical={false} />
                  <XAxis dataKey="year" tick={{ fill:"#666", fontSize:11 }} />
                  <YAxis tick={{ fill:"#666", fontSize:11 }} />
                  <Tooltip
                    contentStyle={{ background:"#0d0d0d", border:"1px solid #333", borderRadius:6 }}
                    content={({ active, payload, label }) => {
                      if (!active || !payload?.length) return null;
                      const d = payload[0].payload;
                      return (
                        <div style={{ background:"#0d0d0d", border:"1px solid #333", borderRadius:6, padding:"10px 12px" }}>
                          <div style={{ color:"#2176d2", fontFamily:"'Cooper Black',Georgia,serif", fontSize:16, marginBottom:4 }}>{label}</div>
                          <div style={{ fontSize:12, color:"#aaa" }}>Spread: <b style={{ color:"#e9c46a" }}>{d.spread} pts</b></div>
                          <div style={{ fontSize:11, color:"#81b29a" }}>High: {d.high}</div>
                          <div style={{ fontSize:11, color:"#2176d2" }}>Low: {d.low}</div>
                          <div style={{ fontSize:11, color:"#e9c46a" }}>Avg: {d.avg}</div>
                        </div>
                      );
                    }} />
                  <Bar dataKey="spread" radius={[3,3,0,0]}>
                    {yoyDrama.map((d, i) => {
                      const maxSpread = Math.max(...yoyDrama.map(x => x.spread));
                      return <Cell key={i} fill="#2176d2" opacity={0.4 + 0.6*(d.spread/maxSpread)} />;
                    })}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </Card>

          {/* Year-by-year table */}
          <Card>
            <SectionTitle>Season Drama Breakdown</SectionTitle>
            {mobile ? (
              <div style={{ display:"flex", flexDirection:"column", gap:4 }}>
                {[...yoyDrama].reverse().map((d, i) => (
                  <div key={d.year} style={{ background:i%2===0?"#0d0d0d":"#1a1a1a", borderRadius:6, padding:mobile ? "6px 8px" : "9px 12px", display:"flex", alignItems:"center", gap:10 }}>
                    <span style={{ fontFamily:"'Cooper Black',Georgia,serif", fontSize:16, color:"#2176d2", minWidth:38 }}>{d.year}</span>
                    <div style={{ flex:1 }}>
                      <div style={{ color:"#e9c46a", fontFamily:"'Cooper Black',Georgia,serif", fontSize:14 }}>{d.spread} pt spread</div>
                      <div style={{ fontSize:11, color:"#555" }}>↑{d.high} avg:{d.avg} ↓{d.low}</div>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div style={{ overflowX:"auto" }}>
                <table style={{ width:"100%", borderCollapse:"collapse", fontSize:13 }}>
                  <thead><tr>
                    {["Year","Avg Score","Week High","Week Low","Spread","Drama Rank"].map(h => (
                      <th key={h} style={{ textAlign:"left", padding:mobile ? "5px 7px" : "8px 10px", borderBottom:"1px solid #222222", color:"#2176d2", fontFamily:"'Cooper Black',Georgia,serif", letterSpacing:1, fontSize:13 }}>{h}</th>
                    ))}
                  </tr></thead>
                  <tbody>
                    {(() => {
                      const ranked = [...yoyDrama].sort((a,b)=>b.spread-a.spread).map((d,i)=>({...d,dramaRank:i+1}));
                      return [...ranked].sort((a,b)=>b.year-a.year).map((d, i) => (
                        <tr key={d.year} style={{ background:i%2===0?"#0d0d0d":"#1a1a1a" }}>
                          <td style={{ padding:mobile ? "5px 7px" : "8px 10px", borderBottom:"1px solid #1a1a1a", color:"#2176d2", fontFamily:"'Cooper Black',Georgia,serif", fontSize:16 }}>{d.year}</td>
                          <td style={{ padding:mobile ? "5px 7px" : "8px 10px", borderBottom:"1px solid #1a1a1a" }}><span style={{ color:"#e9c46a", fontFamily:"'Cooper Black',Georgia,serif", fontSize:15 }}>{d.avg}</span></td>
                          <td style={{ padding:mobile ? "5px 7px" : "8px 10px", borderBottom:"1px solid #1a1a1a", color:"#81b29a" }}>{d.high}</td>
                          <td style={{ padding:mobile ? "5px 7px" : "8px 10px", borderBottom:"1px solid #1a1a1a", color:"#2176d2" }}>{d.low}</td>
                          <td style={{ padding:mobile ? "5px 7px" : "8px 10px", borderBottom:"1px solid #1a1a1a" }}>
                            <div style={{ display:"flex", alignItems:"center", gap:6 }}>
                              <div style={{ width:60, height:5, background:"#181818", borderRadius:3, overflow:"hidden" }}>
                                <div style={{ width:`${(d.spread/Math.max(...yoyDrama.map(x=>x.spread)))*100}%`, height:"100%", background:"#2176d2", borderRadius:3 }} />
                              </div>
                              <span style={{ color:"#f4a261", fontFamily:"'Cooper Black',Georgia,serif", fontSize:14 }}>{d.spread}</span>
                            </div>
                          </td>
                          <td style={{ padding:mobile ? "5px 7px" : "8px 10px", borderBottom:"1px solid #1a1a1a", color: d.dramaRank<=3?"#e9c46a":"#555", fontFamily:"'Cooper Black',Georgia,serif", fontSize:15 }}>
                            {rank(d.dramaRank-1)}
                          </td>
                        </tr>
                      ));
                    })()}
                  </tbody>
                </table>
              </div>
            )}
          </Card>
        </div>
      )}
    </div>
  );
}



